// Content for Plan It (node g22, ages 12-15, Chapter 4): NEW v2 build to GDD 22 (mechanic-embodying), the
// fertility + pregnancy + contraception node (Thread F · Sexual & Reproductive Health). "Your body, your
// timeline, your choice." 85 researched, India-grounded scenarios across the how-it-happens → bust-myths →
// ways-to-prevent → delaying-valid → plan-future → facts-help arc, each encoded as one of the shared v2 play
// actions (strike-rewrite / sort / branch / build / reflect / role-play / match): no binary "tap the right
// card". Lead mechanics: strike-rewrite (bust the dangerous myth ×21), sort (fact vs myth, reliable vs not
// ×16), branch (choose your own pace ×11). Teaches: the plain biology of how pregnancy can begin, busting the
// dangerous myths (first time, withdrawal, douching, 'safe days', orgasm), an age-appropriate OVERVIEW of
// prevention (abstinence is fully reliable & respected; condoms; ask a doctor about the rest), that DELAYING
// IS FULLY VALID and respected (your pace against 'everyone's doing it' / 'if you loved me'), planning your
// future, and getting facts from a doctor/trusted adult, not rumours. School-comfort: matter-of-fact,
// NON-EXPLICIT, values-first, non-judgmental. GATED at the path layer (age band). Builds on g14 (The Amazing
// Journey); prereq g39. Rendered by the shared engine (components/games/v2-engine.tsx). gameId "plan-it".
// DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // How pregnancy happens
  {"id":"pl-001","cat":"how-it-happens","type":"build","hook":"Build the basic chain of how a pregnancy can begin.","prompt":"Put the steps in order.","pieces":["an egg is released (ovulation)","sperm meets the egg","the egg is fertilised","it settles in the uterus"],"mode":"sequence","key":["an egg is released (ovulation)","sperm meets the egg","the egg is fertilised","it settles in the uterus"],"relearn":"Pregnancy begins when sperm fertilises an egg, which then settles in the uterus.","persona":"any","source":"reproduction (UNESCO 6.2)"},
  {"id":"pl-002","cat":"how-it-happens","type":"strike-rewrite","hook":"\"Pregnancy is random and mysterious.\"","myth":{"un":"Pregnancy just happens randomly and mysteriously.","re":"Pregnancy follows clear biology: sperm meeting an egg.","why":"Knowing the rules lets you understand and prevent it."},"relearn":"Pregnancy isn't a mystery; it follows clear, knowable biology.","persona":"any","source":"reproduction"},
  {"id":"pl-002b","cat":"how-it-happens","type":"strike-rewrite","hook":"\"You can get pregnant on any day, equally, all month.\"","myth":{"un":"The chance is exactly the same every single day.","re":"There's a fertile window around ovulation, but sperm live up to 5 days, so it's hard to predict.","why":"Cycles vary, which is why 'safe days' alone are unreliable."},"relearn":"There's a fertile window, but it's hard to predict, so 'safe days' aren't reliable.","persona":"any","source":"fertility window"},
  {"id":"pl-003","cat":"how-it-happens","type":"sort","hook":"Sort: needed for a pregnancy, or not?","items":[{"id":"a","text":"An egg"},{"id":"b","text":"Sperm"},{"id":"c","text":"An orgasm by the girl"},{"id":"d","text":"A full moon"},{"id":"e","text":"A special 'lucky' day"},{"id":"f","text":"The egg settling in the uterus"}],"bins":[{"id":"needed","label":"Needed","valence":"pos"},{"id":"not","label":"Not needed","valence":"neg"}],"key":{"a":"needed","b":"needed","c":"not","d":"not","e":"not","f":"needed"},"relearn":"Pregnancy needs sperm and egg meeting, then settling; it doesn't need orgasm or luck.","persona":"any","source":"reproduction facts"},
  {"id":"pl-004","cat":"how-it-happens","type":"sort","hook":"Sort: a real fact about fertility, or made up?","items":[{"id":"a","text":"Sperm can live a few days inside the body"},{"id":"b","text":"Bodies can make babies once puberty starts"},{"id":"c","text":"You can tell the exact safe day easily"},{"id":"d","text":"Only adults over 20 can get pregnant"},{"id":"e","text":"There's a fertile window around ovulation"},{"id":"f","text":"Washing afterwards stops a pregnancy"}],"bins":[{"id":"fact","label":"Fact","valence":"pos"},{"id":"madeup","label":"Made up","valence":"neg"}],"key":{"a":"fact","b":"fact","c":"madeup","d":"madeup","e":"fact","f":"madeup"},"relearn":"Once puberty starts, pregnancy is possible; 'safe days' aren't easy to know.","persona":"any","source":"fertility facts"},
  {"id":"pl-005","cat":"how-it-happens","type":"sort","hook":"Sort: about the body becoming fertile.","items":[{"id":"a","text":"Periods can signal fertility has begun"},{"id":"b","text":"Sperm production begins in puberty"},{"id":"c","text":"Fertility waits until marriage"},{"id":"d","text":"You must 'feel' fertile to be fertile"},{"id":"e","text":"Puberty makes pregnancy biologically possible"},{"id":"f","text":"Fertility only starts at a fixed birthday"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"true","c":"false","d":"false","e":"true","f":"false"},"relearn":"Fertility begins with puberty's changes, not at any particular life event.","persona":"any","source":"fertility / puberty"},
  {"id":"pl-006","cat":"how-it-happens","type":"match","hook":"Match the part to its role in reproduction.","pairs":[{"left":"Egg","right":"Released from the ovary"},{"left":"Sperm","right":"Can fertilise the egg"},{"left":"Uterus","right":"Where a pregnancy grows"},{"left":"Ovary","right":"Stores and releases eggs"},{"left":"Fallopian tube","right":"Where egg and sperm can meet"}],"relearn":"Each part, like egg, sperm, ovary, tube or uterus, plays a clear role.","persona":"any","source":"reproduction"},
  {"id":"pl-007","cat":"how-it-happens","type":"match","hook":"Match the term to its plain meaning.","pairs":[{"left":"Ovulation","right":"An egg is released"},{"left":"Fertilisation","right":"Sperm joins the egg"},{"left":"Fertile window","right":"Days pregnancy is likeliest"},{"left":"Conception","right":"A pregnancy begins"},{"left":"Implantation","right":"The egg settles in the uterus"}],"relearn":"Knowing the basic terms makes the facts clear, not scary.","persona":"any","source":"vocabulary"},
  {"id":"pl-008","cat":"how-it-happens","type":"match","hook":"Match the fact to why it matters.","pairs":[{"left":"Sperm live up to ~5 days","right":"'Safe days' are unreliable"},{"left":"Cycles vary a lot","right":"Timing is hard to predict"},{"left":"First time counts","right":"A chance is there from the start"},{"left":"Orgasm isn't required","right":"Pregnancy can still happen"},{"left":"Puberty has begun","right":"The body can already conceive"}],"relearn":"These facts are exactly why simple 'timing' tricks fail.","persona":"any","source":"fertility facts"},
  {"id":"pl-009","cat":"how-it-happens","type":"build","hook":"Build the 'when can it happen?' summary.","prompt":"Assemble the true points.","pieces":["once puberty has begun","when sperm can reach an egg","even the first time","timing is hard to predict"],"mode":"assemble","key":["once puberty has begun","when sperm can reach an egg","even the first time","timing is hard to predict"],"relearn":"Pregnancy is possible once puberty starts, any time sperm can reach an egg.","persona":"any","source":"fertility summary"},
  {"id":"pl-010","cat":"how-it-happens","type":"reflect","hook":"Lensy: knowing how it actually works puts you in charge, not in the dark. Feel that?","prompt":"What do you think?","options":["Yes","Knowledge is power","Less confusing now"],"affirm":"Understanding the biology means no one can mislead you about it.","relearn":"Understanding how pregnancy works puts you in charge of the facts.","persona":"any","source":"agency"},
  {"id":"pl-011","cat":"how-it-happens","type":"reflect","hook":"Lensy: this is just biology, calm and factual, nothing to be embarrassed about. Agree?","prompt":"What do you think?","options":["Yes","It's just facts","Good to know plainly"],"affirm":"Bodies and biology are normal; learning them is simply being informed.","relearn":"How reproduction works is normal biology, learned calmly.","persona":"any","source":"normalising"},
  // Bust the dangerous myths
  {"id":"pl-012","cat":"bust-myths","type":"strike-rewrite","hook":"\"You can't get pregnant the first time.\"","myth":{"un":"You can't get pregnant the first time.","re":"Pregnancy is possible the very first time, every time carries a chance.","why":"The body doesn't get a 'free pass' on the first occasion."},"relearn":"You can get pregnant the first time; there's no 'free pass'.","persona":"any","source":"myth-busting (verified)"},
  {"id":"pl-013","cat":"bust-myths","type":"strike-rewrite","hook":"\"You can't get pregnant during your period.\"","myth":{"un":"It's impossible to get pregnant during a period.","re":"It's less likely but still possible, especially with shorter or irregular cycles.","why":"Sperm can live for days and cycles vary."},"relearn":"Pregnancy during a period is less likely but still possible.","persona":"Riya","source":"myth-busting (verified)"},
  {"id":"pl-014","cat":"bust-myths","type":"strike-rewrite","hook":"\"Pulling out in time prevents pregnancy.\"","myth":{"un":"Pulling out (withdrawal) reliably prevents pregnancy.","re":"Withdrawal is unreliable; fluid before climax can contain sperm.","why":"About 1 in 5 who rely on it each year have an unplanned pregnancy."},"relearn":"Withdrawal is unreliable; it isn't a dependable method.","persona":"any","source":"myth-busting (verified)"},
  {"id":"pl-015","cat":"bust-myths","type":"strike-rewrite","hook":"\"If she doesn't orgasm, she can't get pregnant.\"","myth":{"un":"Pregnancy needs the girl to orgasm.","re":"Orgasm has nothing to do with whether an egg gets fertilised.","why":"Fertilisation is about sperm meeting egg, not pleasure."},"relearn":"Orgasm isn't required for pregnancy; that myth is false.","persona":"any","source":"myth-busting (verified)"},
  {"id":"pl-016","cat":"bust-myths","type":"strike-rewrite","hook":"\"Washing or douching afterwards stops pregnancy.\"","myth":{"un":"Washing or douching after sex prevents pregnancy.","re":"It does not; sperm can already be on the way.","why":"You can't rinse away the possibility."},"relearn":"Douching or washing afterwards does not prevent pregnancy.","persona":"any","source":"myth-busting (verified)"},
  {"id":"pl-017","cat":"bust-myths","type":"strike-rewrite","hook":"\"Standing up or jumping afterwards prevents it.\"","myth":{"un":"Position, standing or jumping afterwards prevents pregnancy.","re":"None of these affect whether sperm reaches an egg.","why":"Gravity tricks are myths."},"relearn":"Position and 'tricks' afterwards don't prevent pregnancy.","persona":"any","source":"myth-busting"},
  {"id":"pl-018","cat":"bust-myths","type":"strike-rewrite","hook":"\"You're too young for your body to get pregnant.\"","myth":{"un":"A teen's body is too young to get pregnant.","re":"Once puberty's changes begin, pregnancy is biologically possible.","why":"Biology doesn't wait for a 'ready' age."},"relearn":"Once puberty begins, pregnancy is biologically possible.","persona":"any","source":"myth-busting"},
  {"id":"pl-019","cat":"bust-myths","type":"strike-rewrite","hook":"\"Only certain 'types' of people need to know this.\"","myth":{"un":"Only some people need to understand pregnancy and prevention.","re":"Everyone benefits from accurate facts, whatever their plans.","why":"Knowledge protects everyone, including future-you."},"relearn":"Everyone benefits from knowing the facts, whatever their plans.","persona":"any","source":"access to info"},
  {"id":"pl-020","cat":"bust-myths","type":"strike-rewrite","hook":"\"Learning this means I'm being pushed to do something.\"","myth":{"un":"Learning about this is pressure to have sex.","re":"Knowing the facts actually helps people wait and stay safer.","why":"Good information leads to better, often more cautious, choices."},"relearn":"Knowing the facts helps you wait and stay safe; it isn't pressure.","persona":"Veer","source":"CSE evidence"},
  {"id":"pl-021","cat":"bust-myths","type":"strike-rewrite","hook":"\"You can tell a 'safe day' just by counting, easily.\"","myth":{"un":"You can always pick a guaranteed 'safe day' by counting.","re":"Cycles vary and sperm live for days, so counting alone is unreliable.","why":"Prediction is much harder than the myth suggests."},"relearn":"'Safe day' counting alone is unreliable for preventing pregnancy.","persona":"any","source":"fertility awareness limits"},
  {"id":"pl-022","cat":"bust-myths","type":"strike-rewrite","hook":"\"Myths from friends are good enough to rely on.\"","myth":{"un":"What friends say about pregnancy is reliable enough.","re":"Friend 'facts' are often myths; check with a doctor or trusted adult.","why":"Rumours cause real, avoidable harm."},"relearn":"Don't rely on friend-rumours; check facts with a doctor or trusted adult.","persona":"any","source":"help-seeking"},
  {"id":"pl-023","cat":"bust-myths","type":"sort","hook":"Sort: dangerous myth, or real fact?","items":[{"id":"a","text":"\"Can't happen the first time\""},{"id":"b","text":"\"Every time carries a chance\""},{"id":"c","text":"\"Pulling out is safe\""},{"id":"d","text":"\"Sperm can live for days\""},{"id":"e","text":"\"Washing afterwards stops it\""},{"id":"f","text":"\"Once puberty starts, it's possible\""}],"bins":[{"id":"myth","label":"Dangerous myth","valence":"neg"},{"id":"fact","label":"Real fact","valence":"pos"}],"key":{"a":"myth","b":"fact","c":"myth","d":"fact","e":"myth","f":"fact"},"relearn":"The 'first time', 'pulling out' and 'washing' beliefs are dangerous myths.","persona":"any","source":"myth-busting"},
  {"id":"pl-024","cat":"bust-myths","type":"sort","hook":"Sort: reliable, or not reliable, for preventing pregnancy?","items":[{"id":"a","text":"Not having sex"},{"id":"b","text":"Withdrawal"},{"id":"c","text":"Douching"},{"id":"d","text":"A condom used correctly"},{"id":"e","text":"Counting 'safe days' alone"},{"id":"f","text":"Jumping up afterwards"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"not","label":"Not reliable","valence":"neg"}],"key":{"a":"reliable","b":"not","c":"not","d":"reliable","e":"not","f":"not"},"relearn":"Not having sex is fully reliable; a correctly used condom is reliable; the rest are not.","persona":"any","source":"prevention facts"},
  {"id":"pl-025","cat":"bust-myths","type":"sort","hook":"Sort: where good pregnancy facts come from.","items":[{"id":"a","text":"A doctor or health worker"},{"id":"b","text":"A random forwarded message"},{"id":"c","text":"A trusted adult or counsellor"},{"id":"d","text":"Locker-room rumours"},{"id":"e","text":"A school health teacher"},{"id":"f","text":"A viral reel with no source"}],"bins":[{"id":"reliable","label":"Reliable source","valence":"pos"},{"id":"not","label":"Unreliable","valence":"neg"}],"key":{"a":"reliable","b":"not","c":"reliable","d":"not","e":"reliable","f":"not"},"relearn":"Trust doctors, health teachers and trusted adults for facts, not rumours or viral reels.","persona":"any","source":"help-seeking"},
  // Ways it's prevented
  {"id":"pl-026","cat":"ways-to-prevent","type":"sort","hook":"Sort: how well does each prevent pregnancy?","items":[{"id":"a","text":"Not having sex"},{"id":"b","text":"A condom, used correctly"},{"id":"c","text":"Hoping for the best"},{"id":"d","text":"Withdrawal"},{"id":"e","text":"A doctor-set-up method"},{"id":"f","text":"Washing afterwards"}],"bins":[{"id":"works","label":"Reliable","valence":"pos"},{"id":"weak","label":"Unreliable","valence":"neg"}],"key":{"a":"works","b":"works","e":"works","c":"weak","d":"weak","f":"weak"},"relearn":"Not having sex is fully reliable; condoms used right and a doctor's method work; hoping, withdrawal and washing don't.","persona":"any","source":"prevention"},
  {"id":"pl-027","cat":"ways-to-prevent","type":"sort","hook":"Sort: also protects against STIs, or only pregnancy?","items":[{"id":"a","text":"Condoms"},{"id":"b","text":"The pill"},{"id":"c","text":"Not having sex"},{"id":"d","text":"Most other methods"},{"id":"e","text":"An implant"},{"id":"f","text":"An injection"}],"bins":[{"id":"both","label":"Pregnancy + STIs","valence":"pos"},{"id":"pregonly","label":"Mainly pregnancy","valence":"neutral"}],"key":{"a":"both","c":"both","b":"pregonly","d":"pregonly","e":"pregonly","f":"pregonly"},"relearn":"Condoms and not having sex also reduce STIs; the pill, implant, injection and most methods mainly prevent pregnancy.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-028","cat":"ways-to-prevent","type":"sort","hook":"Sort: a real method a doctor can explain, or a myth?","items":[{"id":"a","text":"Condoms"},{"id":"b","text":"The pill"},{"id":"c","text":"Crossing fingers"},{"id":"d","text":"A lucky charm"},{"id":"e","text":"An implant"},{"id":"f","text":"A herbal 'cure'"}],"bins":[{"id":"real","label":"Real method","valence":"pos"},{"id":"myth","label":"Not a method","valence":"neg"}],"key":{"a":"real","b":"real","e":"real","c":"myth","d":"myth","f":"myth"},"relearn":"Condoms, the pill and an implant are real methods a doctor explains; charms, luck and 'cures' aren't.","persona":"any","source":"prevention overview"},
  {"id":"pl-029","cat":"ways-to-prevent","type":"sort","hook":"Sort: true about prevention, or false?","items":[{"id":"a","text":"Several methods exist"},{"id":"b","text":"A doctor can explain options"},{"id":"c","text":"There's only one method"},{"id":"d","text":"Methods never need correct use"},{"id":"e","text":"Prevention is a shared job"},{"id":"f","text":"Luck counts as a method"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"true","e":"true","c":"false","d":"false","f":"false"},"relearn":"Many methods exist, used correctly, and prevention is shared; 'one method', 'no correct use' and 'luck' are false.","persona":"any","source":"prevention overview"},
  {"id":"pl-030","cat":"ways-to-prevent","type":"match","hook":"Match the method to a plain fact about it.","pairs":[{"left":"Not having sex","right":"Fully prevents pregnancy"},{"left":"Condom","right":"Prevents pregnancy and STIs"},{"left":"The pill","right":"A doctor explains how it's used"},{"left":"Withdrawal","right":"Unreliable on its own"},{"left":"A lucky charm","right":"Not a method at all"}],"relearn":"Each method has clear facts; waiting and condoms lead, a doctor fills in details, and luck isn't a method.","persona":"any","source":"prevention overview"},
  {"id":"pl-031","cat":"ways-to-prevent","type":"match","hook":"Match the question to who answers it best.","pairs":[{"left":"Which method suits me later?","right":"A doctor"},{"left":"Is this rumour true?","right":"A trusted adult"},{"left":"How do I feel about waiting?","right":"You"},{"left":"Could a method fit my body?","right":"A health worker"},{"left":"What's my own pace?","right":"You decide"}],"relearn":"Doctors and trusted adults answer the facts; how you feel and your pace are yours.","persona":"any","source":"help-seeking"},
  {"id":"pl-032","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"Carrying or knowing about condoms means you're planning to be reckless.\"","myth":{"un":"Knowing about condoms means you're being reckless.","re":"Being informed is responsible, whatever you choose to do or not do.","why":"Knowledge is protection, not a plan."},"relearn":"Being informed about protection is responsible, not reckless.","persona":"Veer","source":"de-stigmatise"},
  {"id":"pl-033","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"Only one person in a couple is responsible for prevention.\"","myth":{"un":"Preventing pregnancy is only one person's job.","re":"It's a shared responsibility between both people.","why":"Both are involved, so both look after it."},"relearn":"Preventing pregnancy is a shared responsibility, not one person's.","persona":"any","source":"shared responsibility"},
  {"id":"pl-034","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"If something goes wrong, there's nothing anyone can do.\"","myth":{"un":"If a method fails, there's nothing to be done.","re":"A doctor or health worker can advise on next steps and options.","why":"There's always someone to ask; you're not stuck."},"relearn":"If something goes wrong, a doctor or health worker can help with next steps.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-035","cat":"ways-to-prevent","type":"build","hook":"Build the 'know your options' idea (for now and the future).","prompt":"Assemble the calm, true summary.","pieces":["not having sex fully prevents it","condoms also reduce STIs","other methods exist","a doctor can explain them"],"mode":"assemble","key":["not having sex fully prevents it","condoms also reduce STIs","other methods exist","a doctor can explain them"],"relearn":"Knowing your options, starting with waiting, keeps future-you in control.","persona":"any","source":"prevention overview"},
  {"id":"pl-036","cat":"ways-to-prevent","type":"build","hook":"Build the two-job summary of a condom.","prompt":"Assemble what a condom does.","pieces":["helps prevent pregnancy","helps prevent STIs","needs correct use","is widely available"],"mode":"assemble","key":["helps prevent pregnancy","helps prevent STIs","needs correct use","is widely available"],"relearn":"A condom can prevent both pregnancy and STIs when used correctly.","persona":"any","source":"prevention / STIs"},
  {"id":"pl-037","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: knowing your options doesn't mean you have to use any of them now. Reassuring?","prompt":"What do you think?","options":["Yes","Knowledge isn't pressure","Good distinction"],"affirm":"Knowing your options is freedom; using them is a separate, future choice.","relearn":"Knowing your options is separate from choosing to use them.","persona":"any","source":"agency"},
  {"id":"pl-038","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: the most reliable method at your age is also the simplest, waiting. Make sense?","prompt":"What do you think?","options":["Yes","Waiting is solid","Good to know"],"affirm":"Waiting is the one fully reliable choice, and it's completely respected.","relearn":"Not having sex is the most reliable choice and is fully valid.","persona":"any","source":"abstinence-respected"},
  // Delaying is valid
  {"id":"pl-039","cat":"delaying-valid","type":"role-play","hook":"Someone pressures you with \"everyone's doing it\".","setup":"Hold your choice. Say:","yourLine":[{"text":"\"Not everyone is, and I'm not ready, that's my call.\"","best":true},{"text":"\"I guess I have to, then.\""}],"relearn":"You can hold your own pace against 'everyone's doing it'.","persona":"Veer","source":"refusal / pace"},
  {"id":"pl-040","cat":"delaying-valid","type":"role-play","hook":"A partner says \"if you loved me, you would\".","setup":"Name the pressure. Say:","yourLine":[{"text":"\"If you respected me, you wouldn't pressure me.\"","best":true},{"text":"\"...okay, fine.\""}],"relearn":"'If you loved me' is pressure; real respect waits for your yes.","persona":"Riya","source":"pressure / consent (links g24)"},
  {"id":"pl-041","cat":"delaying-valid","type":"role-play","hook":"You want to say you're not ready, without a big argument.","setup":"Keep it simple. Say:","yourLine":[{"text":"\"I'm not ready, and that's not going to change tonight.\"","best":true},{"text":"Give in to avoid awkwardness"}],"relearn":"A calm, clear 'I'm not ready' is a complete answer.","persona":"any","source":"assertiveness"},
  {"id":"pl-042","cat":"delaying-valid","type":"role-play","hook":"Friends tease you for not having a 'story' to share.","setup":"Own your pace. Say:","yourLine":[{"text":"\"I'm good doing things in my own time.\"","best":true},{"text":"Make something up to fit in"}],"relearn":"You don't owe anyone a 'story'; your pace is yours.","persona":"Veer","source":"peer pressure"},
  {"id":"pl-043","cat":"delaying-valid","type":"role-play","hook":"You're not sure how to say a clear 'no' and still be kind.","setup":"Be kind and firm. Say:","yourLine":[{"text":"\"I like you, and I'm still not ready, both are true.\"","best":true},{"text":"Apologise endlessly and cave"}],"relearn":"You can be kind and say a firm 'not ready' at once.","persona":"Riya","source":"assertiveness"},
  {"id":"pl-044","cat":"delaying-valid","type":"role-play","hook":"Someone says waiting is 'old-fashioned' or 'uncool'.","setup":"Reframe it. Say:","yourLine":[{"text":"\"Doing what's right for me is exactly cool enough.\"","best":true},{"text":"\"Maybe you're right...\""}],"relearn":"Waiting isn't old-fashioned; it's your valid choice.","persona":"any","source":"reframe / pace"},
  {"id":"pl-045","cat":"delaying-valid","type":"strike-rewrite","hook":"\"Everyone my age is having sex.\"","myth":{"un":"Everyone my age is already having sex.","re":"Most teens this age are not; the 'everyone' is a myth.","why":"People exaggerate; the real numbers are far lower."},"relearn":"Most teens your age aren't having sex; 'everyone is' is a myth.","persona":"Veer","source":"norms / pace"},
  {"id":"pl-046","cat":"delaying-valid","type":"strike-rewrite","hook":"\"Waiting means something's wrong with me.\"","myth":{"un":"If I'm waiting, something must be wrong with me.","re":"Waiting is healthy, common and smart; nothing is wrong with you.","why":"Readiness is personal, not a deadline."},"relearn":"Waiting is healthy and common; nothing's wrong with you.","persona":"Riya","source":"self-worth / pace"},
  {"id":"pl-047","cat":"delaying-valid","type":"strike-rewrite","hook":"\"Once you've said no, you can't change your mind later, or vice versa.\"","myth":{"un":"Your choice about this is fixed forever once made.","re":"You can decide at your own pace, and a 'yes' can always become 'no' again.","why":"Consent and readiness are ongoing, never locked in."},"relearn":"Your pace is yours; you can always change your mind.","persona":"any","source":"ongoing consent (links g24)"},
  {"id":"pl-048","cat":"delaying-valid","type":"branch","hook":"You feel rushed to 'keep up' with what others claim they're doing.","options":[{"text":"Go at your own pace, ignore the scoreboard","consequence":"You make calm choices that are actually yours.","outcome":"self-led","best":true},{"text":"Rush to match the stories","consequence":"There's no scoreboard; your pace is the only one that matters."}],"debrief":"This isn't a race; the only pace that matters is yours.","relearn":"Go at your own pace; there's no scoreboard to keep up with.","persona":"any","source":"pace / autonomy"},
  {"id":"pl-049","cat":"delaying-valid","type":"branch","hook":"You're with someone you like and feeling unsure in the moment.","options":[{"text":"Pause; 'unsure' means wait","consequence":"You honour your own uncertainty.","outcome":"self-respect","best":true},{"text":"Push past your own hesitation","consequence":"Unsure means not now; your hesitation is information."}],"debrief":"If you're unsure, that's a 'not yet'; trust it.","relearn":"Uncertainty means wait; 'unsure' is a 'not now'.","persona":"Riya","source":"readiness"},
  {"id":"pl-050","cat":"delaying-valid","type":"reflect","hook":"Lensy: readiness is about you, not a date on a calendar. Sit right?","prompt":"What do you think?","options":["Yes","My timing, my call","No deadline"],"affirm":"There's no 'right age' but your own readiness, freely chosen.","relearn":"Readiness is personal; there's no deadline or 'right age'.","persona":"any","source":"readiness"},
  {"id":"pl-051","cat":"delaying-valid","type":"reflect","hook":"Lensy: what would 'ready' even include, for you, one day?","prompt":"Think of one.","options":["Real trust","Feeling safe","Being older","Mutual respect"],"affirm":"Knowing what readiness means to you guards your future choices.","relearn":"Defining your own 'ready' protects your future decisions.","persona":"any","source":"readiness / values"},
  {"id":"pl-052","cat":"delaying-valid","type":"reflect","hook":"Lensy: most teens your age are choosing to wait, you're in good company. Reassuring?","prompt":"What do you think?","options":["Yes","Not alone","Good to know"],"affirm":"Waiting is the common, healthy choice at your age, you're far from alone.","relearn":"Most teens your age wait; you're in good company.","persona":"any","source":"norms (verified)"},
  // Plan your future
  {"id":"pl-053","cat":"plan-future","type":"branch","hook":"Plan It: you set a big goal (study, sport, a dream). A choice now could derail it.","options":[{"text":"Choose the path that protects your goal","consequence":"Your future self thanks you.","outcome":"planner","best":true},{"text":"Ignore how today's choice ripples forward","consequence":"Today's choices ripple; protect the future you want."}],"debrief":"Planning means seeing how today's choice touches tomorrow's goal.","relearn":"Today's choices ripple forward; plan to protect your goals.","persona":"Riya","source":"life-planning (life-sim)"},
  {"id":"pl-054","cat":"plan-future","type":"branch","hook":"An unplanned pregnancy as a teen would change a lot of plans. How do you factor it in?","options":[{"text":"Let it strengthen your reasons to wait or be careful","consequence":"You connect the facts to your own future.","outcome":"informed","best":true},{"text":"Refuse to think about it at all","consequence":"Facing it calmly helps you protect your plans."}],"debrief":"Understanding the stakes makes 'wait or be careful' your own choice.","relearn":"Knowing the stakes strengthens your reasons to wait or be careful.","persona":"any","source":"consequences / planning"},
  {"id":"pl-055","cat":"plan-future","type":"branch","hook":"You're mapping the next few years of your life.","options":[{"text":"Put your goals first and let choices serve them","consequence":"Your decisions line up behind your dreams.","outcome":"planner","best":true},{"text":"Drift and react with no plan","consequence":"A plan helps your choices serve your goals."}],"debrief":"A plan turns scattered choices into steps toward what you want.","relearn":"Planning lines your choices up behind your goals.","persona":"Veer","source":"planning / agency"},
  {"id":"pl-056","cat":"plan-future","type":"branch","hook":"A choice feels good right now but clashes with a big goal later.","options":[{"text":"Weigh now against later before deciding","consequence":"You protect the bigger thing you want.","outcome":"thoughtful","best":true},{"text":"Only think about right now","consequence":"Weigh the long game; future-you is counting on it."}],"debrief":"Planning is weighing the now against the later you care about.","relearn":"Weigh short-term feelings against your long-term goals.","persona":"any","source":"planning (links g16)"},
  {"id":"pl-057","cat":"plan-future","type":"branch","hook":"Friends say planning your future is pointless, 'just live for today'.","options":[{"text":"Enjoy today and keep an eye on tomorrow","consequence":"You balance living now with protecting later.","outcome":"balanced","best":true},{"text":"Drop all planning","consequence":"You can enjoy today and still protect tomorrow."}],"debrief":"Living now and planning ahead aren't enemies; do both.","relearn":"You can live today and plan for tomorrow at once.","persona":"any","source":"planning"},
  {"id":"pl-058","cat":"plan-future","type":"branch","hook":"You realise a goal needs choices you haven't been making.","options":[{"text":"Adjust your choices to match your goal","consequence":"You close the gap between dream and habit.","outcome":"aligned","best":true},{"text":"Keep the goal but ignore the steps","consequence":"Goals need matching choices; line them up."}],"debrief":"A goal is only as real as the choices that feed it.","relearn":"Match your daily choices to the goals you care about.","persona":"any","source":"goals"},
  {"id":"pl-059","cat":"plan-future","type":"branch","hook":"Plan It: a setback knocks your plan off course.","options":[{"text":"Adjust the plan and keep going","consequence":"Plans flex; you stay on track overall.","outcome":"resilient","best":true},{"text":"Abandon the whole plan","consequence":"Plans can bend without breaking; adjust and continue."}],"debrief":"A good plan flexes around setbacks instead of shattering.","relearn":"Adjust your plan around setbacks; don't scrap it.","persona":"Veer","source":"planning / resilience (links g39)"},
  {"id":"pl-060","cat":"plan-future","type":"build","hook":"Build a simple 'protect my future' plan.","prompt":"Order the planning steps.","pieces":["name a goal that matters","spot choices that could derail it","decide how you'll protect it","ask for support if needed"],"mode":"sequence","key":["name a goal that matters","spot choices that could derail it","decide how you'll protect it","ask for support if needed"],"relearn":"Protect your future: name the goal, spot risks, decide, get support.","persona":"any","source":"planning"},
  {"id":"pl-061","cat":"plan-future","type":"build","hook":"Build the 'choices ripple' idea.","prompt":"Assemble how a choice today touches the future.","pieces":["a choice today","leads to a consequence","which shapes options later","which shapes your goal"],"mode":"sequence","key":["a choice today","leads to a consequence","which shapes options later","which shapes your goal"],"relearn":"Choices ripple: today's choice shapes tomorrow's options.","persona":"any","source":"consequential thinking"},
  {"id":"pl-062","cat":"plan-future","type":"build","hook":"Build your 'reasons to wait or be careful' list (your own).","prompt":"Assemble reasons that are yours.","pieces":["my goals come first","I want to be truly ready","my health matters","my future is mine to protect"],"mode":"assemble","key":["my goals come first","I want to be truly ready","my health matters","my future is mine to protect"],"relearn":"Your own reasons to wait or be careful are powerful and valid.","persona":"any","source":"values / planning"},
  {"id":"pl-063","cat":"plan-future","type":"reflect","hook":"Lensy: what's one dream you're protecting by planning ahead?","prompt":"Think of one.","options":["My studies","A career","Travel","Just my freedom"],"affirm":"Keep that dream in view; your choices can guard it.","relearn":"Naming the dream you're protecting makes planning meaningful.","persona":"any","source":"motivation"},
  {"id":"pl-064","cat":"plan-future","type":"reflect","hook":"Lensy: you're the author of your future, not a passenger. Feel that?","prompt":"What do you think?","options":["Yes","I'm in charge","Empowering"],"affirm":"Your choices write your future; that's real power.","relearn":"You author your future through the choices you make.","persona":"any","source":"agency"},
  // Get the facts, not rumours
  {"id":"pl-065","cat":"facts-help","type":"sort","hook":"Sort: reliable place for SRH facts, or not?","items":[{"id":"a","text":"A doctor or clinic"},{"id":"b","text":"Pornography"},{"id":"c","text":"A trusted adult or counsellor"},{"id":"d","text":"Random social media claims"},{"id":"e","text":"A government health worker"},{"id":"f","text":"A forwarded WhatsApp 'fact'"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"not","label":"Not reliable","valence":"neg"}],"key":{"a":"reliable","b":"not","c":"reliable","d":"not","e":"reliable","f":"not"},"relearn":"Trust doctors and trusted adults; porn and random posts aren't fact sources.","persona":"any","source":"help-seeking / media literacy"},
  {"id":"pl-066","cat":"facts-help","type":"sort","hook":"Sort: porn as a guide to real sex and bodies, true or false?","items":[{"id":"a","text":"\"Porn shows realistic bodies\""},{"id":"b","text":"\"Porn is performance, not reality\""},{"id":"c","text":"\"Porn teaches real consent\""},{"id":"d","text":"\"Porn is made to sell, not to teach\""},{"id":"e","text":"\"Porn shows how most people really act\""},{"id":"f","text":"\"Real bodies and sex look different from porn\""}],"bins":[{"id":"false","label":"False","valence":"neg"},{"id":"true","label":"True","valence":"pos"}],"key":{"a":"false","b":"true","c":"false","d":"true","e":"false","f":"true"},"relearn":"Porn is performance made to sell, not a guide to real bodies, sex or consent.","persona":"Veer","source":"porn literacy (links later nodes)"},
  {"id":"pl-067","cat":"facts-help","type":"sort","hook":"Sort: a smart question to ask a doctor, or something to fear asking?","items":[{"id":"a","text":"\"How does this actually work?\""},{"id":"b","text":"Nothing, too embarrassing to ask"},{"id":"c","text":"\"Is this rumour true?\""},{"id":"d","text":"Staying silent and guessing"},{"id":"e","text":"\"Is this normal for my body?\""},{"id":"f","text":"Hiding the worry and hoping it passes"}],"bins":[{"id":"smart","label":"Smart to ask","valence":"pos"},{"id":"avoid","label":"Don't avoid","valence":"neg"}],"key":{"a":"smart","b":"avoid","c":"smart","d":"avoid","e":"smart","f":"avoid"},"relearn":"Doctors are there for exactly these questions; asking is smart.","persona":"any","source":"help-seeking"},
  {"id":"pl-068","cat":"facts-help","type":"sort","hook":"Sort: keeps SRH info private and trustworthy, or risky?","items":[{"id":"a","text":"Asking a doctor privately"},{"id":"b","text":"Believing a viral 'hack'"},{"id":"c","text":"Reading a reputable health site"},{"id":"d","text":"Trusting a stranger's DM"},{"id":"e","text":"Asking a school counsellor in private"},{"id":"f","text":"Acting on an anonymous forum tip"}],"bins":[{"id":"safe","label":"Trustworthy","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Doctors and reputable health sources beat viral 'hacks' and strangers.","persona":"any","source":"media literacy"},
  {"id":"pl-069","cat":"facts-help","type":"sort","hook":"Sort: a fact, or a rumour, about getting information?","items":[{"id":"a","text":"\"Asking questions is healthy\""},{"id":"b","text":"\"Only 'bad' kids ask about this\""},{"id":"c","text":"\"Doctors keep things professional\""},{"id":"d","text":"\"You should just know it all already\""},{"id":"e","text":"\"No question here is too embarrassing\""},{"id":"f","text":"\"Asking means there's something wrong with you\""}],"bins":[{"id":"fact","label":"Fact","valence":"pos"},{"id":"rumour","label":"Rumour","valence":"neg"}],"key":{"a":"fact","b":"rumour","c":"fact","d":"rumour","e":"fact","f":"rumour"},"relearn":"Asking questions is healthy and normal; no one is born knowing this.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-070","cat":"facts-help","type":"role-play","hook":"You want to ask a doctor a private SRH question but feel shy.","setup":"Just ask. Say:","yourLine":[{"text":"\"I have a question about my body, it's a bit private.\"","best":true},{"text":"Say nothing and look it up on a sketchy site"}],"relearn":"You can ask a doctor a private body question; that's what they're for.","persona":"any","source":"help-seeking"},
  {"id":"pl-071","cat":"facts-help","type":"role-play","hook":"A friend repeats a dangerous pregnancy myth as fact.","setup":"Correct it kindly. Say:","yourLine":[{"text":"\"Actually that's a myth, let's check the real facts.\"","best":true},{"text":"Let the myth spread"}],"relearn":"You can kindly correct a dangerous myth and point to real facts.","persona":"any","source":"myth-busting / peer"},
  {"id":"pl-072","cat":"facts-help","type":"role-play","hook":"You want to ask a trusted adult something about this topic.","setup":"Open simply. Say:","yourLine":[{"text":"\"Can I ask you something about growing up?\"","best":true},{"text":"Bottle the question up"}],"relearn":"A trusted adult is a safe person to ask about growing up.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-073","cat":"facts-help","type":"strike-rewrite","hook":"\"Asking about this means I've already done something.\"","myth":{"un":"Asking questions about sex means I've already done something.","re":"Curiosity and questions are normal; they say nothing about your actions.","why":"Learning is not the same as doing."},"relearn":"Asking questions is normal curiosity, not proof of anything.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-074","cat":"facts-help","type":"strike-rewrite","hook":"\"Porn is a decent way to learn about sex.\"","myth":{"un":"Porn is a realistic way to learn about sex.","re":"Porn is staged entertainment, not a guide to real bodies, sex or consent.","why":"It's made to sell, and it misleads."},"relearn":"Porn is staged entertainment, not sex education.","persona":"Veer","source":"porn literacy"},
  {"id":"pl-075","cat":"facts-help","type":"branch","hook":"You got conflicting 'facts' from a friend and a website.","options":[{"text":"Check with a doctor or trusted adult to be sure","consequence":"You land on the real answer.","outcome":"informed","best":true},{"text":"Just believe whichever sounds easier","consequence":"When sources clash, a doctor or trusted adult settles it."}],"debrief":"When facts clash, go to a reliable source, not the easy one.","relearn":"When facts conflict, verify with a doctor or trusted adult.","persona":"any","source":"media literacy"},
  {"id":"pl-076","cat":"facts-help","type":"branch","hook":"You're worried about something private and don't know who to ask.","options":[{"text":"Pick one trusted adult, doctor, or health worker to start","consequence":"You find a safe first door.","outcome":"resourceful","best":true},{"text":"Carry the worry alone","consequence":"There's always one safe person to start with."}],"debrief":"There's always a safe first person for a private worry.","relearn":"For a private worry, start with one trusted adult or doctor.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-077","cat":"facts-help","type":"reflect","hook":"Lensy: accurate facts protect you far more than cool-sounding rumours. Agree?","prompt":"What do you think?","options":["Yes","Facts over rumours","I'll check sources"],"affirm":"Good information is real protection; rumours just sound confident.","relearn":"Accurate facts protect you; confident rumours don't.","persona":"any","source":"media literacy"},
  {"id":"pl-078","cat":"facts-help","type":"reflect","hook":"Lensy: who is one adult you could ask a private question, if you needed to?","prompt":"Think of one.","options":["A parent","A doctor","A counsellor","An older relative"],"affirm":"Knowing your person means a private question always has a safe home.","relearn":"Knowing a trusted adult to ask keeps you informed and safe.","persona":"any","source":"help-seeking"},
  {"id":"pl-079","cat":"facts-help","type":"match","hook":"Match the source to how much to trust it.","pairs":[{"left":"A doctor","right":"Trust it"},{"left":"A viral 'hack'","right":"Be skeptical"},{"left":"A reputable health site","right":"Worth trusting"},{"left":"A locker-room 'fact'","right":"Doubt and verify"},{"left":"A stranger's DM claim","right":"Ignore it"}],"relearn":"Weigh sources: doctors and reputable health info over viral hacks.","persona":"any","source":"media literacy"},
  {"id":"pl-080","cat":"facts-help","type":"reflect","hook":"Lensy: biggest take-away from Plan It?","prompt":"Pick your motto.","options":["Pregnancy follows clear rules","Waiting is fully valid","Plan to protect my future","Get facts, not rumours"],"affirm":"That's planning power, informed, unhurried, and yours.","relearn":"Know the facts, respect waiting, and plan to protect your future.","persona":"any","source":"consolidation"},
  {"id":"pl-081","cat":"how-it-happens","type":"reflect","hook":"Lensy: this whole topic is about health and future, calm and factual. Sit okay with you?","prompt":"What do you think?","options":["Yes","Just health facts","Less awkward now"],"affirm":"Treated as health and planning, it's just useful knowledge.","relearn":"Fertility and planning are health topics, learned calmly.","persona":"any","source":"framing"},
  {"id":"pl-082","cat":"bust-myths","type":"sort","hook":"Sort: safe to rely on, or a myth that gets people in trouble?","items":[{"id":"a","text":"\"First time is free\""},{"id":"b","text":"\"Not having sex prevents pregnancy\""},{"id":"c","text":"\"Period days are always safe\""},{"id":"d","text":"\"A condom used right helps\""},{"id":"e","text":"\"You're too young, so it can't happen\""},{"id":"f","text":"\"Orgasm is needed for pregnancy\""}],"bins":[{"id":"reliable","label":"Reliable truth","valence":"pos"},{"id":"myth","label":"Dangerous myth","valence":"neg"}],"key":{"a":"myth","b":"reliable","c":"myth","d":"reliable","e":"myth","f":"myth"},"relearn":"'First time free', 'period days safe' and 'too young' are dangerous myths.","persona":"any","source":"myth-busting"},
  {"id":"pl-083","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: 'shared responsibility' means it's never just one person's job. Important?","prompt":"What do you think?","options":["Yes","Both share it","Fairer that way"],"affirm":"Prevention and care are shared, by both people, equally.","relearn":"Preventing pregnancy is a shared, equal responsibility.","persona":"any","source":"shared responsibility / equality"},
  {"id":"pl-084","cat":"delaying-valid","type":"reflect","hook":"Lensy: your body, your timeline, your choice, whatever anyone else says. Hold onto that?","prompt":"What do you think?","options":["Yes","My choice","My timeline"],"affirm":"Your body and your timeline are yours; that never changes.","relearn":"Your body, your timeline, your choice, always.","persona":"any","source":"autonomy"},
  {"id":"pl-900","cat":"bust-myths","type":"strike-rewrite","hook":"\"If it only happened once, you're fine.\"","myth":{"un":"Doing it just once can't lead to pregnancy.","re":"One occasion is enough; a single time carries a real chance.","why":"It only takes one sperm reaching one egg, even once."},"relearn":"Even a single occasion can lead to pregnancy.","persona":"any","source":"myth-busting (verified)"},
  {"id":"pl-901","cat":"bust-myths","type":"strike-rewrite","hook":"\"Doing it standing up means it can't happen.\"","myth":{"un":"Standing up during sex prevents pregnancy.","re":"Position makes no difference to whether sperm reaches an egg.","why":"Gravity doesn't stop sperm; the chance is the same."},"relearn":"No body position prevents pregnancy.","persona":"any","source":"myth-busting"},
  {"id":"pl-902","cat":"bust-myths","type":"strike-rewrite","hook":"\"Peeing right after means you're safe.\"","myth":{"un":"Going to the toilet afterwards washes the risk away.","re":"Urinating does not flush out or stop sperm that's already inside.","why":"Urine and sperm travel different paths; it changes nothing."},"relearn":"Peeing afterwards does not prevent pregnancy.","persona":"any","source":"myth-busting"},
  {"id":"pl-903","cat":"bust-myths","type":"strike-rewrite","hook":"\"A hot bath or shower afterwards kills the chance.\"","myth":{"un":"A hot bath or shower after sex prevents pregnancy.","re":"Heat or water on the outside cannot stop sperm already on its way.","why":"Nothing you do externally rinses away the possibility."},"relearn":"Baths, showers or heat afterwards don't prevent pregnancy.","persona":"any","source":"myth-busting"},
  {"id":"pl-904","cat":"bust-myths","type":"strike-rewrite","hook":"\"You can't get pregnant the very first time you ovulate.\"","myth":{"un":"The first ovulation is a 'practice' one that can't cause pregnancy.","re":"A first ovulation releases a real egg that can be fertilised.","why":"There's no 'practice' egg; biology counts from the start."},"relearn":"A first ovulation can lead to pregnancy like any other.","persona":"any","source":"fertility facts"},
  {"id":"pl-905","cat":"bust-myths","type":"strike-rewrite","hook":"\"If it doesn't hurt or you don't feel different, nothing happened.\"","myth":{"un":"You'd 'feel' it if there was any chance of pregnancy.","re":"You feel nothing at the moment sperm could meet an egg.","why":"Fertilisation is silent; sensation tells you nothing about it."},"relearn":"Feeling nothing doesn't mean there was no chance.","persona":"Riya","source":"myth-busting"},
  {"id":"pl-906","cat":"bust-myths","type":"strike-rewrite","hook":"\"Holding your breath or some trick stops it.\"","myth":{"un":"A breathing or body 'trick' in the moment prevents pregnancy.","re":"No in-the-moment trick affects whether sperm reaches an egg.","why":"These are folk tricks with no effect on biology."},"relearn":"In-the-moment 'tricks' don't prevent pregnancy.","persona":"any","source":"myth-busting"},
  {"id":"pl-907","cat":"bust-myths","type":"strike-rewrite","hook":"\"He's careful, so I don't need to think about it.\"","myth":{"un":"If a partner is 'careful', that alone keeps you safe.","re":"'Being careful' isn't a method; only real methods are reliable.","why":"Withdrawal and good intentions still fail often."},"relearn":"'Being careful' isn't a reliable method on its own.","persona":"Riya","source":"prevention facts"},
  {"id":"pl-908","cat":"bust-myths","type":"strike-rewrite","hook":"\"Drinking something or a home remedy afterwards undoes it.\"","myth":{"un":"A drink or home remedy afterwards prevents pregnancy.","re":"No food, drink or home remedy can prevent or reverse it.","why":"Real questions about this go to a doctor, not a kitchen cure."},"relearn":"Home remedies don't prevent pregnancy; ask a doctor for facts.","persona":"any","source":"help-seeking"},
  {"id":"pl-909","cat":"bust-myths","type":"strike-rewrite","hook":"\"It's the girl's job to worry about all this.\"","myth":{"un":"Preventing pregnancy is only the girl's responsibility.","re":"Prevention is shared; it's both partners' job, not only hers.","why":"Both people are part of the choice and the responsibility."},"relearn":"Preventing pregnancy is a shared, two-person responsibility.","persona":"Veer","source":"shared responsibility"},
  {"id":"pl-910","cat":"bust-myths","type":"strike-rewrite","hook":"\"Whatever my friends did worked for them, so it's fine.\"","myth":{"un":"If a friend 'got away with it', the method must be safe.","re":"No chance this time doesn't mean a method is reliable.","why":"Luck once isn't proof; the odds catch up over time."},"relearn":"A friend's luck doesn't make an unreliable method safe.","persona":"Veer","source":"myth-busting"},
  {"id":"pl-911","cat":"bust-myths","type":"strike-rewrite","hook":"\"Real men don't bother with any of this prevention stuff.\"","myth":{"un":"Caring about prevention makes a boy 'less of a man'.","re":"Looking after yourself and a partner is mature, not weak.","why":"That 'manliness' line is just pressure dressed up."},"relearn":"Caring about prevention is mature, not unmanly.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-912","cat":"bust-myths","type":"strike-rewrite","hook":"\"Everyone in my class is already doing it.\"","myth":{"un":"Everyone your age is already having sex.","re":"Most teens this age are not; 'everyone' is a loud myth.","why":"People exaggerate; the noisy claim isn't the real count."},"relearn":"Most teens this age are not having sex; 'everyone' is a myth.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-913","cat":"bust-myths","type":"strike-rewrite","hook":"\"If you wait, something must be wrong with you.\"","myth":{"un":"Waiting means you're behind or something's wrong with you.","re":"Waiting is healthy, common and smart, not a flaw.","why":"There's no clock you're failing; your pace is valid."},"relearn":"Waiting is healthy and common, never a sign something's wrong.","persona":"any","source":"delaying-valid"},
  {"id":"pl-914","cat":"bust-myths","type":"strike-rewrite","hook":"\"What I saw in porn is how real sex and safety work.\"","myth":{"un":"Porn shows how real bodies, sex and safety actually work.","re":"Porn is performance made to sell, not a guide to real life.","why":"It's scripted; real facts come from a doctor, not a screen."},"relearn":"Porn is performance, not a reliable guide to bodies or safety.","persona":"Veer","source":"facts-help"},
  {"id":"pl-915","cat":"bust-myths","type":"strike-rewrite","hook":"\"You can always count the days and pick a 100% safe one.\"","myth":{"un":"You can reliably pick a guaranteed safe day by counting.","re":"Cycles shift and sperm live for days, so counting alone fails.","why":"Even regular-seeming cycles can surprise you."},"relearn":"Counting days alone can't give a guaranteed 'safe' day.","persona":"Riya","source":"fertility awareness limits"},
  {"id":"pl-916","cat":"bust-myths","type":"strike-rewrite","hook":"\"A girl who's never had a period can't get pregnant.\"","myth":{"un":"With no period yet, pregnancy is impossible.","re":"Ovulation can happen just before a first period, so it's possible.","why":"The egg can be released before any bleeding shows."},"relearn":"Pregnancy can be possible even before a first period.","persona":"Counsellor","source":"fertility facts (verified)"},
  {"id":"pl-917","cat":"bust-myths","type":"strike-rewrite","hook":"\"Learning about prevention will just make teens do it more.\"","myth":{"un":"Knowing the facts pushes teens to have sex sooner.","re":"Good information helps teens wait and stay safer, not the reverse.","why":"Facts give you reasons and tools, not a push."},"relearn":"Accurate facts help teens wait and stay safe; they aren't a push.","persona":"Counsellor","source":"CSE evidence (verified)"},
  {"id":"pl-918","cat":"bust-myths","type":"strike-rewrite","hook":"\"Asking a doctor about this is embarrassing and weird.\"","myth":{"un":"These questions are too embarrassing to ask a doctor.","re":"Doctors hear these questions all the time; asking is smart.","why":"A doctor's info is private, accurate and there to help."},"relearn":"No SRH question is too embarrassing for a doctor; asking is smart.","persona":"Counsellor","source":"facts-help"},
  {"id":"pl-919","cat":"bust-myths","type":"strike-rewrite","hook":"\"If a forward has lots of likes, it's probably true.\"","myth":{"un":"A widely shared post about pregnancy must be accurate.","re":"Likes and shares aren't proof; viral doesn't mean true.","why":"Check the claim against a doctor or trusted adult first."},"relearn":"Viral or popular doesn't mean true; verify before you trust it.","persona":"any","source":"facts-help"},
  {"id":"pl-920","cat":"bust-myths","type":"strike-rewrite","hook":"\"Two condoms or layering give double the protection.\"","myth":{"un":"Using two condoms at once gives extra protection.","re":"Doubling up actually makes them more likely to fail, not safer.","why":"They rub and can tear; a doctor explains correct use."},"relearn":"Two condoms aren't safer; one used correctly is the way.","persona":"any","source":"prevention facts (verified)"},
  {"id":"pl-921","cat":"bust-myths","type":"strike-rewrite","hook":"\"Pulling out works if he's done it before with no problem.\"","myth":{"un":"Withdrawal is reliable as long as it 'worked' before.","re":"Withdrawal is unreliable; fluid before climax can carry sperm.","why":"About 1 in 5 who rely on it each year have an unplanned pregnancy."},"relearn":"Withdrawal stays unreliable no matter how often it 'worked'.","persona":"any","source":"prevention facts (verified)"},
  {"id":"pl-922","cat":"bust-myths","type":"strike-rewrite","hook":"\"Only adults need to know fertility facts.\"","myth":{"un":"Fertility facts are only useful once you're an adult.","re":"Once puberty begins these facts already protect you.","why":"Biology starts at puberty, so the facts matter now."},"relearn":"Fertility facts matter from puberty on, not just in adulthood.","persona":"any","source":"access to info"},
  {"id":"pl-923","cat":"bust-myths","type":"strike-rewrite","hook":"\"If a partner says they 'can't', you don't need to plan.\"","myth":{"un":"A partner's claim that they 'can't' get someone pregnant is enough.","re":"Don't rely on someone's claim; only real methods are reliable.","why":"People can be wrong or lying; facts beat reassurance."},"relearn":"Don't rely on a partner's 'I can't'; rely on real facts and methods.","persona":"Riya","source":"prevention facts"},
  {"id":"pl-924","cat":"bust-myths","type":"strike-rewrite","hook":"\"It's safe right after a period ends, guaranteed.\"","myth":{"un":"The days just after a period are guaranteed safe.","re":"Sperm can survive to meet an egg that's released soon after.","why":"With short cycles, the fertile window can start early."},"relearn":"The days after a period aren't guaranteed safe.","persona":"Riya","source":"fertility facts"},
  {"id":"pl-925","cat":"bust-myths","type":"strike-rewrite","hook":"\"Older cousins say a special food prevents it.\"","myth":{"un":"Eating a certain food protects against pregnancy.","re":"No food prevents pregnancy; that's a rumour, not a method.","why":"Real prevention is methods a doctor can explain."},"relearn":"No food prevents pregnancy; trust methods, not food rumours.","persona":"any","source":"help-seeking"},
  {"id":"pl-926","cat":"bust-myths","type":"strike-rewrite","hook":"\"If both are young, the body 'isn't ready' so nothing can happen.\"","myth":{"un":"Two young teens together means pregnancy can't happen.","re":"Once puberty has begun for both, pregnancy is possible.","why":"Age doesn't switch the biology off; it's already on."},"relearn":"Being young doesn't make pregnancy impossible after puberty.","persona":"any","source":"fertility facts"},
  {"id":"pl-927","cat":"bust-myths","type":"strike-rewrite","hook":"\"A 'safe day' app is always 100% accurate.\"","myth":{"un":"A period-tracking app can guarantee a safe day.","re":"Apps estimate from past cycles and can be wrong; they don't guarantee.","why":"Cycles vary, so any calendar guess can miss."},"relearn":"Period apps estimate; they can't guarantee a 'safe' day.","persona":"Riya","source":"fertility awareness limits"},
  {"id":"pl-928","cat":"bust-myths","type":"strike-rewrite","hook":"\"Saying no to sex now means you're rejecting them forever.\"","myth":{"un":"Waiting now means you're closing the door forever.","re":"'Not now' is about your pace, not a forever verdict.","why":"Readiness can change with time; today's no is just today's."},"relearn":"'Not now' is about your pace, not a forever rejection.","persona":"any","source":"delaying-valid"},
  {"id":"pl-929","cat":"bust-myths","type":"strike-rewrite","hook":"\"Only girls who 'aren't careful' end up with surprises.\"","myth":{"un":"Unplanned pregnancy only happens to 'careless' girls.","re":"It can happen to anyone relying on a myth or weak method.","why":"It's about the method's reliability, not someone's character."},"relearn":"It's about method reliability, not anyone's character.","persona":"any","source":"myth-busting"},
  {"id":"pl-930","cat":"bust-myths","type":"strike-rewrite","hook":"\"If there's any chance at all, pregnancy is certain.\"","myth":{"un":"Any contact at all guarantees pregnancy.","re":"A chance isn't a certainty; the truth is calm, not catastrophic.","why":"Facts mean neither false 'safe' nor false 'doomed'."},"relearn":"Every time carries a chance, but a chance isn't a certainty.","persona":"any","source":"myth-busting"},
  {"id":"pl-931","cat":"bust-myths","type":"strike-rewrite","hook":"\"You can just ask the internet instead of a doctor.\"","myth":{"un":"A random search answer is as good as asking a doctor.","re":"Search results mix facts with rumours; a doctor gives reliable answers.","why":"A doctor's info is private, accurate and meant to help."},"relearn":"For real SRH answers, a doctor beats a random search.","persona":"Counsellor","source":"facts-help"},
  {"id":"pl-932","cat":"bust-myths","type":"strike-rewrite","hook":"\"If nobody talks about it, the facts must not matter.\"","myth":{"un":"If adults stay silent about it, the facts can't be important.","re":"Silence is awkwardness, not proof the facts don't matter.","why":"The facts still protect you whether or not people discuss them."},"relearn":"Adults' silence doesn't make the facts unimportant.","persona":"any","source":"access to info"},
  {"id":"pl-933","cat":"bust-myths","type":"strike-rewrite","hook":"\"Condoms don't really do anything useful.\"","myth":{"un":"Condoms aren't actually worth using.","re":"A condom used correctly helps prevent pregnancy and reduces STIs.","why":"It's one of the few methods that does both jobs."},"relearn":"A condom used correctly helps prevent pregnancy and STIs.","persona":"any","source":"prevention facts (verified)"},
  {"id":"pl-934","cat":"bust-myths","type":"strike-rewrite","hook":"\"You can 'undo' the chance if you act fast enough.\"","myth":{"un":"There's a quick home trick to 'undo' the chance afterwards.","re":"No DIY trick reverses it; any real options are a doctor's call.","why":"Anything genuine here is medical, not a kitchen fix."},"relearn":"No home trick 'undoes' the chance; real options come from a doctor.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-935","cat":"bust-myths","type":"strike-rewrite","hook":"\"If a reel says it confidently, it's basically science.\"","myth":{"un":"A confident-sounding reel is as good as real science.","re":"Confidence isn't evidence; check the claim against a real source.","why":"Anyone can sound sure on camera and still be wrong."},"relearn":"Confidence on camera isn't evidence; verify the claim.","persona":"Veer","source":"facts-help"},
  {"id":"pl-936","cat":"bust-myths","type":"strike-rewrite","hook":"\"Talking about prevention 'jinxes' your relationship.\"","myth":{"un":"Bringing up prevention will ruin or jinx the relationship.","re":"Being able to talk about it is a sign of respect, not a jinx.","why":"A partner who respects you can handle the conversation."},"relearn":"Talking about prevention is respect, not a jinx.","persona":"Riya","source":"shared responsibility"},
  {"id":"pl-937","cat":"bust-myths","type":"strike-rewrite","hook":"\"Period sex is a guaranteed free pass.\"","myth":{"un":"Sex during a period is a guaranteed free pass.","re":"It's less likely but still possible, especially with short cycles.","why":"Sperm live for days and cycles vary, so it's not zero."},"relearn":"Period days are less likely but not a guaranteed free pass.","persona":"any","source":"fertility facts"},
  {"id":"pl-938","cat":"bust-myths","type":"role-play","hook":"A friend insists \"first time never counts\".","setup":"Correct the myth calmly. Say:","yourLine":[{"text":"\"Actually the first time counts too, every time has a chance.\"","best":true},{"text":"\"Yeah, you're probably right.\""}],"relearn":"The 'first time doesn't count' belief is a dangerous myth.","persona":"Veer","source":"myth-busting"},
  {"id":"pl-939","cat":"bust-myths","type":"role-play","hook":"Someone swears \"pulling out always works\".","setup":"Hold the fact. Say:","yourLine":[{"text":"\"Pulling out isn't reliable, that's not a real method.\"","best":true},{"text":"\"Okay, if you say so.\""}],"relearn":"Withdrawal is unreliable; saying so out loud is fine.","persona":"any","source":"prevention facts"},
  {"id":"pl-940","cat":"bust-myths","type":"role-play","hook":"A classmate says \"everyone's already doing it, don't be a baby\".","setup":"Name the myth. Say:","yourLine":[{"text":"\"Most people aren't, and that line is just pressure.\"","best":true},{"text":"\"...fine, I don't want to be left out.\""}],"relearn":"'Everyone's doing it' is a myth, not a reason.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-941","cat":"bust-myths","type":"role-play","hook":"A partner says \"washing after is enough, relax\".","setup":"Set the record straight. Say:","yourLine":[{"text":"\"Washing doesn't prevent pregnancy, that's not how it works.\"","best":true},{"text":"\"Oh, okay then.\""}],"relearn":"Washing or douching afterwards doesn't prevent pregnancy.","persona":"Riya","source":"myth-busting"},
  {"id":"pl-942","cat":"bust-myths","type":"role-play","hook":"A friend repeats \"a girl can't get pregnant before her first period\".","setup":"Share the real fact. Say:","yourLine":[{"text":"\"It can actually happen before a first period, ovulation comes first.\"","best":true},{"text":"\"I didn't know, so maybe.\""}],"relearn":"Pregnancy can be possible even before a first period.","persona":"any","source":"fertility facts"},
  {"id":"pl-943","cat":"bust-myths","type":"role-play","hook":"Someone mocks you for wanting real facts: \"just ask the group chat\".","setup":"Stand by the better source. Say:","yourLine":[{"text":"\"I'd rather check with a doctor than trust a group chat on this.\"","best":true},{"text":"\"Yeah, the group chat's fine I guess.\""}],"relearn":"A doctor beats a group chat for real SRH facts.","persona":"any","source":"facts-help"},
  {"id":"pl-944","cat":"bust-myths","type":"role-play","hook":"A friend says \"safe days are easy, just count, no risk\".","setup":"Add the missing fact. Say:","yourLine":[{"text":"\"Counting alone isn't reliable, cycles change and sperm last days.\"","best":true},{"text":"\"Cool, sounds simple enough.\""}],"relearn":"'Safe day' counting alone is unreliable.","persona":"Riya","source":"fertility awareness limits"},
  {"id":"pl-945","cat":"bust-myths","type":"role-play","hook":"Someone says \"prevention is the girl's problem, not mine\".","setup":"Share the load out loud. Say:","yourLine":[{"text":"\"Prevention is both people's job, not just hers.\"","best":true},{"text":"\"I mean, it's kind of her thing.\""}],"relearn":"Preventing pregnancy is a shared responsibility.","persona":"Veer","source":"shared responsibility"},
  {"id":"pl-946","cat":"bust-myths","type":"match","hook":"Match each confident myth to the fact that busts it.","pairs":[{"left":"\"First time is free\"","right":"Every time carries a chance"},{"left":"\"Pulling out is safe\"","right":"Fluid before climax can carry sperm"},{"left":"\"Washing stops it\"","right":"Sperm can already be on its way"},{"left":"\"Too young to happen\"","right":"Possible once puberty begins"},{"left":"\"Everyone's doing it\"","right":"Most teens this age are not"}],"relearn":"Each confident myth has a calm, true fact that busts it.","persona":"any","source":"myth-busting"},
  {"id":"pl-947","cat":"bust-myths","type":"match","hook":"Match the claim to where you'd check if it's true.","pairs":[{"left":"\"Is the first time risky?\"","right":"A doctor or health worker"},{"left":"\"My cousin's home remedy\"","right":"Not a real source, skip it"},{"left":"\"A viral reel's claim\"","right":"Verify before trusting"},{"left":"\"A school health teacher\"","right":"A reliable place to ask"},{"left":"\"Locker-room rumour\"","right":"Doubt it, then check"}],"relearn":"Check claims against doctors and trusted adults, not rumours.","persona":"any","source":"facts-help"},
  {"id":"pl-948","cat":"bust-myths","type":"match","hook":"Match the myth to why it's risky to believe.","pairs":[{"left":"\"Safe days are easy to count\"","right":"Cycles vary, so timing can surprise you"},{"left":"\"Pulling out always works\"","right":"It fails for about 1 in 5 a year"},{"left":"\"Period days are always safe\"","right":"Sperm live for days; it's not zero"},{"left":"\"Two condoms are safer\"","right":"They rub and are more likely to fail"},{"left":"\"He's careful, so relax\"","right":"'Careful' isn't a real method"}],"relearn":"Each myth carries a real risk a fact clears up.","persona":"any","source":"prevention facts (verified)"},
  {"id":"pl-949","cat":"bust-myths","type":"match","hook":"Match the worry to the calm, true reassurance.","pairs":[{"left":"\"Waiting means I'm behind\"","right":"Waiting is healthy and common"},{"left":"\"Everyone's doing it\"","right":"Most teens this age aren't"},{"left":"\"Learning this is pressure\"","right":"Facts help you wait and stay safe"},{"left":"\"It's too embarrassing to ask\"","right":"Doctors hear these questions daily"},{"left":"\"My pace must be wrong\"","right":"Your pace is valid; there's no deadline"}],"relearn":"The scary myths each have a calm, true answer.","persona":"any","source":"delaying-valid"},
  {"id":"pl-950","cat":"bust-myths","type":"match","hook":"Match the rumour source to the smarter move.","pairs":[{"left":"Forwarded message","right":"Ask a doctor before you trust it"},{"left":"Porn clip","right":"It's performance, not a guide"},{"left":"Confident reel","right":"Confidence isn't evidence"},{"left":"Group-chat 'fact'","right":"Check it against a real source"},{"left":"Trusted adult","right":"A good place to get real facts"}],"relearn":"Rumour sources get a check; real sources get your trust.","persona":"any","source":"facts-help"},
  {"id":"pl-951","cat":"bust-myths","type":"match","hook":"Match the prevention claim to whether it holds up.","pairs":[{"left":"\"Not having sex\"","right":"Fully reliable and valid"},{"left":"\"A condom used right\"","right":"Reliable, and reduces STIs"},{"left":"\"Withdrawal\"","right":"Unreliable, not a real method"},{"left":"\"Douching after\"","right":"Does nothing to prevent it"},{"left":"\"Jumping up after\"","right":"A myth with no effect"}],"relearn":"Some methods hold up; the myths don't.","persona":"any","source":"prevention facts"},
  {"id":"pl-952","cat":"bust-myths","type":"match","hook":"Match the bold claim to the honest, calm correction.","pairs":[{"left":"\"You'd feel if there was a chance\"","right":"You feel nothing when it could happen"},{"left":"\"One time can't matter\"","right":"One occasion is enough"},{"left":"\"Orgasm is needed\"","right":"It's not; sperm meeting egg is what counts"},{"left":"\"A hot shower fixes it\"","right":"Heat or water changes nothing"},{"left":"\"Position matters\"","right":"Position makes no difference"}],"relearn":"Bold myths fall apart against calm, plain facts.","persona":"any","source":"myth-busting"},
  {"id":"pl-953","cat":"bust-myths","type":"match","hook":"Match the 'who decides' myth to the truth.","pairs":[{"left":"\"It's only the girl's job\"","right":"Prevention is shared by both"},{"left":"\"Real men skip it\"","right":"Caring for both is mature"},{"left":"\"Asking shows weakness\"","right":"Asking a doctor is smart"},{"left":"\"If you loved me you would\"","right":"That's pressure, not love"},{"left":"\"Saying no is rude\"","right":"A calm no is a complete answer"}],"relearn":"Prevention and pace are shared and respected, not one-sided.","persona":"any","source":"shared responsibility"},
  {"id":"pl-954","cat":"bust-myths","type":"branch","hook":"A friend confidently tells you \"you can't get pregnant the first time\".","options":[{"text":"Politely correct it: every time carries a chance","consequence":"You stop a dangerous myth from spreading further.","outcome":"fact-led","best":true},{"text":"Nod along so you don't seem uncool","consequence":"The myth stays alive and someone might rely on it."}],"debrief":"A calm correction beats letting a risky myth pass.","relearn":"The 'first time' belief is a myth worth correcting.","persona":"Veer","source":"myth-busting"},
  {"id":"pl-955","cat":"bust-myths","type":"branch","hook":"You read a viral post claiming a home remedy prevents pregnancy.","options":[{"text":"Check it with a doctor or trusted adult first","consequence":"You learn it's false before acting on a rumour.","outcome":"verified","best":true},{"text":"Share it because it had lots of likes","consequence":"Likes aren't proof; you'd be spreading a false claim."}],"debrief":"Verify a claim against a real source before trusting or sharing it.","relearn":"Viral doesn't mean true; verify before you trust.","persona":"any","source":"facts-help"},
  {"id":"pl-956","cat":"bust-myths","type":"branch","hook":"Someone says \"safe days are easy, just count and you're fine\".","options":[{"text":"Note that counting alone isn't reliable","consequence":"You keep a realistic picture of the facts.","outcome":"clear-eyed","best":true},{"text":"Take it as a guaranteed rule","consequence":"Cycles vary, so a 'counted' safe day can be wrong."}],"debrief":"'Safe day' counting alone can't guarantee anything.","relearn":"Counting days alone is unreliable for preventing pregnancy.","persona":"Riya","source":"fertility awareness limits"},
  {"id":"pl-957","cat":"bust-myths","type":"branch","hook":"A partner claims \"pulling out is basically as good as anything\".","options":[{"text":"Say it's actually unreliable and not a real method","consequence":"You both stay honest about how weak that option is.","outcome":"informed","best":true},{"text":"Agree to keep the peace","consequence":"Withdrawal stays unreliable whether or not you argue."}],"debrief":"Withdrawal is unreliable; naming that protects you both.","relearn":"Withdrawal isn't a dependable method.","persona":"Riya","source":"prevention facts"},
  {"id":"pl-958","cat":"bust-myths","type":"branch","hook":"A reel insists \"if you wait, you're falling behind everyone\".","options":[{"text":"Recognise it as a myth and keep your pace","consequence":"You hold a calm, valid choice that's truly yours.","outcome":"self-led","best":true},{"text":"Believe you must be doing something wrong","consequence":"There's no scoreboard; waiting is common and fine."}],"debrief":"Waiting is healthy and common; 'falling behind' is a myth.","relearn":"Waiting doesn't mean you're behind; your pace is valid.","persona":"any","source":"delaying-valid"},
  {"id":"pl-959","cat":"bust-myths","type":"branch","hook":"You're unsure if a 'fact' a senior told you is real.","options":[{"text":"Ask a doctor or health teacher to check it","consequence":"You get a private, accurate answer you can trust.","outcome":"verified","best":true},{"text":"Just assume a senior must be right","consequence":"Confident seniors can repeat myths too; verify it."}],"debrief":"Verifying a claim beats acting on someone's confidence.","relearn":"Even a confident senior can be wrong; check the facts.","persona":"any","source":"facts-help"},
  {"id":"pl-960","cat":"bust-myths","type":"branch","hook":"A friend says \"washing right after is enough, no need to worry\".","options":[{"text":"Tell them washing doesn't prevent pregnancy","consequence":"You correct a myth before anyone relies on it.","outcome":"fact-led","best":true},{"text":"Let it slide to avoid the awkwardness","consequence":"Sperm can already be on its way; washing changes nothing."}],"debrief":"Washing or douching afterwards does not prevent pregnancy.","relearn":"Washing afterwards doesn't prevent pregnancy.","persona":"any","source":"myth-busting"},
  {"id":"pl-961","cat":"bust-myths","type":"branch","hook":"Boys in your group laugh that \"caring about prevention isn't manly\".","options":[{"text":"Say looking after yourself and a partner is mature","consequence":"You push back on a norm that just hides pressure.","outcome":"grounded","best":true},{"text":"Laugh along to fit in","consequence":"The 'manly' line is pressure, not a real reason."}],"debrief":"Caring about prevention is mature, not unmanly.","relearn":"Prevention is mature and shared, not 'unmanly'.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-962","cat":"bust-myths","type":"build","hook":"Build a quick myth-buster pocket card.","prompt":"Assemble the lines that are actually true.","pieces":["every time carries a chance","withdrawal is unreliable","washing afterwards does nothing","ask a doctor for real facts","the first time can't count","douching prevents it"],"mode":"assemble","key":["every time carries a chance","withdrawal is unreliable","washing afterwards does nothing","ask a doctor for real facts"],"relearn":"The true lines: every time counts, withdrawal and washing fail, ask a doctor.","persona":"any","source":"myth-busting"},
  {"id":"pl-963","cat":"bust-myths","type":"build","hook":"Build a 'reliable source' checklist for SRH facts.","prompt":"Assemble the sources worth trusting.","pieces":["a doctor or health worker","a trusted adult or counsellor","a school health teacher","a forwarded message","a viral reel with no source","a locker-room rumour"],"mode":"assemble","key":["a doctor or health worker","a trusted adult or counsellor","a school health teacher"],"relearn":"Trust doctors, trusted adults and health teachers, not rumours or reels.","persona":"any","source":"facts-help"},
  {"id":"pl-964","cat":"bust-myths","type":"build","hook":"Build the steps to handle a myth you just heard.","prompt":"Put the steps in order.","pieces":["notice the claim sounds too neat","doubt it instead of acting on it","check it with a doctor or trusted adult","go with the verified fact"],"mode":"sequence","key":["notice the claim sounds too neat","doubt it instead of acting on it","check it with a doctor or trusted adult","go with the verified fact"],"relearn":"Notice, doubt, check, then act on the verified fact.","persona":"any","source":"facts-help"},
  {"id":"pl-965","cat":"bust-myths","type":"build","hook":"Build the set of things that truly prevent pregnancy.","prompt":"Assemble only the reliable ones.","pieces":["not having sex","a condom used correctly","withdrawal","douching afterwards","jumping up afterwards","a 'safe day' guess"],"mode":"assemble","key":["not having sex","a condom used correctly"],"relearn":"Not having sex and a correctly used condom are reliable; the rest aren't.","persona":"any","source":"prevention facts"},
  {"id":"pl-966","cat":"bust-myths","type":"build","hook":"Build a calm reply to 'everyone's doing it'.","prompt":"Assemble the true, steady points.","pieces":["most teens this age aren't","that line is just pressure","my pace is my call","waiting is common and fine","so I must be behind","I have to keep up"],"mode":"assemble","key":["most teens this age aren't","that line is just pressure","my pace is my call","waiting is common and fine"],"relearn":"'Everyone's doing it' is a myth; your pace is valid.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-967","cat":"bust-myths","type":"build","hook":"Build the myth-vs-fact pair for the 'first time'.","prompt":"Assemble the true statements only.","pieces":["every time carries a chance","one occasion is enough","there's no 'free pass'","the first time can't count","first ovulation is just practice"],"mode":"assemble","key":["every time carries a chance","one occasion is enough","there's no 'free pass'"],"relearn":"There's no 'free pass'; the first time carries a chance like any other.","persona":"any","source":"myth-busting"},
  {"id":"pl-968","cat":"bust-myths","type":"build","hook":"Build the team of people you'd actually ask for fertility facts.","prompt":"Assemble the trustworthy helpers.","pieces":["a doctor","a school counsellor","a trusted adult at home","a health worker","a random forward","a confident senior's rumour"],"mode":"assemble","key":["a doctor","a school counsellor","a trusted adult at home","a health worker"],"relearn":"Doctors, counsellors, trusted adults and health workers give real facts.","persona":"any","source":"help-seeking"},
  {"id":"pl-969","cat":"bust-myths","type":"build","hook":"Build the order of busting a confident rumour.","prompt":"Put the moves in order.","pieces":["hear the confident claim","remember confidence isn't evidence","find a reliable source","replace the rumour with the fact"],"mode":"sequence","key":["hear the confident claim","remember confidence isn't evidence","find a reliable source","replace the rumour with the fact"],"relearn":"Confidence isn't evidence; find a reliable source and use the fact.","persona":"Veer","source":"facts-help"},
  {"id":"pl-970","cat":"bust-myths","type":"reflect","hook":"Lensy: noticing when a 'fact' is really a myth is a quiet superpower. Feel that?","prompt":"What do you think?","options":["Yes","I can spot them now","Rumours don't scare me"],"affirm":"Spotting a myth before you act on it keeps you in charge of the facts.","relearn":"Spotting a myth before acting on it keeps you safe and in charge.","persona":"any","source":"agency"},
  {"id":"pl-971","cat":"bust-myths","type":"reflect","hook":"Lensy: 'everyone's doing it' loses its grip once you know it's a myth. Notice that?","prompt":"What's true for you?","options":["Yes","Less pressure now","My pace is mine"],"affirm":"Most teens your age aren't, and your pace was always the only one that mattered.","relearn":"'Everyone's doing it' is a myth; your own pace is what matters.","persona":"any","source":"norm-busting"},
  {"id":"pl-972","cat":"bust-myths","type":"reflect","hook":"Lensy: asking a doctor a 'silly' question is actually the smart move. Agree?","prompt":"How does that sit?","options":["Yes","Good to know","I'd ask now"],"affirm":"There's no question too embarrassing; a doctor's info is private and there to help.","relearn":"No SRH question is too embarrassing to ask; asking is smart.","persona":"any","source":"facts-help"},
  {"id":"pl-973","cat":"bust-myths","type":"reflect","hook":"Lensy: knowing the myths are false makes the calm facts feel lighter. Notice it?","prompt":"What do you feel?","options":["Yes","Calmer about it","Just facts now"],"affirm":"Once the scary myths fall away, the real facts are calm, clear and on your side.","relearn":"With the myths gone, the real facts feel calm and clear.","persona":"any","source":"normalising"},
  {"id":"pl-974","cat":"bust-myths","type":"reflect","hook":"Lensy: learning this didn't push you anywhere; it just gave you the facts. True?","prompt":"What's true for you?","options":["Yes","I feel more ready","Just informed"],"affirm":"Facts give you reasons and tools, not a push; you're simply better informed now.","relearn":"Knowing the facts informs you; it isn't pressure to do anything.","persona":"any","source":"CSE evidence"},
  {"id":"pl-975","cat":"bust-myths","type":"reflect","hook":"Lensy: you don't owe anyone a big argument to hold your own pace. Feel that?","prompt":"What do you think?","options":["Yes","A calm no is enough","My call"],"affirm":"A clear, kind 'I'm not ready' is a complete answer; you owe no one a debate.","relearn":"A calm 'I'm not ready' is a complete answer to any myth or pressure.","persona":"any","source":"delaying-valid"},
  {"id":"pl-976","cat":"bust-myths","type":"reflect","hook":"Lensy: doubting a too-confident claim isn't rude, it's wise. Sit with that?","prompt":"How does that land?","options":["Yes","I'll check first","Wise, not rude"],"affirm":"Pausing to verify a bold claim is exactly the smart, calm move; it's never rude.","relearn":"Doubting and checking a bold claim is wise, not rude.","persona":"any","source":"facts-help"},
  {"id":"pl-977","cat":"bust-myths","type":"reflect","hook":"Lensy: prevention being a two-person job takes the weight off any one person. Notice?","prompt":"What feels true?","options":["Yes","Shared feels fairer","Not just one person"],"affirm":"Prevention is both partners' job; sharing it is fairer and how respect looks.","relearn":"Preventing pregnancy is a shared, two-person responsibility.","persona":"any","source":"shared responsibility"},
  {"id":"pl-990","cat":"delaying-valid","type":"role-play","hook":"A boyfriend sulks and goes quiet when you say not yet.","setup":"Don't chase the sulk. Say:","yourLine":[{"text":"\"Me being not ready isn't yours to punish with silence.\"","best":true},{"text":"Apologise and offer to make it up to him"}],"relearn":"Sulking is pressure too; a 'not ready' doesn't need a make-up.","persona":"Riya","source":"pressure / pace"},
  {"id":"pl-991","cat":"delaying-valid","type":"role-play","hook":"Older cousins brag at a wedding about their 'experience'.","setup":"Stay easy. Say:","yourLine":[{"text":"\"Cool for you; I'm on my own clock, no rush.\"","best":true},{"text":"Pretend you have stories too"}],"relearn":"Other people's stories set no clock for yours.","persona":"Veer","source":"family / norms"},
  {"id":"pl-992","cat":"delaying-valid","type":"role-play","hook":"Someone says \"you'll lose me if you keep waiting\".","setup":"Call the bluff calmly. Say:","yourLine":[{"text":"\"If waiting loses you, you weren't staying for me.\"","best":true},{"text":"Panic and give in to keep them"}],"relearn":"A threat to leave over waiting is pressure, not love.","persona":"Riya","source":"pressure / consent (links g24)"},
  {"id":"pl-993","cat":"delaying-valid","type":"role-play","hook":"A group chat dares you to 'prove' you're not a kid.","setup":"Skip the dare. Say:","yourLine":[{"text":"\"I don't prove anything to a group chat. Pass.\"","best":true},{"text":"Take the dare so they stop"}],"relearn":"You owe a group chat no proof; your pace isn't a dare.","persona":"Veer","source":"peer pressure / online"},
  {"id":"pl-994","cat":"delaying-valid","type":"role-play","hook":"A partner keeps asking 'why' you're not ready, again and again.","setup":"You don't owe a thesis. Say:","yourLine":[{"text":"\"'Not ready' is the whole reason. It's enough.\"","best":true},{"text":"List ten reasons hoping one lands"}],"relearn":"'I'm not ready' is a full answer; you owe no big argument.","persona":"any","source":"assertiveness"},
  {"id":"pl-995","cat":"delaying-valid","type":"role-play","hook":"A senior at tuition hints you're 'behind' your friends.","setup":"Drop the ranking. Say:","yourLine":[{"text":"\"There's no leaderboard for this. I'm fine, thanks.\"","best":true},{"text":"Feel ashamed and stay quiet"}],"relearn":"There's no leaderboard; being 'behind' is a made-up race.","persona":"any","source":"norms / pace"},
  {"id":"pl-996","cat":"delaying-valid","type":"role-play","hook":"Someone says \"just this once won't matter\".","setup":"Hold the line, lightly. Say:","yourLine":[{"text":"\"If I'm not ready, 'just once' is still not ready.\"","best":true},{"text":"Decide once can't hurt"}],"relearn":"'Just once' doesn't change a 'not ready'; your no still stands.","persona":"Riya","source":"pressure / pace"},
  {"id":"pl-997","cat":"delaying-valid","type":"role-play","hook":"A friend mocks you for blushing when this comes up.","setup":"Own it, unbothered. Say:","yourLine":[{"text":"\"I blush, I wait, both fine. Moving on.\"","best":true},{"text":"Laugh along and put yourself down"}],"relearn":"Being shy or unhurried about this is nothing to mock.","persona":"Veer","source":"peer pressure"},
  {"id":"pl-998","cat":"delaying-valid","type":"role-play","hook":"You said yes earlier in the evening but now feel off.","setup":"Update your answer. Say:","yourLine":[{"text":"\"I've changed my mind, and that's allowed. Let's stop.\"","best":true},{"text":"Push through because you already said yes"}],"relearn":"An earlier 'yes' can always become 'no'; you can stop anytime.","persona":"any","source":"ongoing consent (links g24)"},
  {"id":"pl-999","cat":"delaying-valid","type":"role-play","hook":"A partner says everyone 'their level' has done it by now.","setup":"Decline the comparison. Say:","yourLine":[{"text":"\"Their level isn't my level. I go at mine.\"","best":true},{"text":"Try to catch up to 'their level'"}],"relearn":"Other people's pace is not a level you must reach.","persona":"Riya","source":"norms / pace"},
  {"id":"pl-1000","cat":"delaying-valid","type":"role-play","hook":"Someone frames waiting as you 'not trusting' them.","setup":"Separate the two. Say:","yourLine":[{"text":"\"I can trust you and still not be ready. Both true.\"","best":true},{"text":"Agree that waiting means you distrust them"}],"relearn":"Waiting isn't distrust; readiness is its own thing.","persona":"any","source":"pressure / pace"},
  {"id":"pl-1001","cat":"delaying-valid","type":"role-play","hook":"A reel says 'real teens aren't shy about this'.","setup":"Mute the script. Say:","yourLine":[{"text":"\"A reel doesn't decide what a real teen is. I do.\"","best":true},{"text":"Believe the reel and feel less-than"}],"relearn":"A reel's idea of 'real' doesn't define you; your pace does.","persona":"Veer","source":"media / norms"},
  {"id":"pl-1002","cat":"delaying-valid","type":"role-play","hook":"You want to slow things down mid-date without killing the mood.","setup":"Slow it warmly. Say:","yourLine":[{"text":"\"I like this; let's keep it here for now. Okay?\"","best":true},{"text":"Stay quiet and let it go further than you want"}],"relearn":"You can pause things kindly; 'let's keep it here' is enough.","persona":"any","source":"assertiveness"},
  {"id":"pl-1003","cat":"delaying-valid","type":"role-play","hook":"A friend says you'll 'regret missing out' on your teen years.","setup":"Reframe the FOMO. Say:","yourLine":[{"text":"\"I won't regret living at my own speed. Truly.\"","best":true},{"text":"Rush so you don't 'miss out'"}],"relearn":"Living at your own speed isn't missing out; it's your choice.","persona":"any","source":"reframe / pace"},
  {"id":"pl-1004","cat":"delaying-valid","type":"role-play","hook":"Someone says \"you led me on, so you owe me\".","setup":"Reject the debt. Say:","yourLine":[{"text":"\"I owe you nothing physical. Liking you isn't a debt.\"","best":true},{"text":"Feel guilty and give in"}],"relearn":"Liking someone is never a debt you must repay with your body.","persona":"Riya","source":"pressure / consent (links g24)"},
  {"id":"pl-1005","cat":"delaying-valid","type":"role-play","hook":"A classmate insists 'holding out' makes you look uptight.","setup":"Shrug it off. Say:","yourLine":[{"text":"\"Call it uptight; I call it knowing myself.\"","best":true},{"text":"Worry you really are uptight"}],"relearn":"Knowing yourself isn't being uptight; that's just a putdown.","persona":"Veer","source":"peer pressure / reframe"},
  {"id":"pl-1006","cat":"delaying-valid","type":"role-play","hook":"A partner says a real relationship 'has to' include this by now.","setup":"Rewrite the rule. Say:","yourLine":[{"text":"\"A real relationship moves at a pace we both want.\"","best":true},{"text":"Accept their timeline as the rule"}],"relearn":"No relationship 'has to' hit a deadline; pace is mutual.","persona":"any","source":"pressure / pace"},
  {"id":"pl-1007","cat":"delaying-valid","type":"role-play","hook":"You're scared a clear 'no' will cause a scene in public.","setup":"Keep it simple and firm. Say:","yourLine":[{"text":"\"No. Let's leave it. We can talk later if you want.\"","best":true},{"text":"Soften it so much it stops being a no"}],"relearn":"A short, firm 'no' is complete; you needn't avoid a scene.","persona":"any","source":"assertiveness"},
  {"id":"pl-1008","cat":"delaying-valid","type":"role-play","hook":"Someone says they'll tell people you 'froze' if you don't.","setup":"Refuse the blackmail. Say:","yourLine":[{"text":"\"Threatening my name won't change my no.\"","best":true},{"text":"Give in to protect your reputation"}],"relearn":"A threat to your reputation is blackmail, not a reason to say yes.","persona":"Riya","source":"pressure / consent (links g24)"},
  {"id":"pl-1009","cat":"delaying-valid","type":"role-play","hook":"A friend asks why you 'always' say not yet, like it's a flaw.","setup":"Name it as fine. Say:","yourLine":[{"text":"\"'Not yet' isn't a flaw to fix. It's my honest answer.\"","best":true},{"text":"Treat your own pace as a problem"}],"relearn":"Saying 'not yet' isn't a defect; it's an honest, valid answer.","persona":"any","source":"self-worth / pace"},
  {"id":"pl-1010","cat":"delaying-valid","type":"role-play","hook":"You want to set a boundary before things even start.","setup":"Say it upfront. Say:","yourLine":[{"text":"\"Before anything: I'm not going there, and that's set.\"","best":true},{"text":"Hope they just figure it out"}],"relearn":"You can state a boundary upfront; clear beats hoping.","persona":"Veer","source":"assertiveness"},
  {"id":"pl-1011","cat":"delaying-valid","type":"strike-rewrite","hook":"\"If two people are dating, sex is just expected.\"","myth":{"un":"Once you're dating, having sex is just expected.","re":"Dating expects respect and a shared pace, not sex on a clock.","why":"A relationship runs on consent, not on a default setting."},"relearn":"Dating expects respect and shared pace, never sex by default.","persona":"any","source":"norms / pace"},
  {"id":"pl-1012","cat":"delaying-valid","type":"strike-rewrite","hook":"\"Saying no will make them stop liking me.\"","myth":{"un":"If I say no, they'll stop liking me.","re":"Someone who respects you can hear a 'no' and stay; if they can't, that's on them.","why":"Real liking survives a boundary; pressure doesn't get a pass."},"relearn":"A real connection can hear your no and still stay.","persona":"Riya","source":"self-worth / pace"},
  {"id":"pl-1013","cat":"delaying-valid","type":"strike-rewrite","hook":"\"There's a 'right age' you're supposed to start by.\"","myth":{"un":"There's a correct age you're meant to start by.","re":"There's no 'right age' deadline; the only timeline that counts is your own readiness.","why":"Readiness is personal, not a date everyone shares."},"relearn":"No 'right age' exists; only your own readiness sets the time.","persona":"any","source":"readiness / norms"},
  {"id":"pl-1014","cat":"delaying-valid","type":"strike-rewrite","hook":"\"Waiting just means you're scared.\"","myth":{"un":"If you're waiting, it just means you're scared.","re":"Waiting can be a calm, confident choice, not fear; you get to decide for yourself.","why":"Choosing your own pace is a sign of strength, not nerves."},"relearn":"Waiting can be calm confidence, not fear; it's your call.","persona":"Veer","source":"reframe / pace"},
  {"id":"pl-1015","cat":"delaying-valid","type":"strike-rewrite","hook":"\"A boy can't be expected to wait.\"","myth":{"un":"Boys can't really be expected to wait.","re":"Anyone can wait and respect a pace; 'boys can't help it' is an excuse, not a fact.","why":"Self-control isn't gendered; everyone owns their choices."},"relearn":"Anyone can wait; 'boys can't help it' is just an excuse.","persona":"Veer","source":"norms / equality"},
  {"id":"pl-1016","cat":"delaying-valid","type":"strike-rewrite","hook":"\"If you stop midway you're a tease.\"","myth":{"un":"Stopping midway makes you a tease.","re":"You can stop at any point; changing your mind is your right, not a crime.","why":"Consent can be withdrawn anytime; nobody is owed a finish."},"relearn":"You can stop anytime; changing your mind is never being a tease.","persona":"any","source":"ongoing consent (links g24)"},
  {"id":"pl-1017","cat":"delaying-valid","type":"strike-rewrite","hook":"\"Everyone's already done it, so I'm the odd one out.\"","myth":{"un":"Everyone has already done it, so I'm the odd one out.","re":"Most teens this age are waiting too; you're with the majority, not the exception.","why":"The 'everyone' is loud talk, not the real picture."},"relearn":"Most teens your age are waiting; you're not the odd one out.","persona":"any","source":"norms (verified)"},
  {"id":"pl-1018","cat":"delaying-valid","type":"strike-rewrite","hook":"\"Once you start a relationship, you can't take physical things slow.\"","myth":{"un":"In a relationship you can't take physical things slow.","re":"You can set the pace at any stage; slow is a perfectly valid speed.","why":"Pace is something you keep choosing, not a one-time lock."},"relearn":"You can take it slow at any stage; slow is a valid speed.","persona":"Riya","source":"pace / autonomy"},
  {"id":"pl-1019","cat":"delaying-valid","type":"strike-rewrite","hook":"\"Turning someone down means you'll be alone forever.\"","myth":{"un":"If I turn this down, I'll end up alone forever.","re":"Holding your pace doesn't doom you; the right people respect your timing.","why":"A boundary filters out pressure, it doesn't push away real connection."},"relearn":"Holding your pace won't leave you alone; it filters for respect.","persona":"any","source":"reframe / self-worth"},
  {"id":"pl-1020","cat":"delaying-valid","type":"branch","hook":"A partner gives you an ultimatum: 'tonight or we're done'.","options":[{"text":"Let them walk; an ultimatum isn't love","consequence":"You keep your pace and your self-respect.","outcome":"self-led","best":true},{"text":"Give in to save the relationship","consequence":"An ultimatum is pressure; a real partner wouldn't give one."}],"debrief":"An ultimatum is a pressure tactic, not a sign of love.","relearn":"'Tonight or we're done' is pressure; your no can let them walk.","persona":"Riya","source":"pressure / consent (links g24)"},
  {"id":"pl-1021","cat":"delaying-valid","type":"branch","hook":"Your crush hints that 'proof' would make it official.","options":[{"text":"Say a relationship needs no physical 'proof'","consequence":"You keep things honest and unforced.","outcome":"clear","best":true},{"text":"Offer 'proof' to make it real","consequence":"Real isn't proven by your body; that's just pressure dressed up."}],"debrief":"Nothing real needs to be 'proven' with your body.","relearn":"A relationship needs no physical 'proof'; that's just pressure.","persona":"any","source":"pressure / pace"},
  {"id":"pl-1022","cat":"delaying-valid","type":"branch","hook":"Friends plan to pair off after a party and expect you to as well.","options":[{"text":"Opt out without explaining yourself","consequence":"You stay comfortable and in control.","outcome":"self-led","best":true},{"text":"Go along so you're not the odd one","consequence":"Being 'the odd one' beats doing what you don't want."}],"debrief":"You can opt out of the group plan with zero explanation.","relearn":"You can sit out the group plan; you owe no explanation.","persona":"Veer","source":"peer pressure"},
  {"id":"pl-1023","cat":"delaying-valid","type":"branch","hook":"Someone you like keeps testing your 'no' to see if it bends.","options":[{"text":"Hold the same answer, calm and steady","consequence":"Your no means no, every time they test it.","outcome":"firm","best":true},{"text":"Bend a little to end the testing","consequence":"A repeated test is pressure; a steady no ends it."}],"debrief":"A 'no' that's tested again and again is still a no.","relearn":"Repeated testing is pressure; hold the same calm no.","persona":"any","source":"assertiveness / pressure"},
  {"id":"pl-1024","cat":"delaying-valid","type":"branch","hook":"You catch yourself about to say yes just to stop feeling awkward.","options":[{"text":"Sit with the awkward and keep your real answer","consequence":"You choose from your own wishes, not the discomfort.","outcome":"self-respect","best":true},{"text":"Say yes to make the awkward go away","consequence":"Awkward passes; a yes you didn't mean stays with you."}],"debrief":"Awkwardness is temporary; a choice made to dodge it isn't.","relearn":"Don't trade a real 'no' just to escape a moment of awkward.","persona":"any","source":"readiness / autonomy"},
  {"id":"pl-1025","cat":"delaying-valid","type":"branch","hook":"A partner says they'll 'wait' but keeps a countdown going.","options":[{"text":"Say a real wait has no countdown attached","consequence":"You name the pressure under the patience.","outcome":"aware","best":true},{"text":"Feel rushed by the countdown","consequence":"'Waiting' with a deadline is just slow pressure."}],"debrief":"Patience with a deadline isn't patience; it's pressure.","relearn":"A real 'I'll wait' has no countdown; a deadline is pressure.","persona":"Riya","source":"pressure / pace"},
  {"id":"pl-1026","cat":"delaying-valid","type":"branch","hook":"You feel ready in your head but your gut says 'not now'.","options":[{"text":"Trust the gut and wait","consequence":"You honour the part of you that isn't sure.","outcome":"self-respect","best":true},{"text":"Override your gut to seem decided","consequence":"A 'not now' from your gut is real information; wait."}],"debrief":"When your gut says wait, that counts as a full answer.","relearn":"If your gut says 'not now', that's reason enough to wait.","persona":"any","source":"readiness"},
  {"id":"pl-1027","cat":"delaying-valid","type":"reflect","hook":"Lensy: nobody else gets a vote on your timeline. Sit right with you?","prompt":"What do you think?","options":["Yes","No outside votes","My call alone"],"affirm":"Your timeline has one voter: you. That never changes.","relearn":"Your timeline is yours alone; no one else gets a vote.","persona":"any","source":"autonomy"},
  {"id":"pl-1028","cat":"delaying-valid","type":"reflect","hook":"Lensy: a calm 'no thanks' is a whole sentence. Does that land?","prompt":"What do you think?","options":["Yes","No need to explain","It's enough"],"affirm":"'No thanks' needs no footnote; a clear no is complete.","relearn":"A calm 'no' is a full answer; you owe no explanation.","persona":"any","source":"assertiveness"},
  {"id":"pl-1029","cat":"delaying-valid","type":"reflect","hook":"Lensy: pressure you feel is never your fault, only the pressurer's. Take that in?","prompt":"What do you think?","options":["Yes","Not my fault","Good to hear"],"affirm":"Pressure is on whoever applies it, never on you. 💛","relearn":"Pressure is never your fault; it sits with whoever pushes.","persona":"any","source":"reassurance / pace"},
  {"id":"pl-1030","cat":"delaying-valid","type":"reflect","hook":"Lensy: 'later' and 'never' are both yours to choose. Feel that freedom?","prompt":"What do you think?","options":["Yes","Both are okay","My choice"],"affirm":"Later, never, on your own day, all valid and all yours.","relearn":"'Later' and 'never' are both fully valid, fully your choice.","persona":"any","source":"autonomy"},
  {"id":"pl-1031","cat":"delaying-valid","type":"reflect","hook":"Lensy: which feels truer, 'I'm behind' or 'I'm on my own path'?","prompt":"Pick the one for you.","options":["On my own path","No race to win","I set the pace"],"affirm":"There's no 'behind'; there's only your own path forward.","relearn":"You're never 'behind'; you're on your own path at your pace.","persona":"any","source":"reframe / pace"},
  {"id":"pl-1032","cat":"delaying-valid","type":"reflect","hook":"Lensy: what helps you hold your pace when someone pushes?","prompt":"Pick one.","options":["A calm no","Walking away","Trusting myself","A friend's backup"],"affirm":"Knowing your tool means you've got it ready when you need it.","relearn":"Having a go-to way to hold your pace makes pressure easier.","persona":"any","source":"coping / pace"},
  {"id":"pl-1033","cat":"delaying-valid","type":"reflect","hook":"Lensy: respect from someone means they wait for your real yes. Agree?","prompt":"What do you think?","options":["Yes","That's respect","Worth holding out for"],"affirm":"Real respect waits for your yes; anything else isn't it.","relearn":"Respect means waiting for your genuine yes, never rushing it.","persona":"any","source":"consent (links g24)"},
  {"id":"pl-1034","cat":"delaying-valid","type":"reflect","hook":"Lensy: you can like someone a lot and still not be ready. True for you?","prompt":"What do you think?","options":["Yes","Both can be true","Liking isn't a deadline"],"affirm":"Strong feelings and 'not ready' live together just fine.","relearn":"You can have strong feelings and still not be ready; both fit.","persona":"Riya","source":"readiness"},
  {"id":"pl-1035","cat":"delaying-valid","type":"reflect","hook":"Lensy: what does 'my pace' actually feel like to you?","prompt":"Pick what fits.","options":["Calm","Unhurried","In control","No pressure"],"affirm":"Whatever 'my pace' feels like, it's yours to keep.","relearn":"Naming how your own pace feels helps you protect it.","persona":"any","source":"readiness / values"},
  {"id":"pl-1036","cat":"delaying-valid","type":"reflect","hook":"Lensy: a 'no' today doesn't have to mean 'no' forever, and that's okay. Sit right?","prompt":"What do you think?","options":["Yes","I can revisit it","No pressure either way"],"affirm":"Today's no is today's; future-you decides the rest, freely.","relearn":"A 'no' today can stay or change later; it's always your call.","persona":"any","source":"autonomy / readiness"},
  {"id":"pl-1037","cat":"delaying-valid","type":"match","hook":"Match the pressure line to the calm comeback.","pairs":[{"left":"\"Everyone's doing it\"","right":"\"Not everyone, and not me yet\""},{"left":"\"If you loved me\"","right":"\"If you respected me, you'd wait\""},{"left":"\"Just this once\"","right":"\"Once is still not ready\""},{"left":"\"You're so uptight\"","right":"\"I just know myself\""},{"left":"\"Tonight or we're done\"","right":"\"Then we're done\""}],"relearn":"Every pressure line has a calm, short comeback that holds your pace.","persona":"any","source":"assertiveness / scripts"},
  {"id":"pl-1038","cat":"delaying-valid","type":"match","hook":"Match the worry to the reassurance that answers it.","pairs":[{"left":"\"Am I behind?\"","right":"\"No race; your own path\""},{"left":"\"Will they leave?\"","right":"\"Right people wait for you\""},{"left":"\"Is waiting weird?\"","right":"\"It's common and healthy\""},{"left":"\"Do I owe a reason?\"","right":"\"'Not ready' is enough\""},{"left":"\"Is the pressure my fault?\"","right":"\"Never; it's on them\""}],"relearn":"Common waiting worries each have a calm, true answer.","persona":"any","source":"reassurance / pace"},
  {"id":"pl-1039","cat":"delaying-valid","type":"match","hook":"Match each phrase to whether it's pressure or respect.","pairs":[{"left":"\"You owe me\"","right":"Pressure"},{"left":"\"Take your time\"","right":"Respect"},{"left":"\"Prove you like me\"","right":"Tactic"},{"left":"\"Only if you want to\"","right":"Consent"},{"left":"\"Or I'll tell people\"","right":"Blackmail"}],"relearn":"Pressure demands and threatens; respect waits for your real yes.","persona":"any","source":"consent literacy (links g24)"},
  {"id":"pl-1040","cat":"delaying-valid","type":"sort","hook":"Sort: a valid reason to wait, or a pressure line to ignore?","items":[{"id":"a","text":"\"I'm just not ready yet\""},{"id":"b","text":"\"Everyone else has\""},{"id":"c","text":"\"I want to focus on my goals\""},{"id":"d","text":"\"If you loved me you would\""},{"id":"e","text":"\"My pace, my call\""},{"id":"f","text":"\"You'll lose me if you don't\""}],"bins":[{"id":"valid","label":"Valid reason","valence":"pos"},{"id":"pressure","label":"Pressure line","valence":"neg"}],"key":{"a":"valid","b":"pressure","c":"valid","d":"pressure","e":"valid","f":"pressure"},"relearn":"Your reasons to wait are valid; 'everyone' and 'if you loved me' are pressure.","persona":"any","source":"pressure-spotting / pace"},
  {"id":"pl-1041","cat":"delaying-valid","type":"sort","hook":"Sort: a true thing about waiting, or a myth?","items":[{"id":"a","text":"Most teens this age are waiting too"},{"id":"b","text":"Waiting means something's wrong with you"},{"id":"c","text":"There's no 'right age', only your readiness"},{"id":"d","text":"You owe a big reason to say no"},{"id":"e","text":"A 'yes' can become 'no' anytime"},{"id":"f","text":"Boys can't be expected to wait"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Waiting is common and valid; 'something's wrong' and 'boys can't wait' are myths.","persona":"any","source":"myth-busting / pace"},
  {"id":"pl-1042","cat":"delaying-valid","type":"sort","hook":"Sort: holds your pace, or hands it away?","items":[{"id":"a","text":"Saying a calm, clear no"},{"id":"b","text":"Caving to stop the awkwardness"},{"id":"c","text":"Trusting your own gut"},{"id":"d","text":"Doing it to keep someone"},{"id":"e","text":"Setting a boundary upfront"},{"id":"f","text":"Bending so they stop testing you"}],"bins":[{"id":"holds","label":"Holds my pace","valence":"pos"},{"id":"hands","label":"Hands it away","valence":"neg"}],"key":{"a":"holds","b":"hands","c":"holds","d":"hands","e":"holds","f":"hands"},"relearn":"A clear no and your own gut hold your pace; caving hands it away.","persona":"any","source":"assertiveness / pace"},
  {"id":"pl-1043","cat":"delaying-valid","type":"build","hook":"Build your 'hold my pace' kit (your own toolkit).","prompt":"Assemble what helps you hold your pace.","pieces":["a calm, clear no","trust in my own gut","the right to change my mind","no owed explanation"],"mode":"assemble","key":["a calm, clear no","trust in my own gut","the right to change my mind","no owed explanation"],"relearn":"Your pace-holding kit: a clear no, your gut, your right to change your mind.","persona":"any","source":"assertiveness / toolkit"},
  {"id":"pl-1044","cat":"delaying-valid","type":"build","hook":"Build a calm comeback to 'everyone's doing it'.","prompt":"Order the comeback.","pieces":["pause, don't panic","name it: that's not actually true","state your line: I go at my pace","end it: no debate needed"],"mode":"sequence","key":["pause, don't panic","name it: that's not actually true","state your line: I go at my pace","end it: no debate needed"],"relearn":"Answer 'everyone's doing it': pause, name the myth, state your pace, end it.","persona":"Veer","source":"scripts / norms"},
  {"id":"pl-1045","cat":"delaying-valid","type":"build","hook":"Build the steps for handling an ultimatum.","prompt":"Order the steps.","pieces":["spot the ultimatum as pressure","stay calm, don't argue it out","keep your real answer","let them walk if they choose"],"mode":"sequence","key":["spot the ultimatum as pressure","stay calm, don't argue it out","keep your real answer","let them walk if they choose"],"relearn":"Handle an ultimatum: spot it, stay calm, keep your answer, let them walk.","persona":"Riya","source":"pressure / scripts"},
  {"id":"pl-1046","cat":"delaying-valid","type":"build","hook":"Build your own list of reasons your pace is valid.","prompt":"Assemble reasons that are yours.","pieces":["I get to choose my timing","there's no deadline on me","my readiness is the only clock","respect waits for my yes"],"mode":"assemble","key":["I get to choose my timing","there's no deadline on me","my readiness is the only clock","respect waits for my yes"],"relearn":"Your pace is valid: you choose the timing, no deadline, respect waits.","persona":"any","source":"values / pace"},
  {"id":"pl-1080","cat":"facts-help","type":"sort","hook":"Sort: who actually knows your body facts, or who's just guessing?","items":[{"id":"a","text":"Your family doctor"},{"id":"b","text":"A senior bragging in the corridor"},{"id":"c","text":"A nurse at the clinic"},{"id":"d","text":"A meme that 'explains' bodies"},{"id":"e","text":"A health teacher you trust"},{"id":"f","text":"A celebrity's wellness post"}],"bins":[{"id":"knows","label":"Actually knows","valence":"pos"},{"id":"guess","label":"Just guessing","valence":"neg"}],"key":{"a":"knows","b":"guess","c":"knows","d":"guess","e":"knows","f":"guess"},"relearn":"Trained health people know; corridor brags and memes are guesses.","persona":"any","source":"media literacy"},
  {"id":"pl-1081","cat":"facts-help","type":"sort","hook":"Sort: green-light source you can act on, or one to double-check first?","items":[{"id":"a","text":"A clinic pamphlet from a doctor"},{"id":"b","text":"A 'fact' your cousin heard somewhere"},{"id":"c","text":"A government health helpline"},{"id":"d","text":"A clip with no source named"},{"id":"e","text":"A school counsellor's answer"},{"id":"f","text":"A claim that starts 'I heard that…'"}],"bins":[{"id":"go","label":"Trust it","valence":"pos"},{"id":"check","label":"Double-check","valence":"uhoh"}],"key":{"a":"go","b":"check","c":"go","d":"check","e":"go","f":"check"},"relearn":"Named, trained sources you can trust; vague 'I heard' claims you verify.","persona":"any","source":"media literacy"},
  {"id":"pl-1082","cat":"facts-help","type":"sort","hook":"Sort: true or false about asking a doctor a private question?","items":[{"id":"a","text":"\"A doctor keeps your questions private\""},{"id":"b","text":"\"The doctor will judge you\""},{"id":"c","text":"\"Doctors hear these questions often\""},{"id":"d","text":"\"You're the only one who ever asks\""},{"id":"e","text":"\"It's their job to give real answers\""},{"id":"f","text":"\"You must already know before you ask\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"A doctor's info is private and judgment-free; asking is normal and expected.","persona":"any","source":"help-seeking"},
  {"id":"pl-1083","cat":"facts-help","type":"sort","hook":"Sort: that's a real fact-source habit, or a rumour-trap?","items":[{"id":"a","text":"Checking a claim before you repeat it"},{"id":"b","text":"Forwarding a shocking post 'just in case'"},{"id":"c","text":"Asking 'who says so?' about a claim"},{"id":"d","text":"Believing it because everyone shared it"},{"id":"e","text":"Looking it up on a health site"},{"id":"f","text":"Trusting it because it sounds confident"}],"bins":[{"id":"habit","label":"Smart habit","valence":"pos"},{"id":"trap","label":"Rumour trap","valence":"neg"}],"key":{"a":"habit","b":"trap","c":"habit","d":"trap","e":"habit","f":"trap"},"relearn":"Check before you share; 'everyone said it' and confidence aren't proof.","persona":"any","source":"media literacy"},
  {"id":"pl-1084","cat":"facts-help","type":"sort","hook":"Riya: sort what porn really is, true or false?","items":[{"id":"a","text":"\"Porn is acting, paid and scripted\""},{"id":"b","text":"\"Porn shows what real partners want\""},{"id":"c","text":"\"Porn is edited to look a certain way\""},{"id":"d","text":"\"Porn teaches you how to treat someone\""},{"id":"e","text":"\"Real intimacy isn't a performance\""},{"id":"f","text":"\"Bodies in porn are typical bodies\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Porn is scripted, edited performance, not a model for real bodies or partners.","persona":"Riya","source":"porn literacy"},
  {"id":"pl-1085","cat":"facts-help","type":"sort","hook":"Sort: a question worth asking out loud, or one to swallow?","items":[{"id":"a","text":"\"Is this thing I read actually true?\""},{"id":"b","text":"Nothing, I'll just look it up at 2am"},{"id":"c","text":"\"Can I check this with you?\""},{"id":"d","text":"Pretend I understood and move on"},{"id":"e","text":"\"What should I trust about this?\""},{"id":"f","text":"Stay quiet so I don't look clueless"}],"bins":[{"id":"ask","label":"Worth asking","valence":"pos"},{"id":"swallow","label":"Don't swallow it","valence":"neg"}],"key":{"a":"ask","b":"swallow","c":"ask","d":"swallow","e":"ask","f":"swallow"},"relearn":"A real question out loud beats a guess in the dark; ask, don't swallow it.","persona":"any","source":"help-seeking"},
  {"id":"pl-1086","cat":"facts-help","type":"sort","hook":"Sort: that belief protects you, or sets you up to be misled?","items":[{"id":"a","text":"\"Good info helps me stay safe\""},{"id":"b","text":"\"If it's confident, it must be right\""},{"id":"c","text":"\"I can verify before I believe\""},{"id":"d","text":"\"Older kids always know best\""},{"id":"e","text":"\"A reliable source beats a rumour\""},{"id":"f","text":"\"Asking makes me look weak\""}],"bins":[{"id":"protects","label":"Protects you","valence":"pos"},{"id":"misled","label":"Gets you misled","valence":"neg"}],"key":{"a":"protects","b":"misled","c":"protects","d":"misled","e":"protects","f":"misled"},"relearn":"Verifying protects you; confidence and 'older kids know' get you misled.","persona":"any","source":"media literacy"},
  {"id":"pl-1087","cat":"facts-help","type":"sort","hook":"Veer: sort the 'man's guide' claims, fact or locker-room myth?","items":[{"id":"a","text":"\"A doctor gives the real answer\""},{"id":"b","text":"\"Real men just figure it out alone\""},{"id":"c","text":"\"Asking questions is smart, not weak\""},{"id":"d","text":"\"Porn shows how it's really done\""},{"id":"e","text":"\"Most of those brags are made up\""},{"id":"f","text":"\"You'd be the only one who doesn't know\""}],"bins":[{"id":"fact","label":"Fact","valence":"pos"},{"id":"myth","label":"Locker-room myth","valence":"neg"}],"key":{"a":"fact","b":"myth","c":"fact","d":"myth","e":"fact","f":"myth"},"relearn":"Asking is smart; the 'real men figure it out / porn teaches it' lines are myths.","persona":"Veer","source":"norm-busting / porn literacy"},
  {"id":"pl-1088","cat":"facts-help","type":"sort","hook":"Sort: leads to a real answer, or to a dead end?","items":[{"id":"a","text":"Booking a quick chat with a doctor"},{"id":"b","text":"Asking the loudest kid in class"},{"id":"c","text":"Calling a government health line"},{"id":"d","text":"Reading the comments under a reel"},{"id":"e","text":"Telling a trusted adult you're unsure"},{"id":"f","text":"Guessing and hoping you're right"}],"bins":[{"id":"answer","label":"Real answer","valence":"pos"},{"id":"deadend","label":"Dead end","valence":"neg"}],"key":{"a":"answer","b":"deadend","c":"answer","d":"deadend","e":"answer","f":"deadend"},"relearn":"Doctors, health lines and trusted adults give real answers; guessing doesn't.","persona":"any","source":"help-seeking"},
  {"id":"pl-1089","cat":"facts-help","type":"sort","hook":"Sort: how should you treat each of these about your body?","items":[{"id":"a","text":"A doctor's explanation"},{"id":"b","text":"A 'cure' someone's selling online"},{"id":"c","text":"A health worker's advice"},{"id":"d","text":"A scary forwarded message"},{"id":"e","text":"A counsellor's calm answer"},{"id":"f","text":"A claim with no source at all"}],"bins":[{"id":"believe","label":"Can rely on it","valence":"pos"},{"id":"verify","label":"Verify it first","valence":"uhoh"}],"key":{"a":"believe","b":"verify","c":"believe","d":"verify","e":"believe","f":"verify"},"relearn":"Rely on trained sources; verify sellers, scary forwards and unsourced claims.","persona":"any","source":"media literacy"},
  {"id":"pl-1090","cat":"facts-help","type":"sort","hook":"Sort: that's a safe way to get facts, or a risky shortcut?","items":[{"id":"a","text":"Asking the clinic nurse directly"},{"id":"b","text":"Copying what a stranger swears worked"},{"id":"c","text":"Checking two trusted sources agree"},{"id":"d","text":"Acting on one screenshot you saw"},{"id":"e","text":"Asking a parent or trusted aunt"},{"id":"f","text":"Trusting a 'secret tip' from a DM"}],"bins":[{"id":"safe","label":"Safe way","valence":"pos"},{"id":"risky","label":"Risky shortcut","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Ask trained people and cross-check; lone screenshots and 'secret tips' are risky.","persona":"any","source":"media literacy"},
  {"id":"pl-1091","cat":"facts-help","type":"sort","hook":"Sort: that thought makes asking easier, or keeps you stuck?","items":[{"id":"a","text":"\"No question's too embarrassing\""},{"id":"b","text":"\"I'll be the weird one for asking\""},{"id":"c","text":"\"A doctor has heard it all\""},{"id":"d","text":"\"Asking will get back to everyone\""},{"id":"e","text":"\"It's private between me and them\""},{"id":"f","text":"\"Teens just deal with it solo\""}],"bins":[{"id":"easier","label":"Makes it easier","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"easier","b":"stuck","c":"easier","d":"stuck","e":"easier","f":"stuck"},"relearn":"No question's too embarrassing and it stays private; ask, don't cope solo.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-1092","cat":"facts-help","type":"sort","hook":"Counsellor: sort what's true about coming to me with a question.","items":[{"id":"a","text":"\"What you ask stays between us\""},{"id":"b","text":"\"I'll think less of you for asking\""},{"id":"c","text":"\"I can point you to a doctor for facts\""},{"id":"d","text":"\"You should've just known this\""},{"id":"e","text":"\"There's no silly question here\""},{"id":"f","text":"\"You'd be wasting my time\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"A counsellor keeps it private, never judges, and can route you to real facts.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-1093","cat":"facts-help","type":"role-play","hook":"You read a scary claim online and you're not sure it's real.","setup":"Take it to someone who knows. Say:","yourLine":[{"text":"\"I saw something online, can you tell me if it's actually true?\"","best":true},{"text":"Believe it and panic on your own"}],"relearn":"Run a scary claim past a trusted source instead of believing it alone.","persona":"any","source":"media literacy"},
  {"id":"pl-1094","cat":"facts-help","type":"role-play","hook":"A friend says 'don't ask a doctor, it's embarrassing'.","setup":"Hold your ground. Say:","yourLine":[{"text":"\"It's their job, and I'd rather know the real answer.\"","best":true},{"text":"\"Yeah, you're right, forget it\""}],"relearn":"Asking a doctor isn't embarrassing; the real answer is worth it.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-1095","cat":"facts-help","type":"role-play","hook":"Veer's mate insists porn is 'basically a tutorial'.","setup":"Call it what it is. Say:","yourLine":[{"text":"\"That's acting made to sell, not how real life works.\"","best":true},{"text":"Nod along so you don't seem clueless"}],"relearn":"Porn is paid performance, not a tutorial for real bodies or sex.","persona":"Veer","source":"porn literacy"},
  {"id":"pl-1096","cat":"facts-help","type":"role-play","hook":"You want to ask a doctor but worry your parents will hear every word.","setup":"Just ask about privacy. Say:","yourLine":[{"text":"\"Can I ask you something privately?\"","best":true},{"text":"Skip the question to stay safe"}],"relearn":"You can ask a doctor for a private chat; they will explain what stays private.","persona":"any","source":"help-seeking"},
  {"id":"pl-1097","cat":"facts-help","type":"role-play","hook":"Riya hears a confident 'fact' from an older girl and doubts it.","setup":"Verify, don't just accept. Say:","yourLine":[{"text":"\"I'm going to check that with someone who'd actually know.\"","best":true},{"text":"Repeat it to others as fact"}],"relearn":"A confident claim isn't proof; check it with a reliable source first.","persona":"Riya","source":"media literacy"},
  {"id":"pl-1098","cat":"facts-help","type":"role-play","hook":"You don't have a clinic nearby and want trustworthy info.","setup":"Ask the counsellor for a route. Say:","yourLine":[{"text":"\"Where can I get reliable facts about this without guessing?\"","best":true},{"text":"Just trust the first link you find"}],"relearn":"Ask a trusted adult to point you to a reliable source instead of guessing.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-1099","cat":"facts-help","type":"role-play","hook":"A group chat is passing around a 'health hack' as gospel.","setup":"Slow it down. Say:","yourLine":[{"text":"\"Before we all believe this, who actually said it's true?\"","best":true},{"text":"Forward it on without checking"}],"relearn":"Ask who the source is before a 'hack' spreads as if it's a fact.","persona":"any","source":"media literacy"},
  {"id":"pl-1100","cat":"facts-help","type":"role-play","hook":"You feel silly for not already knowing something about your body.","setup":"Give yourself permission. Say:","yourLine":[{"text":"\"No one's born knowing this, so I'll just ask.\"","best":true},{"text":"Stay silent and feel behind"}],"relearn":"Nobody is born knowing this; asking is how everyone learns it.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-1101","cat":"facts-help","type":"role-play","hook":"A senior offers to 'explain how it all really works'.","setup":"Be politely skeptical. Say:","yourLine":[{"text":"\"Thanks, but I'll get the real facts from a doctor.\"","best":true},{"text":"Take every word as the truth"}],"relearn":"A senior's confident 'explainer' isn't a doctor's facts; verify it.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-1102","cat":"facts-help","type":"role-play","hook":"You finally decide to ask a trusted adult something private.","setup":"Open the door simply. Say:","yourLine":[{"text":"\"Can I ask you something about my body, even if it sounds awkward?\"","best":true},{"text":"Change the subject again"}],"relearn":"An awkward-feeling question is still fine to ask a trusted adult.","persona":"any","source":"help-seeking"},
  {"id":"pl-1103","cat":"facts-help","type":"strike-rewrite","hook":"\"If I have to ask, everyone will know I'm clueless.\"","myth":{"un":"Asking a question makes me look clueless to everyone.","re":"Asking a doctor or trusted adult is private and shows you're being smart.","why":"Smart people verify; the question stays between you and them."},"relearn":"Asking privately is smart, not clueless, and it stays private.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-1104","cat":"facts-help","type":"strike-rewrite","hook":"Veer: \"Porn taught me everything I need to know.\"","myth":{"un":"Porn is a reliable way to learn how real sex and bodies work.","re":"Porn is scripted, edited performance built to sell, not real life.","why":"It's made to entertain and profit, so it misleads about real bodies and consent."},"relearn":"Porn is paid performance, not a guide to real bodies, sex or consent.","persona":"Veer","source":"porn literacy"},
  {"id":"pl-1105","cat":"facts-help","type":"strike-rewrite","hook":"\"A claim must be true if loads of people are sharing it.\"","myth":{"un":"A claim is true if lots of people are sharing it.","re":"Popularity isn't proof; a claim is only as good as its real source.","why":"A wrong 'fact' can spread fast. Checking the source is what tells you the truth."},"relearn":"How many people share a claim doesn't make it true; check the source.","persona":"any","source":"media literacy"},
  {"id":"pl-1106","cat":"facts-help","type":"strike-rewrite","hook":"\"Doctors will tell my parents whatever I ask.\"","myth":{"un":"A doctor will report everything I ask straight to my parents.","re":"A doctor is there to help, not to expose you, and will explain what stays private.","why":"You can ask for a private chat; a doctor will tell you what stays private and why."},"relearn":"A doctor is there to help, not to expose you; ask them what stays private.","persona":"any","source":"help-seeking"},
  {"id":"pl-1107","cat":"facts-help","type":"strike-rewrite","hook":"\"Some questions are too embarrassing to ever ask.\"","myth":{"un":"Some body questions are too embarrassing to ask anyone.","re":"No question here is too embarrassing; doctors hear them all the time.","why":"They're trained for exactly these questions, so nothing surprises them."},"relearn":"No question is too embarrassing; doctors are there for exactly these.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-1108","cat":"facts-help","type":"strike-rewrite","hook":"Riya: \"Whatever the most confident person says must be right.\"","myth":{"un":"The most confident-sounding person is the one who's right.","re":"Confidence isn't accuracy; a calm, reliable source beats a loud guess.","why":"People can be very sure and still wrong, so you check, not just believe."},"relearn":"Confidence isn't proof; verify a claim against a reliable source.","persona":"Riya","source":"media literacy"},
  {"id":"pl-1109","cat":"facts-help","type":"branch","hook":"You read two opposite 'facts' about your body and don't know which is real.","options":[{"text":"Ask a doctor or trusted adult to settle it","consequence":"You walk away with the real, verified answer.","outcome":"informed","best":true},{"text":"Pick the one that sounds more exciting","consequence":"When claims clash, only a reliable source tells you which is true."}],"debrief":"When facts clash, a doctor or trusted adult settles it, not the louder claim.","relearn":"When two claims conflict, verify with a reliable source.","persona":"any","source":"media literacy"},
  {"id":"pl-1110","cat":"facts-help","type":"branch","hook":"A friend forwards you a shocking health 'fact' and says share it fast.","options":[{"text":"Check whether it's actually true before sharing","consequence":"You avoid spreading a rumour and learn the real answer.","outcome":"careful","best":true},{"text":"Forward it right away to be safe","consequence":"Checking first keeps a false 'fact' from spreading further."}],"debrief":"Check a shocking claim before you pass it on. Speed isn't proof.","relearn":"Verify a forwarded 'fact' before sharing it.","persona":"any","source":"media literacy"},
  {"id":"pl-1111","cat":"facts-help","type":"branch","hook":"You have a private worry and no idea who's safe to ask.","options":[{"text":"Pick one trusted adult, doctor or health worker to start","consequence":"You find a safe first door and stop carrying it alone.","outcome":"resourceful","best":true},{"text":"Keep it to yourself indefinitely","consequence":"There's always one safe person to start a private worry with."}],"debrief":"Every private worry has a safe first person. Start with one.","relearn":"For a private worry, start with one trusted adult or doctor.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-1112","cat":"facts-help","type":"branch","hook":"Veer's mates dare him to learn 'how it's done' from a porn clip.","options":[{"text":"Treat it as acting, not a guide, and ask a real source instead","consequence":"You keep a clear head about what's real and what's staged.","outcome":"clear-eyed","best":true},{"text":"Take the clip as a how-to","consequence":"Porn is staged to sell; it isn't how real bodies or consent work."}],"debrief":"Porn is performance. For real facts, go to a real source.","relearn":"Porn is performance, not a how-to; get real facts elsewhere.","persona":"Veer","source":"porn literacy"},
  {"id":"pl-1113","cat":"facts-help","type":"branch","hook":"You're too shy to ask out loud, so you nearly trust a random post.","options":[{"text":"Ask privately, a doctor or counsellor","consequence":"You get an accurate, private answer, not a guess.","outcome":"informed","best":true},{"text":"Act on the random post instead","consequence":"A private ask to a real source beats a stranger's post."}],"debrief":"Shyness is normal, but a private ask beats a random post.","relearn":"Ask privately for a real answer, not a random post.","persona":"any","source":"help-seeking"},
  {"id":"pl-1114","cat":"facts-help","type":"branch","hook":"Riya's boyfriend quotes a 'fact' to push her; she doubts it's true.","options":[{"text":"Pause and check it with a reliable source","consequence":"The 'fact' was just pressure dressed up; she holds her pace.","outcome":"steady","best":true},{"text":"Take his 'fact' at face value","consequence":"A claim used to pressure you is the kind to verify first."}],"debrief":"A 'fact' used to push you is the first to verify. Pressure isn't truth.","relearn":"Verify a claim used to pressure you; pressure isn't proof.","persona":"Riya","source":"media literacy"},
  {"id":"pl-1115","cat":"facts-help","type":"reflect","hook":"Lensy: where would you go first for a real body question: a person or a post?","prompt":"What feels right?","options":["A doctor","A trusted adult","A reputable health site"],"affirm":"Going to a real, reliable source first is exactly the smart move.","relearn":"For real body questions, start with a reliable source, not a random post.","persona":"any","source":"help-seeking"},
  {"id":"pl-1116","cat":"facts-help","type":"reflect","hook":"Lensy: what's your move when a claim sounds super confident but you're unsure?","prompt":"How do you handle it?","options":["Check the source","Ask someone who'd know","Look it up properly"],"affirm":"Pausing to verify a confident claim is how you stay hard to fool.","relearn":"Confidence isn't proof. Verify before you believe.","persona":"any","source":"media literacy"},
  {"id":"pl-1117","cat":"facts-help","type":"reflect","hook":"Lensy: who's one adult you'd actually feel okay asking a private question?","prompt":"Picture them.","options":["A parent","A doctor","A counsellor","An older cousin"],"affirm":"Having one safe person means a private question always has a home.","relearn":"Knowing one trusted adult to ask keeps you informed and safe.","persona":"any","source":"help-seeking"},
  {"id":"pl-1118","cat":"facts-help","type":"reflect","hook":"Lensy: how do you feel about porn being 'sex ed' after this?","prompt":"Your honest take?","options":["It's just acting","Not a real guide","I'll learn from real sources"],"affirm":"Seeing porn as performance, not a guide, keeps your facts real.","relearn":"Porn is performance, not sex ed; learn from real sources.","persona":"Veer","source":"porn literacy"},
  {"id":"pl-1119","cat":"facts-help","type":"reflect","hook":"Lensy: what would make asking a doctor feel less scary for you?","prompt":"Think it over.","options":["Knowing it's private","Knowing they've heard it","Bringing a written question"],"affirm":"Whatever lowers the bar to ask is worth using. The answer's worth it.","relearn":"Small things, like knowing it's private, make asking a doctor easier.","persona":"any","source":"help-seeking"},
  {"id":"pl-1120","cat":"facts-help","type":"reflect","hook":"Lensy: when a rumour spreads in class, what do you tend to do?","prompt":"Be honest with yourself.","options":["Ask who said it","Wait and verify","Not pass it on"],"affirm":"Slowing a rumour down, even quietly, makes you the reliable one.","relearn":"Questioning a rumour before passing it on keeps facts clean.","persona":"any","source":"media literacy"},
  {"id":"pl-1121","cat":"facts-help","type":"reflect","hook":"Riya: what helps you trust your own 'let me check that' instinct?","prompt":"What grounds you?","options":["I've been right to check","Real sources help me","I don't owe quick belief"],"affirm":"Trusting your check-it-first instinct is a quiet superpower.","relearn":"Your instinct to verify before believing is worth trusting.","persona":"Riya","source":"media literacy"},
  {"id":"pl-1122","cat":"facts-help","type":"reflect","hook":"Lensy: what's one 'fact' you've heard that you now want to double-check?","prompt":"Bring one to mind.","options":["A pregnancy myth","A body claim","A 'everyone does it' line"],"affirm":"Noticing a claim worth checking is the whole skill in action.","relearn":"Spotting a claim to verify is media literacy working.","persona":"any","source":"media literacy"},
  {"id":"pl-1123","cat":"facts-help","type":"reflect","hook":"Lensy: how does it feel knowing no question here is too embarrassing?","prompt":"Sit with it.","options":["Relieved","Less alone","More willing to ask"],"affirm":"That relief is real. The door to asking is always open to you.","relearn":"No question is too embarrassing; the door to asking stays open.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-1124","cat":"facts-help","type":"reflect","hook":"Lensy: what's your one-line rule for sorting facts from rumours?","prompt":"Coin your motto.","options":["Check the source","Ask a real person","Verify, then believe"],"affirm":"That's your filter now. It'll keep you hard to mislead.","relearn":"A simple 'check the source' rule keeps facts ahead of rumours.","persona":"any","source":"consolidation"},
  {"id":"pl-1125","cat":"facts-help","type":"match","hook":"Match the move to the smart reason behind it.","pairs":[{"left":"Ask a doctor privately","right":"Get accurate facts in private"},{"left":"Check who said a claim","right":"Tell a source from a rumour"},{"left":"Treat porn as acting","right":"Avoid a misleading 'guide'"},{"left":"Pause before forwarding","right":"Stop spreading a false 'fact'"},{"left":"Pick one trusted adult","right":"Have a safe first door"}],"relearn":"Each smart move has a clear reason: real facts, less rumour, safer you.","persona":"any","source":"media literacy"},
  {"id":"pl-1126","cat":"facts-help","type":"match","hook":"Match the claim to the right response.","pairs":[{"left":"\"Porn shows real sex\"","right":"It's staged performance"},{"left":"\"Asking is embarrassing\"","right":"It's smart and private"},{"left":"\"Everyone shares it, so it's true\"","right":"Popularity isn't proof"},{"left":"\"You should already know\"","right":"No one's born knowing"},{"left":"\"A confident person is right\"","right":"Verify, don't just believe"}],"relearn":"Each tempting claim has a calm, accurate comeback.","persona":"any","source":"media literacy"},
  {"id":"pl-1127","cat":"facts-help","type":"match","hook":"Match who to ask with the kind of help they give.","pairs":[{"left":"A doctor","right":"Accurate medical facts"},{"left":"A school counsellor","right":"A private, trusted ear"},{"left":"A government health line","right":"Reliable info by phone"},{"left":"A reputable health site","right":"Checkable written facts"},{"left":"A trusted relative","right":"A safe first conversation"}],"relearn":"Different trusted routes, all better than rumours, each with its own help.","persona":"any","source":"help-seeking"},
  {"id":"pl-1128","cat":"facts-help","type":"match","hook":"Match the red-flag source to why you'd doubt it.","pairs":[{"left":"A locker-room 'fact'","right":"Brag, not evidence"},{"left":"A 'cure' being sold","right":"Wants your money"},{"left":"An anonymous DM tip","right":"No one to vouch for it"},{"left":"A scary forward","right":"Built to spread, not inform"},{"left":"A no-source clip","right":"Nothing to check it against"}],"relearn":"Each shaky source gives you a clear reason to doubt and verify.","persona":"any","source":"media literacy"},
  {"id":"pl-1129","cat":"facts-help","type":"match","hook":"Riya: match the rumour to the reliable fact about getting help.","pairs":[{"left":"\"Doctors judge teens\"","right":"They're there to help"},{"left":"\"It won't stay private\"","right":"They'll explain what stays private"},{"left":"\"You'll be the only one asking\"","right":"They hear it often"},{"left":"\"Looking it up online is enough\"","right":"A real source is safer"},{"left":"\"Asking proves something's wrong\"","right":"Curiosity is normal"}],"relearn":"Each scary rumour about asking has a calm, true answer.","persona":"Riya","source":"de-stigmatise"},
  {"id":"pl-1130","cat":"facts-help","type":"match","hook":"Match the habit to the kind of thinker it makes you.","pairs":[{"left":"Asks 'who says so?'","right":"Hard to mislead"},{"left":"Checks before sharing","right":"A reliable friend"},{"left":"Goes to a doctor for facts","right":"Well-informed"},{"left":"Doubts a confident brag","right":"Sharp and skeptical"},{"left":"Knows one trusted adult","right":"Never stuck alone"}],"relearn":"Good fact-habits add up to someone who's hard to fool.","persona":"any","source":"consolidation"},
  {"id":"pl-1131","cat":"facts-help","type":"match","hook":"Match each question to the best place to take it.","pairs":[{"left":"\"Is this body change normal?\"","right":"A doctor"},{"left":"\"I'm worried and need to talk\"","right":"A counsellor"},{"left":"\"Is this online claim true?\"","right":"A reputable health site"},{"left":"\"Who can I even ask?\"","right":"A trusted adult"},{"left":"\"I need info but no clinic's near\"","right":"A government health line"}],"relearn":"Every question has a right door; matching them is the skill.","persona":"any","source":"help-seeking"},
  {"id":"pl-1132","cat":"facts-help","type":"build","hook":"Build your 'check it before I believe it' routine, in order.","prompt":"Put the steps in order.","pieces":["Notice the claim","Ask who the source is","Check it against a trusted source","Decide what to actually believe"],"mode":"sequence","key":["Notice the claim","Ask who the source is","Check it against a trusted source","Decide what to actually believe"],"relearn":"Notice, question the source, verify, then decide. That's the routine.","persona":"any","source":"media literacy"},
  {"id":"pl-1133","cat":"facts-help","type":"build","hook":"Build a kit of sources you can actually trust for body facts.","prompt":"Pick the trustworthy sources.","pieces":["A doctor","A 'health hack' reel","A school counsellor","A reputable health site","A stranger's DM","A government health line"],"mode":"assemble","key":["A doctor","A school counsellor","A reputable health site","A government health line"],"relearn":"A trustworthy kit is doctors, counsellors, reputable sites and health lines.","persona":"any","source":"help-seeking"},
  {"id":"pl-1134","cat":"facts-help","type":"build","hook":"Build the steps to ask a doctor a private question without panicking.","prompt":"Order the steps.","pieces":["Write down your question","Ask for a private moment","Say it plainly","Ask anything you still don't get"],"mode":"sequence","key":["Write down your question","Ask for a private moment","Say it plainly","Ask anything you still don't get"],"relearn":"Write it, ask for privacy, say it plainly, then ask follow-ups.","persona":"any","source":"help-seeking"},
  {"id":"pl-1135","cat":"facts-help","type":"build","hook":"Veer: build the 'is this a real source?' checklist.","prompt":"Pick the real checks.","pieces":["Who said it?","Are they trained in this?","Does a trusted source agree?","Does it just sound cool?","Is anyone selling something?"],"mode":"assemble","key":["Who said it?","Are they trained in this?","Does a trusted source agree?","Is anyone selling something?"],"relearn":"Check who said it, if they're trained, if a trusted source agrees, who profits.","persona":"Veer","source":"media literacy"},
  {"id":"pl-1136","cat":"facts-help","type":"build","hook":"Build what to do when a friend shares a shocking health claim.","prompt":"Order your response.","pieces":["Don't forward it yet","Ask where it came from","Check a reliable source","Then share only if it's true"],"mode":"sequence","key":["Don't forward it yet","Ask where it came from","Check a reliable source","Then share only if it's true"],"relearn":"Pause, ask the origin, verify, and share only what checks out.","persona":"any","source":"media literacy"},
  {"id":"pl-1137","cat":"facts-help","type":"build","hook":"Build your shortlist of safe people to take a private worry to.","prompt":"Pick the safe people.","pieces":["A trusted parent","An anonymous forum","A school counsellor","A doctor","A boastful classmate","A health worker"],"mode":"assemble","key":["A trusted parent","A school counsellor","A doctor","A health worker"],"relearn":"Safe people are trusted parents, counsellors, doctors and health workers.","persona":"any","source":"help-seeking"},
  {"id":"pl-1138","cat":"facts-help","type":"build","hook":"Riya: build the steps to handle a 'fact' used to pressure you.","prompt":"Put them in order.","pieces":["Notice it's being used to push you","Don't accept it on the spot","Check it with a real source","Hold your pace either way"],"mode":"sequence","key":["Notice it's being used to push you","Don't accept it on the spot","Check it with a real source","Hold your pace either way"],"relearn":"Notice the push, don't accept on the spot, verify, and hold your pace.","persona":"Riya","source":"media literacy"},
  {"id":"pl-1139","cat":"facts-help","type":"build","hook":"Build the 'why ask a doctor' reasons worth remembering.","prompt":"Pick the true reasons.","pieces":["It's private","It's accurate","It's there to help","It'll embarrass you","It judges you"],"mode":"assemble","key":["It's private","It's accurate","It's there to help"],"relearn":"A doctor's help is private, accurate and there for you.","persona":"any","source":"help-seeking"},
  {"id":"pl-1170","cat":"how-it-happens","type":"build","hook":"Build the chain from one ovary to a pregnancy.","prompt":"Put the steps in order.","pieces":["an ovary releases an egg","the egg moves into the tube","sperm reaches the egg there","the fertilised egg settles in the uterus"],"mode":"sequence","key":["an ovary releases an egg","the egg moves into the tube","sperm reaches the egg there","the fertilised egg settles in the uterus"],"relearn":"The egg travels from the ovary; if sperm reaches it, it can settle in the uterus.","persona":"any","source":"reproduction (UNESCO 6.2)"},
  {"id":"pl-1171","cat":"how-it-happens","type":"build","hook":"Build the 'why timing is tricky' summary.","prompt":"Assemble the true reasons.","pieces":["cycles vary from person to person","sperm can wait inside for days","ovulation day is hard to pin down","so 'safe days' alone aren't reliable"],"mode":"assemble","key":["cycles vary from person to person","sperm can wait inside for days","ovulation day is hard to pin down","so 'safe days' alone aren't reliable"],"relearn":"Because cycles vary and sperm wait, the exact fertile days are hard to predict.","persona":"any","source":"fertility window"},
  {"id":"pl-1172","cat":"how-it-happens","type":"build","hook":"Riya heard a list of 'rules'. Keep only the true ones.","prompt":"Assemble the points that are actually true.","pieces":["it can happen the very first time","puberty makes it possible","sperm meeting egg is what counts","no day gives a guaranteed free pass"],"mode":"assemble","key":["it can happen the very first time","puberty makes it possible","sperm meeting egg is what counts","no day gives a guaranteed free pass"],"relearn":"Sperm meeting egg is what matters. There's no guaranteed free pass on any day.","persona":"Riya","source":"fertility summary"},
  {"id":"pl-1173","cat":"how-it-happens","type":"build","hook":"Build what a body needs before pregnancy is even possible.","prompt":"Assemble what has to be true.","pieces":["puberty has begun","an egg can be released","sperm can reach that egg","the egg can settle in the uterus"],"mode":"assemble","key":["puberty has begun","an egg can be released","sperm can reach that egg","the egg can settle in the uterus"],"relearn":"Once puberty starts and sperm can reach a released egg, pregnancy becomes possible.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1174","cat":"how-it-happens","type":"build","hook":"Order the journey of a released egg through the body.","prompt":"Put the path in order.","pieces":["the ovary releases the egg","it enters the fallopian tube","it travels toward the uterus","it either settles or leaves with a period"],"mode":"sequence","key":["the ovary releases the egg","it enters the fallopian tube","it travels toward the uterus","it either settles or leaves with a period"],"relearn":"An unfertilised egg leaves with the next period; a fertilised one can settle.","persona":"any","source":"reproduction"},
  {"id":"pl-1175","cat":"how-it-happens","type":"build","hook":"Build the plain answer to 'when can it happen?'","prompt":"Assemble the honest summary.","pieces":["any time sperm can reach an egg","including the first time","whether or not there's an orgasm","since the body gives no free pass"],"mode":"assemble","key":["any time sperm can reach an egg","including the first time","whether or not there's an orgasm","since the body gives no free pass"],"relearn":"Pregnancy can happen any time sperm meets egg, first time included, orgasm or not.","persona":"any","source":"fertility summary"},
  {"id":"pl-1176","cat":"how-it-happens","type":"build","hook":"Counsellor: build a calm fact-check chain for a fertility rumour.","prompt":"Order how to check a 'fact' you heard.","pieces":["notice the claim sounds too neat","ask where it really came from","check it with a doctor or trusted adult","keep only what holds up"],"mode":"sequence","key":["notice the claim sounds too neat","ask where it really came from","check it with a doctor or trusted adult","keep only what holds up"],"relearn":"A neat-sounding fertility rumour is worth checking with a doctor before you trust it.","persona":"Counsellor","source":"verify the source"},
  {"id":"pl-1177","cat":"how-it-happens","type":"build","hook":"Build the two ingredients a pregnancy actually starts from.","prompt":"Assemble what conception needs.","pieces":["one egg","one sperm cell","them meeting and joining","then settling in the uterus"],"mode":"assemble","key":["one egg","one sperm cell","them meeting and joining","then settling in the uterus"],"relearn":"Conception is one egg and one sperm joining, which can then settle in the uterus.","persona":"any","source":"reproduction"},
  {"id":"pl-1178","cat":"how-it-happens","type":"strike-rewrite","hook":"\"An orgasm is needed for pregnancy.\"","myth":{"un":"Pregnancy only happens if the girl has an orgasm.","re":"Orgasm isn't required; pregnancy needs sperm to reach an egg.","why":"What matters is sperm meeting egg, not how anyone feels."},"relearn":"Orgasm is not required for pregnancy; sperm reaching an egg is what counts.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1179","cat":"how-it-happens","type":"strike-rewrite","hook":"\"You're too young, your body can't yet.\"","myth":{"un":"A teen body is too young to ever get pregnant.","re":"Once puberty has begun, pregnancy is biologically possible.","why":"Puberty is exactly when the body becomes able to."},"relearn":"Once puberty has begun, a teen body can biologically conceive.","persona":"any","source":"fertility / puberty"},
  {"id":"pl-1180","cat":"how-it-happens","type":"strike-rewrite","hook":"\"There's always a guaranteed safe day.\"","myth":{"un":"You can always find a day with zero chance.","re":"Cycles vary and sperm live for days, so no day is a sure free pass.","why":"That's why calendar-only methods aren't reliable on their own."},"relearn":"No single day is a guaranteed free pass, because cycles vary and sperm wait.","persona":"any","source":"fertility window"},
  {"id":"pl-1181","cat":"how-it-happens","type":"strike-rewrite","hook":"Veer: \"Sperm dies the second it's out, so timing fixes everything.\"","myth":{"un":"Sperm dies instantly, so you just time it right.","re":"Sperm can survive inside for several days, waiting for an egg.","why":"Because they wait, 'just timing it' isn't a reliable plan."},"relearn":"Sperm can survive inside for days, so timing alone isn't a reliable plan.","persona":"Veer","source":"fertility window"},
  {"id":"pl-1182","cat":"how-it-happens","type":"strike-rewrite","hook":"\"Pregnancy is some random mystery you can't understand.\"","myth":{"un":"How pregnancy happens is a confusing mystery.","re":"It follows clear biology: sperm reaching and joining an egg.","why":"Knowing the steps means no one can mislead you about it."},"relearn":"Pregnancy isn't a mystery; it follows clear, knowable biology.","persona":"any","source":"reproduction"},
  {"id":"pl-1183","cat":"how-it-happens","type":"strike-rewrite","hook":"\"The egg and sperm meet in the uterus.\"","myth":{"un":"Egg and sperm always meet down in the uterus.","re":"They usually meet up in a fallopian tube, then the egg settles.","why":"Knowing where it happens makes the whole process make sense."},"relearn":"Egg and sperm usually meet in a fallopian tube; the egg then settles in the uterus.","persona":"any","source":"reproduction"},
  {"id":"pl-1184","cat":"how-it-happens","type":"strike-rewrite","hook":"\"An egg is ready any day, all month long.\"","myth":{"un":"A fresh egg is sitting ready every single day.","re":"An egg is usually released once a cycle, around ovulation.","why":"Sperm can wait for it, which is why the window is fuzzy."},"relearn":"An egg is usually released once a cycle; sperm can wait, making the window fuzzy.","persona":"any","source":"fertility window"},
  {"id":"pl-1185","cat":"how-it-happens","type":"strike-rewrite","hook":"\"A short moment can't possibly start a pregnancy.\"","myth":{"un":"It was too quick for anything to happen.","re":"If sperm can reach an egg, length of time doesn't undo the chance.","why":"What counts is whether sperm met an egg, not how long it took."},"relearn":"What counts is whether sperm met an egg, not how long anything took.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1186","cat":"how-it-happens","type":"sort","hook":"Sort: where in the body does each step happen?","items":[{"id":"a","text":"An egg is released"},{"id":"b","text":"Egg and sperm meet"},{"id":"c","text":"A fertilised egg settles"},{"id":"d","text":"Eggs are stored"},{"id":"e","text":"The egg travels along"},{"id":"f","text":"A period sheds the lining"}],"bins":[{"id":"ovary","label":"Ovary","valence":"neutral"},{"id":"tube","label":"Fallopian tube","valence":"neutral"},{"id":"uterus","label":"Uterus","valence":"neutral"}],"key":{"a":"ovary","b":"tube","c":"uterus","d":"ovary","e":"tube","f":"uterus"},"relearn":"The ovary releases, the tube is where they meet, the uterus is where it settles.","persona":"any","source":"reproduction"},
  {"id":"pl-1187","cat":"how-it-happens","type":"sort","hook":"Sort: does this change whether pregnancy can happen?","items":[{"id":"a","text":"Sperm reaches an egg"},{"id":"b","text":"It's the first time"},{"id":"c","text":"Nobody had an orgasm"},{"id":"d","text":"It was very quick"},{"id":"e","text":"Puberty has started"},{"id":"f","text":"Washing right after"}],"bins":[{"id":"matters","label":"Actually matters","valence":"pos"},{"id":"doesnt","label":"Doesn't change it","valence":"neutral"}],"key":{"a":"matters","b":"doesnt","c":"doesnt","d":"doesnt","e":"matters","f":"doesnt"},"relearn":"Sperm reaching an egg after puberty is what matters; the rest don't give a free pass.","persona":"any","source":"fertility facts"},
  {"id":"pl-1188","cat":"how-it-happens","type":"sort","hook":"Sort: reliable way to know the fertile time, or not?","items":[{"id":"a","text":"Asking a doctor about your body"},{"id":"b","text":"Guessing from a phone app alone"},{"id":"c","text":"A friend's 'safe day' trick"},{"id":"d","text":"Assuming your cycle never shifts"},{"id":"e","text":"Knowing sperm can wait for days"},{"id":"f","text":"A rumour from a group chat"}],"bins":[{"id":"reliable","label":"Worth trusting","valence":"pos"},{"id":"unreliable","label":"Not reliable","valence":"neg"}],"key":{"a":"reliable","b":"unreliable","c":"unreliable","d":"unreliable","e":"reliable","f":"unreliable"},"relearn":"Doctor facts and knowing sperm wait beat app-guesses, tricks and group-chat rumours.","persona":"any","source":"verify the source"},
  {"id":"pl-1189","cat":"how-it-happens","type":"sort","hook":"Sort: true about the fertile window, or false?","items":[{"id":"a","text":"It sits around ovulation"},{"id":"b","text":"Sperm waiting widens it"},{"id":"c","text":"It's the exact same dates for everyone"},{"id":"d","text":"You can always feel when it is"},{"id":"e","text":"Irregular cycles make it harder to predict"},{"id":"f","text":"It lasts the whole month equally"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"true","c":"false","d":"false","e":"true","f":"false"},"relearn":"The window sits around ovulation but sperm and irregular cycles make it hard to pin down.","persona":"any","source":"fertility window"},
  {"id":"pl-1190","cat":"how-it-happens","type":"sort","hook":"Sort: needed for a pregnancy to begin, or a myth?","items":[{"id":"a","text":"Sperm"},{"id":"b","text":"An egg"},{"id":"c","text":"A 'lucky' charm"},{"id":"d","text":"Them actually meeting"},{"id":"e","text":"A certain age like 20"},{"id":"f","text":"The girl's orgasm"}],"bins":[{"id":"needed","label":"Truly needed","valence":"pos"},{"id":"myth","label":"Just a myth","valence":"neg"}],"key":{"a":"needed","b":"needed","c":"myth","d":"needed","e":"myth","f":"myth"},"relearn":"It needs sperm, egg and them meeting, not a charm, a set age, or an orgasm.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1191","cat":"how-it-happens","type":"sort","hook":"Riya sorts cycle 'facts' from her group chat.","items":[{"id":"a","text":"Cycles can be irregular for teens"},{"id":"b","text":"A period means zero chance ever"},{"id":"c","text":"Sperm can outlast a day or two"},{"id":"d","text":"Stress can shift your cycle"},{"id":"e","text":"Counting days is a perfect guarantee"},{"id":"f","text":"Your cycle is identical every month"}],"bins":[{"id":"true","label":"Holds up","valence":"pos"},{"id":"false","label":"Doesn't","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"true","e":"false","f":"false"},"relearn":"Teen cycles can shift and sperm can wait, so day-counting isn't a guarantee.","persona":"Riya","source":"fertility facts"},
  {"id":"pl-1192","cat":"how-it-happens","type":"sort","hook":"Sort each word into body part, or process.","items":[{"id":"a","text":"Ovary"},{"id":"b","text":"Ovulation"},{"id":"c","text":"Uterus"},{"id":"d","text":"Fertilisation"},{"id":"e","text":"Fallopian tube"},{"id":"f","text":"Implantation"}],"bins":[{"id":"part","label":"A body part","valence":"neutral"},{"id":"process","label":"A process","valence":"neutral"}],"key":{"a":"part","b":"process","c":"part","d":"process","e":"part","f":"process"},"relearn":"Ovary, uterus and tube are parts; ovulation, fertilisation, implantation are steps.","persona":"any","source":"vocabulary"},
  {"id":"pl-1193","cat":"how-it-happens","type":"sort","hook":"Sort: a source you'd trust for fertility facts, or not?","items":[{"id":"a","text":"A doctor"},{"id":"b","text":"A school nurse or counsellor"},{"id":"c","text":"A random viral video"},{"id":"d","text":"A locker-room 'expert'"},{"id":"e","text":"A trusted adult"},{"id":"f","text":"A 'my cousin said' rumour"}],"bins":[{"id":"trust","label":"Trust it","valence":"pos"},{"id":"doubt","label":"Doubt it","valence":"neg"}],"key":{"a":"trust","b":"trust","c":"doubt","d":"doubt","e":"trust","f":"doubt"},"relearn":"Doctors and trusted adults beat viral videos and 'someone said' rumours.","persona":"any","source":"verify the source"},
  {"id":"pl-1194","cat":"how-it-happens","type":"sort","hook":"Sort: makes pregnancy possible, or has nothing to do with it?","items":[{"id":"a","text":"Sperm able to reach an egg"},{"id":"b","text":"Puberty having begun"},{"id":"c","text":"The moon's phase"},{"id":"d","text":"What you ate that day"},{"id":"e","text":"An egg being available"},{"id":"f","text":"Your favourite colour"}],"bins":[{"id":"yes","label":"Makes it possible","valence":"pos"},{"id":"no","label":"Unrelated","valence":"neutral"}],"key":{"a":"yes","b":"yes","c":"no","d":"no","e":"yes","f":"no"},"relearn":"Pregnancy comes from biology, like sperm, egg and puberty, not from moons, food or colours.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1195","cat":"how-it-happens","type":"sort","hook":"Sort: which belongs to the fertile window idea?","items":[{"id":"a","text":"Centred on ovulation"},{"id":"b","text":"Stretched by sperm surviving"},{"id":"c","text":"Easy to know exactly"},{"id":"d","text":"The same for every body"},{"id":"e","text":"Fuzzy with irregular cycles"},{"id":"f","text":"Proof some days are risk-free"}],"bins":[{"id":"yes","label":"Fits the window","valence":"pos"},{"id":"no","label":"Misreads it","valence":"neg"}],"key":{"a":"yes","b":"yes","c":"no","d":"no","e":"yes","f":"no"},"relearn":"The window centres on ovulation but is stretched and fuzzy, not a risk-free promise.","persona":"any","source":"fertility window"},
  {"id":"pl-1196","cat":"how-it-happens","type":"sort","hook":"Sort: step that helps a pregnancy start, or a step that ends the cycle?","items":[{"id":"a","text":"An egg is released"},{"id":"b","text":"Sperm joins the egg"},{"id":"c","text":"The egg settles in the uterus"},{"id":"d","text":"No sperm reaches the egg"},{"id":"e","text":"The egg leaves with a period"},{"id":"f","text":"The lining sheds"}],"bins":[{"id":"start","label":"Toward pregnancy","valence":"pos"},{"id":"end","label":"Cycle resets","valence":"neutral"}],"key":{"a":"start","b":"start","c":"start","d":"end","e":"end","f":"end"},"relearn":"If sperm doesn't reach the egg, it leaves with a period and the cycle resets.","persona":"any","source":"reproduction"},
  {"id":"pl-1197","cat":"how-it-happens","type":"sort","hook":"Sort: honest fertility fact, or scary exaggeration?","items":[{"id":"a","text":"Pregnancy follows clear biology"},{"id":"b","text":"A chance exists if sperm meets egg"},{"id":"c","text":"You'll definitely get pregnant from one touch"},{"id":"d","text":"Knowing the facts helps you plan"},{"id":"e","text":"Even thinking about it makes it happen"},{"id":"f","text":"Timing alone is guaranteed-safe"}],"bins":[{"id":"honest","label":"Honest","valence":"pos"},{"id":"off","label":"Off the mark","valence":"neg"}],"key":{"a":"honest","b":"honest","c":"off","d":"honest","e":"off","f":"off"},"relearn":"Honest facts beat both scare-talk and false 'guaranteed-safe' promises.","persona":"any","source":"fertility facts"},
  {"id":"pl-1198","cat":"how-it-happens","type":"match","hook":"Match the step to where it happens in the body.","pairs":[{"left":"An egg is released","right":"At the ovary"},{"left":"Sperm meets egg","right":"In a fallopian tube"},{"left":"A fertilised egg settles","right":"In the uterus"},{"left":"Eggs are stored","right":"Inside the ovaries"},{"left":"The lining sheds","right":"Out as a period"}],"relearn":"Each step has a place: ovary, tube, uterus, biology you can map out.","persona":"any","source":"reproduction"},
  {"id":"pl-1199","cat":"how-it-happens","type":"match","hook":"Match the myth to the plain fact that corrects it.","pairs":[{"left":"\"Not the first time\"","right":"A chance is there from the start"},{"left":"\"Need an orgasm\"","right":"Sperm meeting egg is what counts"},{"left":"\"Too young\"","right":"Puberty makes it possible"},{"left":"\"Always a safe day\"","right":"Cycles vary; sperm wait"},{"left":"\"It's random\"","right":"It follows clear biology"}],"relearn":"Each confident myth has a plain, true correction behind it.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1200","cat":"how-it-happens","type":"match","hook":"Match the fertility fact to what it means for you.","pairs":[{"left":"Sperm can wait inside","right":"The fertile window is wider than a day"},{"left":"Cycles can be irregular","right":"Predicting the day is hard"},{"left":"Puberty has begun","right":"The body can already conceive"},{"left":"Orgasm isn't required","right":"It can still happen without one"},{"left":"First time counts","right":"There's no free first pass"}],"relearn":"Each fact connects to a real takeaway about how pregnancy works.","persona":"any","source":"fertility facts"},
  {"id":"pl-1201","cat":"how-it-happens","type":"match","hook":"Riya matches each term to its plain-language meaning.","pairs":[{"left":"Ovulation","right":"An egg leaves the ovary"},{"left":"Conception","right":"A pregnancy starts"},{"left":"Implantation","right":"The egg settles in"},{"left":"Fertile window","right":"When it's likeliest"},{"left":"Irregular cycle","right":"Timing that shifts month to month"}],"relearn":"Plain words for each term make the biology clear instead of scary.","persona":"Riya","source":"vocabulary"},
  {"id":"pl-1202","cat":"how-it-happens","type":"match","hook":"Match the question to who can give a real answer.","pairs":[{"left":"\"When is my fertile window?\"","right":"A doctor who knows your body"},{"left":"\"Is this rumour true?\"","right":"A trusted adult or counsellor"},{"left":"\"How does a cycle work?\"","right":"A health worker or doctor"},{"left":"\"Is this video right?\"","right":"Check it against a real source"},{"left":"\"Am I normal?\"","right":"A doctor, privately and kindly"}],"relearn":"Real fertility questions route to a doctor or trusted adult, not a rumour.","persona":"any","source":"verify the source"},
  {"id":"pl-1203","cat":"how-it-happens","type":"match","hook":"Match each body part to its job in the journey.","pairs":[{"left":"Ovary","right":"Releases the egg"},{"left":"Fallopian tube","right":"Carries it and hosts the meeting"},{"left":"Uterus","right":"Holds a settled pregnancy"},{"left":"Egg","right":"What sperm fertilises"},{"left":"Sperm","right":"Travels to reach the egg"}],"relearn":"Each part has one clear job in the journey from egg to settling.","persona":"any","source":"reproduction"},
  {"id":"pl-1204","cat":"how-it-happens","type":"match","hook":"Match the 'safe day' claim to why it can't be trusted alone.","pairs":[{"left":"\"My app says today's safe\"","right":"It only guesses from past cycles"},{"left":"\"I counted the days\"","right":"Cycles can shift unexpectedly"},{"left":"\"It's the wrong week\"","right":"Sperm can wait for an egg"},{"left":"\"My friend's trick works\"","right":"It isn't reliable for everyone"},{"left":"\"I feel safe today\"","right":"Feelings don't track fertility"}],"relearn":"Every 'safe day' shortcut leans on guesses that cycles and sperm can break.","persona":"any","source":"fertility window"},
  {"id":"pl-1205","cat":"how-it-happens","type":"match","hook":"Match the cause to the effect in reproduction.","pairs":[{"left":"Sperm reaches and joins an egg","right":"A pregnancy can begin"},{"left":"No sperm reaches the egg","right":"It leaves with the next period"},{"left":"Puberty starts","right":"The body becomes able to conceive"},{"left":"An egg is released","right":"The fertile window opens"},{"left":"The fertilised egg settles","right":"The pregnancy continues"}],"relearn":"Each cause leads to a clear effect. Pregnancy is a chain, not a mystery.","persona":"any","source":"reproduction"},
  {"id":"pl-1206","cat":"how-it-happens","type":"match","hook":"Veer matches a cocky claim to the fact that deflates it.","pairs":[{"left":"\"Timing beats everything\"","right":"Sperm can wait for the egg"},{"left":"\"First time is free\"","right":"A chance is there from the start"},{"left":"\"We're too young anyway\"","right":"Puberty already makes it possible"},{"left":"\"It's all luck\"","right":"It follows clear biology"},{"left":"\"No orgasm, no risk\"","right":"Sperm meeting egg is what counts"}],"relearn":"Every cocky 'rule' has a plain fact that quietly takes it apart.","persona":"Veer","source":"fertility facts"},
  {"id":"pl-1207","cat":"how-it-happens","type":"match","hook":"Match the everyday word to the science word.","pairs":[{"left":"Egg is let go","right":"Ovulation"},{"left":"Sperm and egg join","right":"Fertilisation"},{"left":"It takes hold","right":"Implantation"},{"left":"Pregnancy starts","right":"Conception"},{"left":"Likeliest days","right":"Fertile window"}],"relearn":"The science words just label everyday steps you can already picture.","persona":"any","source":"vocabulary"},
  {"id":"pl-1208","cat":"how-it-happens","type":"match","hook":"Match the body change at puberty to what it signals.","pairs":[{"left":"Periods may begin","right":"Eggs can be released"},{"left":"Sperm production starts","right":"Sperm becomes possible"},{"left":"Body matures","right":"Conception becomes possible"},{"left":"Cycles settle in (slowly)","right":"They can still be irregular"},{"left":"Hormones shift","right":"It's normal, not a problem"}],"relearn":"Puberty's changes signal that the body can now biologically conceive.","persona":"any","source":"fertility / puberty"},
  {"id":"pl-1209","cat":"how-it-happens","type":"match","hook":"Match the question a teen asks to the honest answer.","pairs":[{"left":"\"Can it happen the first time?\"","right":"Yes, a chance is there"},{"left":"\"Only on certain days?\"","right":"Timing is hard to predict"},{"left":"\"Is my body too young?\"","right":"After puberty, no"},{"left":"\"Does washing stop it?\"","right":"No, sperm may already be on the way"},{"left":"\"Is it random?\"","right":"No, it's clear biology"}],"relearn":"Honest answers replace the scary myths with calm, clear facts.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1210","cat":"how-it-happens","type":"reflect","hook":"Lensy: once you can picture egg, sperm and where they meet, it stops feeling spooky. Notice that?","prompt":"What do you think?","options":["Yes","Less spooky now","I can picture it"],"affirm":"Picturing the simple steps takes the fear out of the facts.","relearn":"Seeing the simple steps makes the biology feel clear, not scary.","persona":"any","source":"agency"},
  {"id":"pl-1211","cat":"how-it-happens","type":"reflect","hook":"Lensy: knowing the real rules means a confident rumour can't fool you. Feel steadier?","prompt":"What do you think?","options":["Yes","Harder to fool me now","Good to know"],"affirm":"When you know how it works, a loud rumour loses its power over you.","relearn":"Knowing how pregnancy works makes you harder to mislead.","persona":"any","source":"agency"},
  {"id":"pl-1212","cat":"how-it-happens","type":"reflect","hook":"Lensy: having a plain name for each part, like ovary, tube or uterus, makes it click. Notice that?","prompt":"What do you think?","options":["Yes","The words help","It clicks now"],"affirm":"Real names for the parts turn a fuzzy topic into something you can hold.","relearn":"Knowing the plain names for each part makes the whole process easier to grasp.","persona":"any","source":"vocabulary"},
  {"id":"pl-1213","cat":"how-it-happens","type":"reflect","hook":"Riya: I used to think this stuff was a guessing game. Knowing the steps actually settles me. You too?","prompt":"What do you think?","options":["Yes","Same","Clearer now"],"affirm":"Trading guesswork for facts is a calm kind of confidence.","relearn":"Understanding the facts replaces anxious guessing with calm clarity.","persona":"Riya","source":"agency"},
  {"id":"pl-1214","cat":"how-it-happens","type":"reflect","hook":"Lensy: understanding 'how' is the first step to understanding 'how to prevent'. Makes sense?","prompt":"What do you think?","options":["Yes","Connects up","Step one, got it"],"affirm":"Understanding how it happens is exactly what makes prevention make sense later.","relearn":"Knowing how pregnancy happens lays the groundwork for understanding prevention.","persona":"any","source":"agency"},
  {"id":"pl-1215","cat":"how-it-happens","type":"reflect","hook":"Lensy: you don't have to memorise everything. Knowing where to ask is its own skill. Agree?","prompt":"What do you think?","options":["Yes","I can ask","That's a relief"],"affirm":"You don't need every fact memorised; knowing who to ask is power too.","relearn":"Knowing where to get real facts matters as much as the facts themselves.","persona":"any","source":"verify the source"},
  {"id":"pl-1216","cat":"how-it-happens","type":"reflect","hook":"Counsellor: there's no question about your body that's too silly or too embarrassing to ask. Okay?","prompt":"What do you think?","options":["Okay","Good to hear","I'll remember that"],"affirm":"No body question is too small or too awkward. That's what doctors are for.","relearn":"No question about your body is too embarrassing to ask a doctor or trusted adult.","persona":"Counsellor","source":"facts-help"},
  {"id":"pl-1217","cat":"how-it-happens","type":"reflect","hook":"Lensy: noticing a 'fact' sounds too neat and pausing to check it is smart, not paranoid. Right?","prompt":"What do you think?","options":["Right","Worth a pause","I'll check first"],"affirm":"Pausing to check a too-neat claim is a smart habit, not paranoia.","relearn":"Pausing to verify a confident-sounding claim is a smart, healthy habit.","persona":"any","source":"verify the source"},
  {"id":"pl-1218","cat":"how-it-happens","type":"reflect","hook":"Lensy: the more clearly you understand your own body, the more it feels like yours. Notice that?","prompt":"What do you think?","options":["Yes","It does","Feels like mine"],"affirm":"Understanding your body makes it feel more fully your own.","relearn":"Understanding how your body works deepens your sense of owning it.","persona":"any","source":"agency"},
  {"id":"pl-1219","cat":"how-it-happens","type":"reflect","hook":"Veer: I figured this was all stuff 'real men' just know. Turns out asking is the smart move. You see it?","prompt":"What do you think?","options":["Yeah","Asking is smarter","Makes sense"],"affirm":"Asking and learning is the strong move, not pretending you already know.","relearn":"Learning the real facts is smarter than pretending you already know them.","persona":"Veer","source":"facts-help"},
  {"id":"pl-1220","cat":"how-it-happens","type":"reflect","hook":"Lensy: facts here aren't pressure. They're just a clearer picture, for whenever you want it. Okay?","prompt":"What do you think?","options":["Okay","No pressure","Good to know"],"affirm":"Knowing the facts is information, not a push. They're yours to use when you choose.","relearn":"These facts are information that protects you, never a push toward anything.","persona":"any","source":"normalising"},
  {"id":"pl-1221","cat":"how-it-happens","type":"reflect","hook":"Lensy: the calm version of these facts is way less scary than the half-rumours floating around. Agree?","prompt":"What do you think?","options":["Agree","Calmer is better","Yeah"],"affirm":"The plain, calm facts are far less frightening than the scary half-rumours.","relearn":"The accurate, calm facts are less scary than the rumours they replace.","persona":"any","source":"normalising"},
  {"id":"pl-1222","cat":"how-it-happens","type":"role-play","hook":"A classmate says 'the first time totally doesn't count.' What do you say?","setup":"Veer: 'Relax, the first time literally can't do anything.'","yourLine":[{"text":"\"That's a myth. A chance is there from the start.\"","best":true},{"text":"\"Yeah, probably true.\""}],"relearn":"A chance is there from the very first time; 'first time can't count' is a myth.","persona":"Veer","source":"reproduction facts"},
  {"id":"pl-1223","cat":"how-it-happens","type":"role-play","hook":"Someone insists they 'always know the safe day.' How do you reply?","setup":"A friend: 'I've got the safe days down, it's foolproof.'","yourLine":[{"text":"\"Cycles shift and sperm can wait. No day's foolproof.\"","best":true},{"text":"\"Cool, you'd know better than me.\""}],"relearn":"No 'safe day' is foolproof, because cycles shift and sperm can wait.","persona":"any","source":"fertility window"},
  {"id":"pl-1224","cat":"how-it-happens","type":"role-play","hook":"Riya wants the real story, not the group-chat version. What do you tell her?","setup":"Riya: 'Honestly, where do I even get the actual facts on this?'","yourLine":[{"text":"\"A doctor or trusted adult: real, private, and accurate.\"","best":true},{"text":"\"Just google around, you'll figure it out.\""}],"relearn":"Real fertility facts come from a doctor or trusted adult, private and accurate.","persona":"Riya","source":"facts-help"},
  {"id":"pl-1225","cat":"how-it-happens","type":"role-play","hook":"A friend repeats 'washing after sorts it out.' What's your line?","setup":"Friend: 'You just wash after and you're totally fine.'","yourLine":[{"text":"\"That doesn't work. Sperm may already be on the way.\"","best":true},{"text":"\"Huh, okay, maybe.\""}],"relearn":"Washing afterwards doesn't prevent pregnancy; sperm may already be on the way.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1226","cat":"how-it-happens","type":"role-play","hook":"Veer brags that pregnancy is 'just luck either way.' How do you push back?","setup":"Veer: 'It's all random luck anyway, no point knowing the details.'","yourLine":[{"text":"\"It's not luck. It follows clear biology you can learn.\"","best":true},{"text":"\"Eh, maybe you're right, who knows.\""}],"relearn":"Pregnancy isn't luck; it follows clear biology anyone can learn.","persona":"Veer","source":"reproduction"},
  {"id":"pl-1227","cat":"how-it-happens","type":"role-play","hook":"Someone claims you're 'too young for any of this to matter.' Your reply?","setup":"A classmate: 'We're too young, none of this even applies to us.'","yourLine":[{"text":"\"Once puberty starts, the biology already applies.\"","best":true},{"text":"\"True, it's not really our problem yet.\""}],"relearn":"Once puberty has begun, the biology already applies, not 'too young'.","persona":"any","source":"fertility / puberty"},
  {"id":"pl-1228","cat":"how-it-happens","type":"role-play","hook":"A friend shares a 'fertility fact' from a viral clip. What do you say?","setup":"Friend: 'This video said it, so it's definitely true.'","yourLine":[{"text":"\"Worth checking with a doctor before we trust a clip.\"","best":true},{"text":"\"If it's online it's probably right.\""}],"relearn":"A viral clip isn't proof; check a fertility claim with a doctor first.","persona":"any","source":"verify the source"},
  {"id":"pl-1229","cat":"how-it-happens","type":"role-play","hook":"Riya's nervous to ask a doctor a body question. How do you reassure her?","setup":"Riya: 'It feels so embarrassing to ask a doctor about this.'","yourLine":[{"text":"\"It's their job: private, normal, nothing to be shy about.\"","best":true},{"text":"\"Yeah, maybe just skip it then.\""}],"relearn":"Asking a doctor a body question is normal and private, nothing to be shy about.","persona":"Riya","source":"facts-help"},
  {"id":"pl-1230","cat":"how-it-happens","type":"branch","hook":"You hear a confident 'safe day' rumour at school. What do you do?","options":[{"text":"Take it as fact and repeat it","consequence":"The myth spreads; someone may trust it."},{"text":"Quietly check it with a doctor","consequence":"You get the real fact and pass on no myth.","best":true},{"text":"Argue loudly that it's wrong","consequence":"It turns into a fight and the fact is lost."}],"debrief":"Checking a rumour with a real source beats spreading or shouting.","relearn":"A confident rumour is worth quietly checking with a doctor.","persona":"any","source":"verify the source"},
  {"id":"pl-1231","cat":"how-it-happens","type":"branch","hook":"A friend insists the first time 'can't count.' How do you handle it?","options":[{"text":"Agree to avoid the awkwardness","consequence":"A risky myth goes unchallenged."},{"text":"Calmly say a chance is there from the start","consequence":"The fact lands and the myth loses ground.","best":true},{"text":"Mock them for not knowing","consequence":"They get defensive and tune out the fact."}],"debrief":"Calmly stating the fact beats agreeing or mocking.","relearn":"A chance is there from the start. Said calmly, the myth fades.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1232","cat":"how-it-happens","type":"branch","hook":"You're not sure how the fertile window really works. What's your move?","options":[{"text":"Guess from a half-remembered post","consequence":"You act on shaky info that might be wrong."},{"text":"Ask a doctor for the real picture","consequence":"You get the accurate picture, not a guess.","best":true},{"text":"Decide it's too awkward and drop it","consequence":"You stay in the dark."}],"debrief":"Asking a reliable source beats guessing or avoiding it.","relearn":"When the fertile window is unclear, a doctor gives the real picture.","persona":"any","source":"verify the source"},
  {"id":"pl-1233","cat":"how-it-happens","type":"branch","hook":"Veer shares a 'fact' he saw in porn as if it's real biology. What do you do?","options":[{"text":"Believe it, since it looks convincing","consequence":"You take performance as fact and get it wrong."},{"text":"Note porn is performance, then check a real source","consequence":"You tell performance from biology and get it right.","best":true},{"text":"Repeat it as truth","consequence":"The distortion spreads."}],"debrief":"Porn is made to sell, not teach; facts come from real ones.","relearn":"Porn is performance, not a body guide.","persona":"Veer","source":"facts-help"},
  {"id":"pl-1234","cat":"how-it-happens","type":"branch","hook":"Riya gets two opposite 'facts' from two friends. What now?","options":[{"text":"Pick whichever sounds nicer","consequence":"She may lock in the wrong one just because it felt better."},{"text":"Take both to a doctor to settle it","consequence":"The clash gets settled and she keeps the true one.","best":true},{"text":"Assume they're both right","consequence":"She ends up more confused."}],"debrief":"When sources clash, a reliable adult settles it.","relearn":"When 'facts' conflict, a doctor or trusted adult sorts out the truth.","persona":"Riya","source":"verify the source"},
  {"id":"pl-1235","cat":"how-it-happens","type":"branch","hook":"You realise you've believed a myth about how pregnancy works. What do you do?","options":[{"text":"Feel embarrassed and never mention it","consequence":"The wrong idea quietly sticks around."},{"text":"Update it calmly with the real fact","consequence":"You swap the myth for the truth, no harm done.","best":true},{"text":"Insist you were right all along","consequence":"You keep what you know is false."}],"debrief":"Updating a belief when you learn better is a strength.","relearn":"Swapping a myth for the fact is smart and normal.","persona":"any","source":"agency"},
  {"id":"pl-1236","cat":"how-it-happens","type":"branch","hook":"A classmate says 'no orgasm means no risk.' How do you respond?","options":[{"text":"Nod along to seem in the know","consequence":"A false 'rule' gets one more believer."},{"text":"Say what counts is sperm meeting egg","consequence":"The real factor is named and the myth clears up.","best":true},{"text":"Change the subject fast","consequence":"The myth stands and keeps circulating."}],"debrief":"Naming the real factor, sperm meeting egg, clears the myth.","relearn":"Orgasm isn't the factor; sperm reaching an egg is what counts.","persona":"any","source":"reproduction facts"},
  {"id":"pl-1237","cat":"how-it-happens","type":"branch","hook":"You want to understand your own cycle properly. Where do you go?","options":[{"text":"A random app's confident guesses","consequence":"You may trust a guess as if it were certain."},{"text":"A doctor who can explain your own body","consequence":"You learn your real cycle, not a hunch.","best":true},{"text":"A friend who 'just knows'","consequence":"You inherit their guesses and myths."}],"debrief":"Your body's facts come best from a doctor, not an app or hunch.","relearn":"A doctor explains your cycle better than an app or a guess.","persona":"any","source":"verify the source"},
  {"id":"pl-1260","type":"branch","hook":"Plan It: your dream is to be the first doctor in your family.","options":[{"text":"Pick study habits today that build toward it","consequence":"Your daily choices start serving the dream.","best":true},{"text":"Wait for the dream to happen on its own","consequence":"Dreams need today's choices feeding them."}],"debrief":"A goal is built by the small choices you make now.","relearn":"Today's choices build tomorrow's goal, step by step.","persona":"Riya","source":"life-sim / goals","cat":"plan-future"},
  {"id":"pl-1261","type":"branch","hook":"You've set a goal to make the district cricket team.","options":[{"text":"Line up practice and rest behind that goal","consequence":"Your routine now points at the team.","best":true},{"text":"Keep the goal but skip every practice","consequence":"A goal needs matching effort to come true."}],"debrief":"Planning lines your daily habits up behind what you want.","relearn":"Line your habits up behind the goal you care about.","persona":"Veer","source":"life-sim / sport","cat":"plan-future"},
  {"id":"pl-1262","type":"branch","hook":"Plan It: a fun choice now might quietly clash with a big plan later.","options":[{"text":"Weigh the quick fun against the long goal","consequence":"You protect the bigger thing you want.","best":true},{"text":"Only think about this minute","consequence":"Weighing now vs later is what planning is."}],"debrief":"Planning is holding the now and the later in the same view.","relearn":"Weigh a quick yes against the future you're building.","persona":"any","source":"life-sim / weighing","cat":"plan-future"},
  {"id":"pl-1263","type":"branch","hook":"A relative says a teen pregnancy would change everything for you.","options":[{"text":"Let the stakes sharpen your own reasons to be careful","consequence":"The facts become your own, not a rule.","best":true},{"text":"Push the whole thought away","consequence":"Facing the stakes calmly makes the choice yours."}],"debrief":"Knowing what's at stake makes 'be careful' your decision.","relearn":"Knowing the stakes strengthens your own reasons to wait.","persona":"any","source":"life-sim / stakes","cat":"plan-future"},
  {"id":"pl-1264","type":"branch","hook":"Plan It: you map the next three years on paper.","options":[{"text":"Put your goals first and let choices serve them","consequence":"Your decisions fall in behind your dreams.","best":true},{"text":"Drift and just react to whatever comes","consequence":"A map turns drifting into chosen steps."}],"debrief":"A plan turns scattered choices into steps toward a goal.","relearn":"A plan turns scattered choices into steps you choose.","persona":"any","source":"life-sim / mapping","cat":"plan-future"},
  {"id":"pl-1265","type":"branch","hook":"A friend says 'planning is for adults, just live for today'.","options":[{"text":"Enjoy today and keep one eye on tomorrow","consequence":"You live now and still protect later.","best":true},{"text":"Drop every plan you had","consequence":"You can enjoy today without trashing tomorrow."}],"debrief":"Living now and planning ahead are not enemies.","relearn":"You can live today and plan for tomorrow at once.","persona":"any","source":"life-sim / norms","cat":"plan-future"},
  {"id":"pl-1266","type":"branch","hook":"Plan It: a setback knocks your study plan off course.","options":[{"text":"Adjust the plan and keep moving","consequence":"Plans bend; you stay on track overall.","best":true},{"text":"Scrap the whole plan in frustration","consequence":"A plan can flex without breaking."}],"debrief":"A good plan bends around setbacks instead of shattering.","relearn":"Adjust your plan around setbacks; don't scrap it.","persona":"Veer","source":"life-sim / resilience","cat":"plan-future"},
  {"id":"pl-1267","type":"branch","hook":"You realise your dream needs choices you haven't been making.","options":[{"text":"Start matching your choices to the goal","consequence":"You close the gap between dream and habit.","best":true},{"text":"Keep the dream but ignore the steps","consequence":"A goal is only as real as the steps you take."}],"debrief":"A dream stays a wish until your choices feed it.","relearn":"Match your daily choices to the goal you care about.","persona":"any","source":"life-sim / alignment","cat":"plan-future"},
  {"id":"pl-1268","type":"branch","hook":"Plan It: someone pressures you toward a choice that risks your plan.","options":[{"text":"Hold your pace and protect your plan","consequence":"Your goal stays safe and so do you.","best":true},{"text":"Give in just to end the pressure","consequence":"Your plan is yours to guard; pressure isn't a reason."}],"debrief":"Holding your pace protects the future you're planning.","relearn":"Holding your pace protects the future you're building.","persona":"Riya","source":"life-sim / pressure","cat":"plan-future"},
  {"id":"pl-1269","type":"branch","hook":"You want to study abroad one day. That's the goal on the board.","options":[{"text":"Treat today's choices as bricks for that goal","consequence":"Each smart choice lays another brick.","best":true},{"text":"Assume luck will sort it out later","consequence":"Goals are built, not won in a lottery."}],"debrief":"Big goals are built brick by brick from today's choices.","relearn":"Build a big goal brick by brick from today's choices.","persona":"Riya","source":"life-sim / future","cat":"plan-future"},
  {"id":"pl-1270","type":"branch","hook":"Plan It: two paths, one feels easy now, one serves your plan.","options":[{"text":"Pick the path that serves your real goal","consequence":"Future-you is glad you looked ahead.","best":true},{"text":"Take the easy path with eyes shut","consequence":"The easy now can cost the goal later."}],"debrief":"The easiest path now isn't always the one that gets you there.","relearn":"Choose the path that serves the goal, not just the moment.","persona":"any","source":"life-sim / paths","cat":"plan-future"},
  {"id":"pl-1271","type":"branch","hook":"Your goal is to start a small business after school.","options":[{"text":"Make choices that keep that door open","consequence":"You protect the option you care about.","best":true},{"text":"Make a choice that quietly shuts the door","consequence":"Some choices close doors you wanted open."}],"debrief":"Planning is keeping the doors you care about open.","relearn":"Make choices that keep your future doors open.","persona":"Veer","source":"life-sim / options","cat":"plan-future"},
  {"id":"pl-1272","type":"branch","hook":"Plan It: a choice today, a ripple, an option later, your goal.","options":[{"text":"Trace how today's choice reaches your goal","consequence":"You see the whole ripple clearly.","best":true},{"text":"Treat today as cut off from the future","consequence":"Today and tomorrow are linked by a ripple."}],"debrief":"Choices ripple: today touches your options and your goal.","relearn":"Choices ripple: today's choice shapes tomorrow's goal.","persona":"any","source":"life-sim / ripple","cat":"plan-future"},
  {"id":"pl-1273","type":"branch","hook":"A classmate brags that real plans are 'boring' and spontaneous is cooler.","options":[{"text":"Keep your plan and stay open to surprises","consequence":"You can be planned and still spontaneous.","best":true},{"text":"Throw out the plan to seem cool","consequence":"A plan doesn't cancel fun; it protects it."}],"debrief":"A plan can hold both: steady goals and room for surprises.","relearn":"A plan protects fun; it doesn't cancel it.","persona":"Veer","source":"life-sim / norms","cat":"plan-future"},
  {"id":"pl-1274","type":"branch","hook":"Plan It: you're tempted to copy a friend's risky choice.","options":[{"text":"Decide by your own plan, not their move","consequence":"Your goal stays yours and protected.","best":true},{"text":"Just match whatever your friend does","consequence":"Your friend's plan isn't yours to follow."}],"debrief":"Your choices answer to your goals, not a friend's dare.","relearn":"Decide by your own plan, not someone else's move.","persona":"any","source":"life-sim / agency","cat":"plan-future"},
  {"id":"pl-1275","type":"branch","hook":"You want top marks AND time for football. Both matter to you.","options":[{"text":"Plan a week that makes room for both","consequence":"You protect study and the thing you love.","best":true},{"text":"Let one swallow the other by accident","consequence":"Without a plan, one goal eats the rest."}],"debrief":"A plan can guard more than one thing you care about.","relearn":"Plan so the goals you love both get room.","persona":"Veer","source":"life-sim / balance","cat":"plan-future"},
  {"id":"pl-1276","type":"branch","hook":"Plan It: a 'small' choice now turns out to matter a lot later.","options":[{"text":"Treat small choices as worth a thought","consequence":"You catch the ones that quietly count.","best":true},{"text":"Wave off every small choice as nothing","consequence":"Small choices can carry big ripples."}],"debrief":"Even small choices can ripple toward or away from a goal.","relearn":"Small choices can carry big ripples; give them a thought.","persona":"any","source":"life-sim / ripple","cat":"plan-future"},
  {"id":"pl-1277","type":"branch","hook":"Your future-you, ten years on, could send a note back to today.","options":[{"text":"Make the choice future-you would thank you for","consequence":"You plan with the long view in mind.","best":true},{"text":"Ignore what future-you would want","consequence":"Future-you lives with today's choices."}],"debrief":"Planning is choosing for the you who has to live it.","relearn":"Choose what future-you would thank you for.","persona":"any","source":"life-sim / future","cat":"plan-future"},
  {"id":"pl-1278","type":"branch","hook":"Plan It: your goal needs a steady habit, not a one-time burst.","options":[{"text":"Build the small habit and repeat it","consequence":"Steady habits move the goal forward.","best":true},{"text":"Wait for one giant heroic effort","consequence":"Goals are reached by steady habits, not bursts."}],"debrief":"Most goals are won by steady habits, not single bursts.","relearn":"Steady habits beat one giant burst toward a goal.","persona":"Riya","source":"life-sim / habits","cat":"plan-future"},
  {"id":"pl-1279","type":"branch","hook":"A choice could derail your plan, and you can see it coming.","options":[{"text":"Spot the risk early and steer around it","consequence":"You protect the plan before it's hit.","best":true},{"text":"Walk into the risk with eyes open","consequence":"Spotting a risk early lets you steer."}],"debrief":"Planning means spotting what could derail you, in time.","relearn":"Spot risks to your plan early and steer around them.","persona":"any","source":"life-sim / foresight","cat":"plan-future"},
  {"id":"pl-1280","type":"branch","hook":"Plan It: you're asked to trade a long goal for a quick thrill.","options":[{"text":"Keep the long goal; the thrill can wait","consequence":"Your bigger want stays protected.","best":true},{"text":"Trade the goal away for the thrill","consequence":"A quick thrill rarely beats the real goal."}],"debrief":"A quick thrill rarely outweighs the goal you've set.","relearn":"Don't trade a long goal for a quick thrill.","persona":"Veer","source":"life-sim / weighing","cat":"plan-future"},
  {"id":"pl-1281","type":"branch","hook":"Your plan feels too big and you want to quit it.","options":[{"text":"Break the big goal into next small steps","consequence":"One next step makes the goal doable.","best":true},{"text":"Drop the goal because it's big","consequence":"Big goals shrink when you split them up."}],"debrief":"A big goal gets doable when you split it into steps.","relearn":"Break a big goal into the next small step.","persona":"Riya","source":"life-sim / steps","cat":"plan-future"},
  {"id":"pl-1282","type":"branch","hook":"Plan It: knowing how pregnancy happens changes how you plan.","options":[{"text":"Let the facts shape a plan you own","consequence":"Your plan rests on facts, not rumours.","best":true},{"text":"Plan around a rumour instead","consequence":"Plans built on rumours crack; facts hold."}],"debrief":"Real facts make a sturdier plan than rumours do.","relearn":"Build your plan on facts, not rumours.","persona":"any","source":"life-sim / facts","cat":"plan-future"},
  {"id":"pl-1283","type":"branch","hook":"You and a friend both have goals but only one of you plans.","options":[{"text":"Make a simple plan so your goal moves","consequence":"A plan turns your wish into motion.","best":true},{"text":"Leave it all to hope like your friend","consequence":"Hope alone rarely moves a goal."}],"debrief":"A plan, even a simple one, beats hope alone.","relearn":"A simple plan beats leaving a goal to hope.","persona":"any","source":"life-sim / planning","cat":"plan-future"},
  {"id":"pl-1284","type":"branch","hook":"Plan It: a choice that protects your goal also keeps you safer.","options":[{"text":"Notice the choice does both at once","consequence":"Goal and safety can point the same way.","best":true},{"text":"Assume safety and goals always clash","consequence":"Often the smart choice serves both."}],"debrief":"Sometimes the choice that guards your goal guards you too.","relearn":"A smart choice can protect your goal and you at once.","persona":"any","source":"life-sim / overlap","cat":"plan-future"},
  {"id":"pl-1285","type":"branch","hook":"You define the future you want; no one hands you a 'correct' life.","options":[{"text":"Name the future that's actually yours","consequence":"Your plan answers to your own dream.","best":true},{"text":"Copy a life someone else picked for you","consequence":"The future you want is yours to define."}],"debrief":"The future you're planning is yours to define, not a script.","relearn":"The future you want is yours to define.","persona":"Riya","source":"life-sim / agency","cat":"plan-future"},
  {"id":"pl-1286","type":"branch","hook":"Plan It: a detour appears that delays your goal but isn't a dead end.","options":[{"text":"Take the detour and keep the goal in sight","consequence":"A delay isn't the end of the plan.","best":true},{"text":"Treat the detour as total failure","consequence":"A detour can still reach the goal."}],"debrief":"A delay or detour isn't the same as giving up.","relearn":"A detour can still reach the goal; keep it in sight.","persona":"Veer","source":"life-sim / resilience","cat":"plan-future"},
  {"id":"pl-1287","type":"branch","hook":"Your goal needs support you can't give yourself.","options":[{"text":"Ask a trusted adult to back your plan","consequence":"Support makes the plan more solid.","best":true},{"text":"Try to carry the whole plan alone","consequence":"Good plans can lean on support."}],"debrief":"Asking for support is part of a strong plan, not a weakness.","relearn":"Asking for support can make a plan stronger.","persona":"any","source":"life-sim / support","cat":"plan-future"},
  {"id":"pl-1288","type":"branch","hook":"Plan It: you can choose how today's choice ripples toward your goal.","options":[{"text":"Choose the ripple you actually want","consequence":"You steer the ripple, not just ride it.","best":true},{"text":"Let the ripple go wherever","consequence":"You can aim the ripple toward your goal."}],"debrief":"You don't just watch the ripple; you can aim it.","relearn":"You can aim today's ripple toward the goal you want.","persona":"any","source":"life-sim / agency","cat":"plan-future"},
  {"id":"pl-1289","type":"branch","hook":"A goal you set last year doesn't fit you anymore.","options":[{"text":"Update the goal to the you of now","consequence":"Your plan grows as you do.","best":true},{"text":"Cling to a goal that's no longer yours","consequence":"Goals can be revised as you change."}],"debrief":"A plan can be revised; goals grow up with you.","relearn":"It's fine to update a goal as you change.","persona":"Riya","source":"life-sim / revision","cat":"plan-future"},
  {"id":"pl-1290","type":"branch","hook":"Plan It: waiting and being careful are tools, not rules thrown at you.","options":[{"text":"Use them as tools that guard your plan","consequence":"They serve the future you chose.","best":true},{"text":"Treat them as rules to resent","consequence":"Used as tools, they protect your own goals."}],"debrief":"Waiting and care are tools that protect your own plan.","relearn":"Waiting and care are tools that guard your own future.","persona":"any","source":"life-sim / framing","cat":"plan-future"},
  {"id":"pl-1291","type":"branch","hook":"You want to picture how one choice today reaches a goal years away.","options":[{"text":"Trace the line from choice to goal","consequence":"The long link becomes clear to you.","best":true},{"text":"Decide the link is impossible to see","consequence":"The line from choice to goal can be traced."}],"debrief":"You can trace one choice all the way to a far goal.","relearn":"Trace the line from today's choice to a far goal.","persona":"any","source":"life-sim / ripple","cat":"plan-future"},
  {"id":"pl-1292","type":"build","hook":"Build a simple 'protect my future' plan.","prompt":"Order the planning steps.","pieces":["name a goal that matters","spot a choice that could derail it","decide how you'll protect it","ask for support if you need it"],"mode":"sequence","key":["name a goal that matters","spot a choice that could derail it","decide how you'll protect it","ask for support if you need it"],"relearn":"Protect a goal: name it, spot risks, decide, get support.","persona":"any","source":"life-sim / planning","cat":"plan-future"},
  {"id":"pl-1293","type":"build","hook":"Build the 'choices ripple' chain.","prompt":"Assemble how a choice today reaches the future.","pieces":["a choice today","leads to a consequence","which shapes your options later","which shapes your goal"],"mode":"sequence","key":["a choice today","leads to a consequence","which shapes your options later","which shapes your goal"],"relearn":"Choices ripple: a choice today reaches your future goal.","persona":"any","source":"life-sim / ripple","cat":"plan-future"},
  {"id":"pl-1294","type":"build","hook":"Build YOUR own reasons to wait or be careful.","prompt":"Assemble reasons that are yours.","pieces":["my goals come first","I want to be truly ready","my health is mine to protect","my future is mine to plan"],"mode":"assemble","key":["my goals come first","I want to be truly ready","my health is mine to protect","my future is mine to plan"],"relearn":"Your own reasons to wait or be careful are valid and strong.","persona":"Riya","source":"life-sim / values","cat":"plan-future"},
  {"id":"pl-1295","type":"build","hook":"Build the steps to set a goal you'll actually keep.","prompt":"Order the goal-setting steps.","pieces":["pick something you truly want","make it clear and real","name the first small step","check it's still yours over time"],"mode":"sequence","key":["pick something you truly want","make it clear and real","name the first small step","check it's still yours over time"],"relearn":"Set a goal: want it, make it clear, take a first step, revisit it.","persona":"any","source":"life-sim / goals","cat":"plan-future"},
  {"id":"pl-1296","type":"build","hook":"Build a plan that survives a setback.","prompt":"Order the bounce-back steps.","pieces":["notice the plan got knocked","keep the goal in sight","adjust the next step","start moving again"],"mode":"sequence","key":["notice the plan got knocked","keep the goal in sight","adjust the next step","start moving again"],"relearn":"A plan survives a setback: notice, keep the goal, adjust, restart.","persona":"Veer","source":"life-sim / resilience","cat":"plan-future"},
  {"id":"pl-1297","type":"build","hook":"Build a 'weigh now vs later' check for a tempting choice.","prompt":"Order the weighing steps.","pieces":["name the quick yes","name the long goal","ask which one you'll value tomorrow","choose with the goal in view"],"mode":"sequence","key":["name the quick yes","name the long goal","ask which one you'll value tomorrow","choose with the goal in view"],"relearn":"Weigh a choice: name the now, name the goal, pick for tomorrow.","persona":"any","source":"life-sim / weighing","cat":"plan-future"},
  {"id":"pl-1298","type":"build","hook":"Build a kit of things that keep a goal on track.","prompt":"Assemble what helps a plan hold.","pieces":["a clear goal","steady small habits","a trusted person to lean on","a way to spot risks early"],"mode":"assemble","key":["a clear goal","steady small habits","a trusted person to lean on","a way to spot risks early"],"relearn":"A goal holds with: clarity, habits, support, and early warning.","persona":"any","source":"life-sim / kit","cat":"plan-future"},
  {"id":"pl-1299","type":"build","hook":"Build the steps to turn a big dream into a doable plan.","prompt":"Order the shrink-it-down steps.","pieces":["name the big dream","split it into stages","pick the very next step","do that step today"],"mode":"sequence","key":["name the big dream","split it into stages","pick the very next step","do that step today"],"relearn":"Shrink a dream: name it, stage it, pick a step, start today.","persona":"Riya","source":"life-sim / steps","cat":"plan-future"},
  {"id":"pl-1300","type":"build","hook":"Build what 'planning your future' actually means.","prompt":"Assemble the parts of real planning.","pieces":["knowing what you want","seeing how today touches it","making choices that serve it","adjusting as life shifts"],"mode":"assemble","key":["knowing what you want","seeing how today touches it","making choices that serve it","adjusting as life shifts"],"relearn":"Planning = know the want, see the link, choose for it, adjust.","persona":"any","source":"life-sim / planning","cat":"plan-future"},
  {"id":"pl-1301","type":"build","hook":"Build a way to hold your pace AND protect your plan.","prompt":"Order the hold-your-pace steps.","pieces":["remember the goal that's yours","feel the pressure without obeying it","say a calm clear no","keep your plan moving"],"mode":"sequence","key":["remember the goal that's yours","feel the pressure without obeying it","say a calm clear no","keep your plan moving"],"relearn":"Hold your pace: recall the goal, resist pressure, say no, move on.","persona":"Riya","source":"life-sim / pressure","cat":"plan-future"},
  {"id":"pl-1302","type":"build","hook":"Build the link between facts and a sturdy plan.","prompt":"Order how facts make a plan strong.","pieces":["get the real facts","drop the rumours","build the plan on what's true","trust it because it's solid"],"mode":"sequence","key":["get the real facts","drop the rumours","build the plan on what's true","trust it because it's solid"],"relearn":"Facts make a sturdy plan; rumours make one that cracks.","persona":"any","source":"life-sim / facts","cat":"plan-future"},
  {"id":"pl-1303","type":"build","hook":"Build a list of doors you want to keep open.","prompt":"Assemble the doors worth protecting.","pieces":["my studies","a career I'd love","people I care about","my own health and time"],"mode":"assemble","key":["my studies","a career I'd love","people I care about","my own health and time"],"relearn":"Planning keeps the doors you care about open, on purpose.","persona":"Veer","source":"life-sim / options","cat":"plan-future"},
  {"id":"pl-1304","type":"build","hook":"Build a 'future-you' message to guide today's choice.","prompt":"Order the future-you steps.","pieces":["picture you in ten years","ask what they'd want","bring that wish to today","choose with it in mind"],"mode":"sequence","key":["picture you in ten years","ask what they'd want","bring that wish to today","choose with it in mind"],"relearn":"Let future-you guide today: picture, ask, carry it, choose.","persona":"any","source":"life-sim / future","cat":"plan-future"},
  {"id":"pl-1305","type":"build","hook":"Build what makes a goal truly YOURS, not handed to you.","prompt":"Assemble what makes a goal yours.","pieces":["you chose it, not someone else","it fits who you are","you can say why it matters","you can change it if you change"],"mode":"assemble","key":["you chose it, not someone else","it fits who you are","you can say why it matters","you can change it if you change"],"relearn":"A goal is yours when you chose it, own it, and can revise it.","persona":"Riya","source":"life-sim / agency","cat":"plan-future"},
  {"id":"pl-1306","type":"reflect","hook":"Lensy: what's one dream you're protecting by planning ahead?","prompt":"Think of one.","options":["My studies","A sport or art","A career","Just my freedom"],"affirm":"Keep that dream in view; your choices can guard it.","relearn":"Naming the dream you're protecting makes planning real.","persona":"any","source":"life-sim / motivation","cat":"plan-future"},
  {"id":"pl-1307","type":"reflect","hook":"Lensy: a five-year plan isn't a cage. It's a map you're allowed to redraw. Useful?","prompt":"What do you think?","options":["Yes","I can adjust it","Plans can flex"],"affirm":"A plan guides you, but you can revise it as life changes.","relearn":"Plans are flexible maps you can update as your goals shift.","persona":"any","source":"life-sim / planning","cat":"plan-future"},
  {"id":"pl-1308","type":"reflect","hook":"Lensy: when you picture 'future-you', who do you see?","prompt":"Picture them.","options":["Someone proud of me","Someone who kept their pace","Someone free to choose","Still figuring it out"],"affirm":"Whoever you see, today's choices help you get there.","relearn":"Picturing future-you makes today's choices feel real.","persona":"any","source":"life-sim / future","cat":"plan-future"},
  {"id":"pl-1309","type":"reflect","hook":"Lensy: there's no deadline on your plans but your own readiness. Sit with that.","prompt":"How's that land?","options":["A relief","My timeline, my call","Less pressure"],"affirm":"No 'right age' but yours; your timeline is yours to set.","relearn":"There's no deadline on your future but your own readiness.","persona":"any","source":"life-sim / readiness","cat":"plan-future"},
  {"id":"pl-1310","type":"reflect","hook":"Lensy: which feels more like you: a steady plan or going with the flow?","prompt":"No wrong answer.","options":["A steady plan","Going with the flow","A bit of both"],"affirm":"Either can protect your goals if you stay in charge of it.","relearn":"Both planning and flow can work when the choice is yours.","persona":"any","source":"life-sim / style","cat":"plan-future"},
  {"id":"pl-1311","type":"reflect","hook":"Lensy: knowing the facts can make your own plan stronger. Does that fit you?","prompt":"What do you feel?","options":["Yes, facts help","I'd rather know","Knowledge is power"],"affirm":"Real facts are a tool that protects the plan you're building.","relearn":"Accurate facts are a tool that strengthens your own plan.","persona":"any","source":"life-sim / facts","cat":"plan-future"},
  {"id":"pl-1312","type":"reflect","hook":"Lensy: waiting is a common, healthy choice at your age. How does that sit?","prompt":"Take a moment.","options":["Reassuring","Good to hear","Makes sense"],"affirm":"Waiting is valid, common and respected, never second-best.","relearn":"Waiting is a common, healthy, respected choice at this age.","persona":"any","source":"life-sim / readiness","cat":"plan-future"},
  {"id":"pl-1313","type":"reflect","hook":"Lensy: whose plan for your life matters most?","prompt":"Think honestly.","options":["Mine","Mine, with people I trust","I'm working it out"],"affirm":"Your future is yours to define; trusted people can help.","relearn":"The future you want is yours to define and protect.","persona":"Riya","source":"life-sim / agency","cat":"plan-future"},
  {"id":"pl-1314","type":"reflect","hook":"Lensy: one small choice today could protect a big goal. Notice that power.","prompt":"Feel it?","options":["Yes","Small choices count","That's motivating"],"affirm":"Small choices carry real weight toward the goal you want.","relearn":"Even a small choice today can protect a big goal.","persona":"any","source":"life-sim / ripple","cat":"plan-future"},
  {"id":"pl-1315","type":"role-play","setup":"A friend says skip your goal and just have fun now, like everyone else.","yourLine":[{"text":"This is my plan; I can have fun without dropping it.","best":true},{"text":"Maybe you're right, I'll forget the plan."},{"text":"I guess planning is pointless anyway."}],"relearn":"You can hold your plan and still enjoy yourself.","hook":"A friend says skip your goal and just have fun now, like everyone else.","persona":"Veer","source":"life-sim / pressure","cat":"plan-future"},
  {"id":"pl-1316","type":"role-play","setup":"Someone pushes you toward a choice that would derail your dream.","yourLine":[{"text":"No. That doesn't fit the future I'm building.","best":true},{"text":"Fine, if it makes you stop asking."},{"text":"I don't know, maybe my dream isn't worth it."}],"relearn":"A calm, clear no protects the plan you've chosen.","hook":"Someone pushes you toward a choice that would derail your dream.","persona":"Riya","source":"life-sim / pressure","cat":"plan-future"},
  {"id":"pl-1317","type":"role-play","setup":"A cousin says 'why bother planning, life just happens'.","yourLine":[{"text":"I'd rather steer my life than only react to it.","best":true},{"text":"Yeah, planning is probably useless."},{"text":"I'll just see what happens, I guess."}],"relearn":"You can steer your life instead of only reacting.","hook":"A cousin says 'why bother planning, life just happens'.","persona":"Veer","source":"life-sim / norms","cat":"plan-future"},
  {"id":"pl-1318","type":"role-play","setup":"A friend mocks you for thinking years ahead.","yourLine":[{"text":"Thinking ahead is how I protect what I want.","best":true},{"text":"You're right, it's silly to look ahead."},{"text":"Maybe I shouldn't bother with goals."}],"relearn":"Looking ahead protects the things you care about.","hook":"A friend mocks you for thinking years ahead.","persona":"any","source":"life-sim / norms","cat":"plan-future"},
  {"id":"pl-1319","type":"role-play","setup":"Someone says 'if you really liked me you'd drop your plans for me'.","yourLine":[{"text":"Real care wouldn't ask me to drop my future.","best":true},{"text":"Okay, my plans aren't that important."},{"text":"Maybe I should just give them up."}],"relearn":"Care that asks you to abandon your future isn't care.","hook":"Someone says 'if you really liked me you'd drop your plans for me'.","persona":"Riya","source":"life-sim / pressure","cat":"plan-future"},
  {"id":"pl-1320","type":"role-play","setup":"A friend says you'll never reach your big goal anyway.","yourLine":[{"text":"I'm taking the next step toward it regardless.","best":true},{"text":"You're probably right, why try."},{"text":"Maybe I should just quit."}],"relearn":"One next step keeps a big goal alive against doubt.","hook":"A friend says you'll never reach your big goal anyway.","persona":"Veer","source":"life-sim / resilience","cat":"plan-future"},
  {"id":"pl-1321","type":"role-play","setup":"Someone says 'everyone's doing it, your plan makes you weird'.","yourLine":[{"text":"'Everyone' is a myth; my pace is my choice.","best":true},{"text":"I don't want to seem weird, so okay."},{"text":"Maybe I should just go along with it."}],"relearn":"'Everyone's doing it' is a myth you can hold your pace against.","hook":"Someone says 'everyone's doing it, your plan makes you weird'.","persona":"Riya","source":"life-sim / norms","cat":"plan-future"},
  {"id":"pl-1322","type":"role-play","setup":"A friend wants you to copy their risky shortcut.","yourLine":[{"text":"My plan's working; I'll stick to my own path.","best":true},{"text":"Sure, I'll just do whatever you do."},{"text":"I guess my path doesn't matter."}],"relearn":"You answer to your own plan, not a friend's shortcut.","hook":"A friend wants you to copy their risky shortcut.","persona":"any","source":"life-sim / agency","cat":"plan-future"},
  {"id":"pl-1323","type":"strike-rewrite","hook":"Plan It myth check: 'planning your future is a waste of time'.","myth":{"un":"Planning your future is a waste of time.","re":"Planning lines today's choices up behind the goals you want.","why":"A plan turns scattered choices into real steps toward a dream."},"relearn":"Planning lines your choices up behind your goals.","persona":"any","source":"life-sim / myths","cat":"plan-future"},
  {"id":"pl-1324","type":"strike-rewrite","hook":"Plan It myth check: 'today's choice has nothing to do with my future'.","myth":{"un":"Today's choice has nothing to do with my future.","re":"Today's choices ripple forward and shape tomorrow's options.","why":"Each choice now touches the options and goals you'll have later."},"relearn":"Today's choices ripple forward to shape your future.","persona":"any","source":"life-sim / myths","cat":"plan-future"},
  {"id":"pl-1325","type":"strike-rewrite","hook":"Plan It myth check: 'learning these facts is just pressure to grow up fast'.","myth":{"un":"Learning these facts is pressure to grow up fast.","re":"Accurate facts are protection; they help teens wait and stay safer.","why":"Good information helps you plan and pace yourself, not rush."},"relearn":"Accurate facts protect you; they don't push you to rush.","persona":"Veer","source":"life-sim / framing","cat":"plan-future"},
  {"id":"pl-1326","type":"strike-rewrite","hook":"Plan It myth check: 'a teen pregnancy wouldn't change my plans much'.","myth":{"un":"A teen pregnancy wouldn't change my plans much.","re":"An unplanned teen pregnancy would change a lot of plans.","why":"Knowing that is honest, not scary, and strengthens your reasons to be careful."},"relearn":"Knowing the stakes strengthens your own reasons to be careful.","persona":"any","source":"life-sim / stakes","cat":"plan-future"},
  {"id":"pl-1327","type":"strike-rewrite","hook":"Plan It myth check: 'waiting means something's wrong with my plan or me'.","myth":{"un":"Waiting means something's wrong with me.","re":"Waiting is a healthy, common, respected choice, never a flaw.","why":"Most teens this age are waiting; it's a valid part of any plan."},"relearn":"Waiting is healthy and common; it's never a deficiency.","persona":"Riya","source":"life-sim / readiness","cat":"plan-future"},
  {"id":"pl-1328","type":"strike-rewrite","hook":"Plan It myth check: 'a plan has to be perfect or it's useless'.","myth":{"un":"A plan has to be perfect or it's useless.","re":"A good plan flexes around setbacks instead of needing to be perfect.","why":"Plans that bend and adjust survive real life far better."},"relearn":"A good plan bends around setbacks; it needn't be perfect.","persona":"Veer","source":"life-sim / resilience","cat":"plan-future"},
  {"id":"pl-1329","type":"strike-rewrite","hook":"Plan It myth check: 'someone else decides what future I'm allowed to want'.","myth":{"un":"Someone else decides what future I'm allowed to want.","re":"The future you want is yours to define; no one scripts it for you.","why":"Your goals can fit who you are and change as you grow."},"relearn":"The future you want is yours to define.","persona":"Riya","source":"life-sim / agency","cat":"plan-future"},
  {"id":"pl-1330","type":"strike-rewrite","hook":"Plan It myth check: 'careful choices are just boring rules adults impose'.","myth":{"un":"Careful choices are just boring rules adults impose.","re":"Waiting and care are tools that protect the goals you chose yourself.","why":"Used as your own tools, they guard your plan, not cage you."},"relearn":"Careful choices are tools that protect your own goals.","persona":"Veer","source":"life-sim / framing","cat":"plan-future"},
  {"id":"pl-1331","type":"match","hook":"Plan It: match each choice today to the future it shapes.","pairs":[{"left":"Study a little each day","right":"Marks that open your next door"},{"left":"Practise your sport","right":"A real shot at the team"},{"left":"Hold your pace under pressure","right":"A plan that stays yours"},{"left":"Ask a doctor real questions","right":"Facts you can plan on"},{"left":"Adjust after a setback","right":"A goal still in reach"}],"relearn":"Plan It: match each choice today to the future it shapes.","persona":"any","source":"life-sim / ripple","cat":"plan-future"},
  {"id":"pl-1332","type":"match","hook":"Plan It: match the goal to the choice that serves it.","pairs":[{"left":"Become a doctor","right":"Steady study habits now"},{"left":"Make the district team","right":"Regular practice and rest"},{"left":"Start a business","right":"Keep your options open"},{"left":"Study abroad","right":"Smart choices, brick by brick"},{"left":"Protect your health","right":"Facts over rumours"}],"relearn":"Plan It: match the goal to the choice that serves it.","persona":"Riya","source":"life-sim / goals","cat":"plan-future"},
  {"id":"pl-1333","type":"match","hook":"Plan It: match each planning idea to what it means.","pairs":[{"left":"Choices ripple","right":"Today touches tomorrow"},{"left":"Weigh now vs later","right":"Pick for future-you"},{"left":"Adjust the plan","right":"Bend, don't break"},{"left":"Hold your pace","right":"Your timeline, your call"},{"left":"Get the facts","right":"A sturdier plan"}],"relearn":"Plan It: match each planning idea to what it means.","persona":"any","source":"life-sim / concepts","cat":"plan-future"},
  {"id":"pl-1334","type":"match","hook":"Plan It: match the setback to a smart next move.","pairs":[{"left":"Plan got knocked off course","right":"Adjust and keep going"},{"left":"Goal feels too big","right":"Split it into steps"},{"left":"Someone pressures you","right":"Hold your pace, say no"},{"left":"Goal no longer fits you","right":"Update it to now"},{"left":"Plan needs more than you","right":"Ask for support"}],"relearn":"Plan It: match the setback to a smart next move.","persona":"Veer","source":"life-sim / resilience","cat":"plan-future"},
  {"id":"pl-1335","type":"match","hook":"Plan It: match the myth to the fact that replaces it.","pairs":[{"left":"Planning is useless","right":"A plan turns choices into steps"},{"left":"Today doesn't touch later","right":"Choices ripple forward"},{"left":"Waiting is a flaw","right":"Waiting is healthy and common"},{"left":"Facts are just pressure","right":"Facts protect and help you wait"},{"left":"Your future is scripted","right":"The future you want is yours"}],"relearn":"Plan It: match the myth to the fact that replaces it.","persona":"any","source":"life-sim / myths","cat":"plan-future"},
  {"id":"pl-1336","type":"match","hook":"Plan It: match each part of a plan to its job.","pairs":[{"left":"A clear goal","right":"Points you somewhere"},{"left":"Steady habits","right":"Move you toward it"},{"left":"A trusted person","right":"Backs you up"},{"left":"Spotting risks early","right":"Keeps you on track"},{"left":"Room to adjust","right":"Survives surprises"}],"relearn":"Plan It: match each part of a plan to its job.","persona":"any","source":"life-sim / kit","cat":"plan-future"},
  {"id":"pl-1337","type":"match","hook":"Plan It: match the pressure line to a calm reply.","pairs":[{"left":"'Everyone's doing it'","right":"'Everyone' is a myth"},{"left":"'If you liked me, you would'","right":"Real care waits for my yes"},{"left":"'Drop your plans for me'","right":"My future isn't yours to drop"},{"left":"'Planning is boring'","right":"It protects what I want"},{"left":"'You'll never make it'","right":"I'm taking the next step"}],"relearn":"Plan It: match the pressure line to a calm reply.","persona":"Riya","source":"life-sim / pressure","cat":"plan-future"},
  {"id":"pl-1338","type":"match","hook":"Plan It: match the future-you idea to today's action.","pairs":[{"left":"Future-you in ten years","right":"Choose what they'd thank you for"},{"left":"A door you want open","right":"Don't quietly shut it"},{"left":"A goal that's yours","right":"Make choices that serve it"},{"left":"A dream too big to face","right":"Take one small step"},{"left":"A risk you can see coming","right":"Steer around it early"}],"relearn":"Plan It: match the future-you idea to today's action.","persona":"any","source":"life-sim / future","cat":"plan-future"},
  {"id":"pl-1339","type":"sort","hook":"Plan It: sort each idea: does it protect your plan or weaken it?","items":[{"id":"a","text":"name a clear goal"},{"id":"b","text":"make steady habits"},{"id":"c","text":"get the real facts"},{"id":"d","text":"plan on a rumour"},{"id":"e","text":"ignore how choices ripple"},{"id":"f","text":"quit at the first setback"}],"bins":[{"id":"protect","label":"Protects the plan","valence":"pos"},{"id":"weaken","label":"Weakens the plan","valence":"neg"}],"key":{"a":"protect","b":"protect","c":"protect","d":"weaken","e":"weaken","f":"weaken"},"relearn":"Protect a plan with goals, habits and facts, not rumours or quitting.","persona":"any","source":"life-sim / sort","cat":"plan-future"},
  {"id":"pl-1340","type":"sort","hook":"Plan It: sort each line: a real planning move or a myth?","items":[{"id":"a","text":"choices ripple to my goal"},{"id":"b","text":"facts make a sturdier plan"},{"id":"c","text":"waiting is a valid choice"},{"id":"d","text":"today can't touch my future"},{"id":"e","text":"planning is a waste of time"},{"id":"f","text":"waiting means I'm broken"}],"bins":[{"id":"real","label":"True planning move","valence":"pos"},{"id":"myth","label":"Myth to drop","valence":"neg"}],"key":{"a":"real","b":"real","c":"real","d":"myth","e":"myth","f":"myth"},"relearn":"Keep the true planning moves; drop the myths about waiting and time.","persona":"any","source":"life-sim / sort","cat":"plan-future"},
  {"id":"pl-1341","type":"sort","hook":"Plan It: sort each choice: does it keep a future door open or shut it?","items":[{"id":"a","text":"study a bit each day"},{"id":"b","text":"ask a doctor real questions"},{"id":"c","text":"hold your pace under pressure"},{"id":"d","text":"copy a risky shortcut"},{"id":"e","text":"ignore a risk you can see"},{"id":"f","text":"trade your goal for a thrill"}],"bins":[{"id":"open","label":"Keeps a door open","valence":"pos"},{"id":"shut","label":"Shuts a door","valence":"neg"}],"key":{"a":"open","b":"open","c":"open","d":"shut","e":"shut","f":"shut"},"relearn":"Smart choices keep your doors open; risky shortcuts shut them.","persona":"Veer","source":"life-sim / sort","cat":"plan-future"},
  {"id":"pl-1342","type":"sort","hook":"Plan It: sort each move: say it out loud, or just sit with it?","items":[{"id":"a","text":"tell a friend your real goal"},{"id":"b","text":"ask a trusted adult for support"},{"id":"c","text":"say a calm clear no"},{"id":"d","text":"picture future-you quietly"},{"id":"e","text":"weigh a choice in your head"},{"id":"f","text":"sit with your own readiness"}],"bins":[{"id":"speak","label":"Speak it up","valence":"tell"},{"id":"hold","label":"Hold it quietly","valence":"neutral"}],"key":{"a":"speak","b":"speak","c":"speak","d":"hold","e":"hold","f":"hold"},"relearn":"Some planning is spoken aloud; some is quiet reflection. Both count.","persona":"any","source":"life-sim / sort","cat":"plan-future"},
  {"id":"pl-1343","type":"sort","hook":"Plan It: sort each habit: steady toward a goal, or risky for it?","items":[{"id":"a","text":"practise a little daily"},{"id":"b","text":"rest so you can keep going"},{"id":"c","text":"check your goal still fits"},{"id":"d","text":"skip every step and hope"},{"id":"e","text":"let pressure decide for you"},{"id":"f","text":"scrap the plan when it's hard"}],"bins":[{"id":"steady","label":"Steady toward the goal","valence":"pos"},{"id":"risky","label":"Risky for the goal","valence":"uhoh"}],"key":{"a":"steady","b":"steady","c":"steady","d":"risky","e":"risky","f":"risky"},"relearn":"Steady habits move a goal; hoping and quitting put it at risk.","persona":"Riya","source":"life-sim / sort","cat":"plan-future"},
  {"id":"pl-1344","type":"sort","hook":"Plan It: sort each source: solid to plan on, or shaky?","items":[{"id":"a","text":"a doctor's information"},{"id":"b","text":"a trusted adult's guidance"},{"id":"c","text":"verified facts you checked"},{"id":"d","text":"a rumour from a friend"},{"id":"e","text":"a confident locker-room 'fact'"},{"id":"f","text":"a random post online"}],"bins":[{"id":"solid","label":"Solid to plan on","valence":"pos"},{"id":"shaky","label":"Too shaky to trust","valence":"neg"}],"key":{"a":"solid","b":"solid","c":"solid","d":"shaky","e":"shaky","f":"shaky"},"relearn":"Plan on doctors, trusted adults and verified facts, not rumours.","persona":"any","source":"life-sim / sort","cat":"plan-future"},
  {"id":"pl-1345","type":"sort","hook":"Plan It: sort each line: a reason that's truly yours, or someone else's push?","items":[{"id":"a","text":"my goals come first"},{"id":"b","text":"I want to be truly ready"},{"id":"c","text":"my health is mine to protect"},{"id":"d","text":"because a friend dared me"},{"id":"e","text":"because 'everyone' is doing it"},{"id":"f","text":"because someone pressured me"}],"bins":[{"id":"mine","label":"My own reason","valence":"pos"},{"id":"push","label":"Someone else's push","valence":"uhoh"}],"key":{"a":"mine","b":"mine","c":"mine","d":"push","e":"push","f":"push"},"relearn":"Your own reasons are valid; pressure and dares are never your reasons.","persona":"Riya","source":"life-sim / sort","cat":"plan-future"},
  {"id":"pl-1346","type":"sort","hook":"Plan It: sort each step: part of making a plan, or part of dropping one?","items":[{"id":"a","text":"name the goal you want"},{"id":"b","text":"take the next small step"},{"id":"c","text":"adjust after a setback"},{"id":"d","text":"let the plan drift away"},{"id":"e","text":"react with no goal in mind"},{"id":"f","text":"give up at the first 'no'"}],"bins":[{"id":"make","label":"Builds the plan","valence":"pos"},{"id":"drop","label":"Drops the plan","valence":"neg"}],"key":{"a":"make","b":"make","c":"make","d":"drop","e":"drop","f":"drop"},"relearn":"Building a plan: name it, step, adjust, not drift, react, or quit.","persona":"any","source":"life-sim / sort","cat":"plan-future"},
  {"id":"pl-1350","cat":"ways-to-prevent","type":"sort","hook":"Sort each one: fully reliable, or not?","items":[{"id":"a","text":"Not having sex"},{"id":"b","text":"A condom used correctly"},{"id":"c","text":"Pulling out in time"},{"id":"d","text":"Washing after"},{"id":"e","text":"A 'safe day' guess"},{"id":"f","text":"Just hoping"}],"bins":[{"id":"rel","label":"Reliable","valence":"pos"},{"id":"unrel","label":"Not reliable","valence":"neg"}],"key":{"a":"rel","b":"rel","c":"unrel","d":"unrel","e":"unrel","f":"unrel"},"relearn":"Not having sex is fully reliable, a condom used right works well; pulling out, washing, 'safe days' and hoping don't.","persona":"any","source":"prevention overview"},
  {"id":"pl-1351","cat":"ways-to-prevent","type":"sort","hook":"Sort: also protects from STIs, or mainly pregnancy?","items":[{"id":"a","text":"Condoms"},{"id":"b","text":"Not having sex"},{"id":"c","text":"The pill"},{"id":"d","text":"An implant"},{"id":"e","text":"An injection"},{"id":"f","text":"An IUD"}],"bins":[{"id":"both","label":"Pregnancy + STIs","valence":"pos"},{"id":"preg","label":"Mainly pregnancy","valence":"neutral"}],"key":{"a":"both","b":"both","c":"preg","d":"preg","e":"preg","f":"preg"},"relearn":"Condoms and not having sex also cut STIs; most other methods mainly prevent pregnancy.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-1352","cat":"ways-to-prevent","type":"sort","hook":"Sort: a real method a doctor can explain, or not a method?","items":[{"id":"a","text":"Condoms"},{"id":"b","text":"The pill"},{"id":"c","text":"An implant"},{"id":"d","text":"A lucky charm"},{"id":"e","text":"Crossing your fingers"},{"id":"f","text":"Sitting a certain way"}],"bins":[{"id":"real","label":"Real method","valence":"pos"},{"id":"no","label":"Not a method","valence":"neg"}],"key":{"a":"real","b":"real","c":"real","d":"no","e":"no","f":"no"},"relearn":"Condoms, the pill and an implant are real methods a doctor explains; charms, luck and 'sitting right' aren't.","persona":"any","source":"prevention overview"},
  {"id":"pl-1353","cat":"ways-to-prevent","type":"sort","hook":"Sort: true about prevention, or false?","items":[{"id":"a","text":"Several methods exist"},{"id":"b","text":"A doctor can explain them"},{"id":"c","text":"It's a shared job"},{"id":"d","text":"There's only one method"},{"id":"e","text":"Methods never need correct use"},{"id":"f","text":"Luck counts as a method"}],"bins":[{"id":"t","label":"True","valence":"pos"},{"id":"f","label":"False","valence":"neg"}],"key":{"a":"t","b":"t","c":"t","d":"f","e":"f","f":"f"},"relearn":"Many methods exist, used correctly, and prevention is shared; 'one method', 'no correct use' and 'luck' are false.","persona":"any","source":"prevention overview"},
  {"id":"pl-1354","cat":"ways-to-prevent","type":"sort","hook":"Sort: whose job is preventing pregnancy?","items":[{"id":"a","text":"Both partners"},{"id":"b","text":"Both talk about it"},{"id":"c","text":"Both can carry protection"},{"id":"d","text":"Only the girl"},{"id":"e","text":"Only the boy"},{"id":"f","text":"Nobody's, leave it to luck"}],"bins":[{"id":"shared","label":"Shared, both","valence":"pos"},{"id":"wrong","label":"Not how it works","valence":"neg"}],"key":{"a":"shared","b":"shared","c":"shared","d":"wrong","e":"wrong","f":"wrong"},"relearn":"Prevention is both partners' job, talked about and shared; it's not one person's alone, and never luck's.","persona":"any","source":"shared responsibility"},
  {"id":"pl-1355","cat":"ways-to-prevent","type":"sort","hook":"Sort: a fact source you can trust, or not?","items":[{"id":"a","text":"A doctor"},{"id":"b","text":"A health worker"},{"id":"c","text":"A trusted adult"},{"id":"d","text":"A random group chat"},{"id":"e","text":"A 'my cousin said' rumour"},{"id":"f","text":"A confident classmate"}],"bins":[{"id":"trust","label":"Trust it","valence":"pos"},{"id":"check","label":"Check it first","valence":"uhoh"}],"key":{"a":"trust","b":"trust","c":"trust","d":"check","e":"check","f":"check"},"relearn":"Doctors, health workers and trusted adults give real facts; group chats, rumours and confident classmates need checking.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-1356","cat":"ways-to-prevent","type":"sort","hook":"Sort: helps prevent pregnancy, or just a myth that won't?","items":[{"id":"a","text":"A condom used right"},{"id":"b","text":"Not having sex"},{"id":"c","text":"A method a doctor set up"},{"id":"d","text":"Jumping afterwards"},{"id":"e","text":"Holding your breath"},{"id":"f","text":"A herbal 'cure' from a shop"}],"bins":[{"id":"works","label":"Actually works","valence":"pos"},{"id":"myth","label":"Just a myth","valence":"neg"}],"key":{"a":"works","b":"works","c":"works","d":"myth","e":"myth","f":"myth"},"relearn":"Condoms, not having sex and a doctor's method work; jumping, breath-holding and shop 'cures' are myths.","persona":"any","source":"prevention overview"},
  {"id":"pl-1357","cat":"ways-to-prevent","type":"sort","hook":"Sort: a smart move, or a risky shortcut?","items":[{"id":"a","text":"Ask a doctor which method fits"},{"id":"b","text":"Choose to wait"},{"id":"c","text":"Use a condom correctly"},{"id":"d","text":"Rely on pulling out"},{"id":"e","text":"Trust a 'safe days' app blindly"},{"id":"f","text":"Skip protection 'just once'"}],"bins":[{"id":"smart","label":"Smart move","valence":"pos"},{"id":"risk","label":"Risky shortcut","valence":"neg"}],"key":{"a":"smart","b":"smart","c":"smart","d":"risk","e":"risk","f":"risk"},"relearn":"Asking a doctor, waiting and correct condom use are smart; pulling out, blind apps and 'just once' are risky.","persona":"any","source":"prevention overview"},
  {"id":"pl-1358","cat":"ways-to-prevent","type":"sort","hook":"Sort: overview we teach, or a how-to we don't do here?","items":[{"id":"a","text":"Methods exist"},{"id":"b","text":"A doctor explains them"},{"id":"c","text":"Some also cut STIs"},{"id":"d","text":"Step-by-step instructions"},{"id":"e","text":"Graphic detail"},{"id":"f","text":"Pressure to use one now"}],"bins":[{"id":"ok","label":"Overview, yes","valence":"pos"},{"id":"nope","label":"Not here","valence":"neg"}],"key":{"a":"ok","b":"ok","c":"ok","d":"nope","e":"nope","f":"nope"},"relearn":"We keep it overview: methods exist, a doctor explains, some cut STIs; no step-by-steps, graphics or pressure.","persona":"any","source":"prevention overview"},
  {"id":"pl-1359","cat":"ways-to-prevent","type":"sort","hook":"Sort: Veer's locker-room 'facts', true or false?","items":[{"id":"a","text":"Condoms cut STIs too"},{"id":"b","text":"Not having sex is fully reliable"},{"id":"c","text":"A doctor can explain options"},{"id":"d","text":"Pulling out always works"},{"id":"e","text":"Real men don't use protection"},{"id":"f","text":"Only girls handle prevention"}],"bins":[{"id":"t","label":"True","valence":"pos"},{"id":"f","label":"False","valence":"neg"}],"key":{"a":"t","b":"t","c":"t","d":"f","e":"f","f":"f"},"relearn":"Condoms cut STIs, waiting is reliable, a doctor helps; 'pulling out always works' and the 'man' lines are false.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-1360","cat":"ways-to-prevent","type":"sort","hook":"Sort: makes prevention more likely to work, or less?","items":[{"id":"a","text":"Both partners agree on it"},{"id":"b","text":"Using a method correctly"},{"id":"c","text":"Getting real facts first"},{"id":"d","text":"Guessing 'safe' days"},{"id":"e","text":"Doing it 'just once' without"},{"id":"f","text":"Going by what a rumour said"}],"bins":[{"id":"more","label":"More likely to work","valence":"pos"},{"id":"less","label":"Less likely","valence":"neg"}],"key":{"a":"more","b":"more","c":"more","d":"less","e":"less","f":"less"},"relearn":"Agreeing, correct use and real facts help prevention work; guessing days, 'just once' and rumours undercut it.","persona":"any","source":"prevention overview"},
  {"id":"pl-1361","cat":"ways-to-prevent","type":"sort","hook":"Sort: a calm true line, or a scare/shame line we'd cut?","items":[{"id":"a","text":"Methods exist; a doctor explains them"},{"id":"b","text":"Waiting is fully respected"},{"id":"c","text":"Prevention is a shared job"},{"id":"d","text":"One slip ruins your whole life"},{"id":"e","text":"Only bad kids learn this"},{"id":"f","text":"You should be ashamed to ask"}],"bins":[{"id":"keep","label":"Calm + true","valence":"pos"},{"id":"cut","label":"Scare/shame, cut it","valence":"neg"}],"key":{"a":"keep","b":"keep","c":"keep","d":"cut","e":"cut","f":"cut"},"relearn":"Overview, respect and shared responsibility stay; 'ruins your life', 'bad kids' and shame get cut.","persona":"any","source":"prevention overview"},
  {"id":"pl-1362","cat":"ways-to-prevent","type":"sort","hook":"Sort: where does each question get its best answer?","items":[{"id":"a","text":"Which method suits me later?"},{"id":"b","text":"Is this rumour true?"},{"id":"c","text":"Is a method right for my body?"},{"id":"d","text":"Am I ready yet?"},{"id":"e","text":"What's my own pace?"},{"id":"f","text":"What feels right for me?"}],"bins":[{"id":"doc","label":"A doctor / adult","valence":"tell"},{"id":"you","label":"Only you","valence":"neutral"}],"key":{"a":"doc","b":"doc","c":"doc","d":"you","e":"you","f":"you"},"relearn":"Facts about methods go to a doctor or trusted adult; readiness and your own pace are yours alone.","persona":"any","source":"help-seeking + agency"},
  {"id":"pl-1363","cat":"ways-to-prevent","type":"sort","hook":"Sort: reliable everyday, or only a doctor's call?","items":[{"id":"a","text":"Choosing not to have sex"},{"id":"b","text":"Carrying a condom, knowing its use"},{"id":"c","text":"Talking with your partner first"},{"id":"d","text":"Starting the pill"},{"id":"e","text":"Getting an implant"},{"id":"f","text":"Getting an IUD fitted"}],"bins":[{"id":"self","label":"You can choose","valence":"pos"},{"id":"doc","label":"Needs a doctor","valence":"tell"}],"key":{"a":"self","b":"self","c":"self","d":"doc","e":"doc","f":"doc"},"relearn":"Waiting, condoms and talking are choices you can make; the pill, implant and IUD are set up by a doctor.","persona":"any","source":"prevention overview"},
  {"id":"pl-1364","cat":"ways-to-prevent","type":"sort","hook":"Sort: keeps STI protection in the picture, or drops it?","items":[{"id":"a","text":"A condom every time"},{"id":"b","text":"Not having sex"},{"id":"c","text":"Asking a doctor about STIs too"},{"id":"d","text":"Pill only, no condom"},{"id":"e","text":"Implant only, no condom"},{"id":"f","text":"Skipping the topic entirely"}],"bins":[{"id":"yes","label":"STI cover kept","valence":"pos"},{"id":"no","label":"STI cover dropped","valence":"uhoh"}],"key":{"a":"yes","b":"yes","c":"yes","d":"no","e":"no","f":"no"},"relearn":"Condoms, not having sex and asking a doctor keep STI cover; pill-only or implant-only don't, and skipping helps nobody.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-1365","cat":"ways-to-prevent","type":"match","hook":"Match each method to a plain, true fact.","pairs":[{"left":"Not having sex","right":"The one fully reliable choice"},{"left":"A condom","right":"Cuts pregnancy and STIs"},{"left":"The pill","right":"A doctor explains how it's used"},{"left":"Pulling out","right":"Unreliable on its own"},{"left":"Most other methods","right":"Mainly prevent pregnancy"}],"relearn":"Each method has clear facts; waiting leads, condoms also cut STIs, a doctor fills in the rest.","persona":"any","source":"prevention overview"},
  {"id":"pl-1366","cat":"ways-to-prevent","type":"match","hook":"Match the question to who answers it best.","pairs":[{"left":"Which method suits me later?","right":"A doctor"},{"left":"Is this claim actually true?","right":"A trusted adult"},{"left":"Could a method fit my body?","right":"A health worker"},{"left":"Am I ready for any of this?","right":"Only you"},{"left":"What's my own pace?","right":"You decide"}],"relearn":"Facts about methods go to a doctor or adult; readiness and your pace are yours.","persona":"any","source":"help-seeking"},
  {"id":"pl-1367","cat":"ways-to-prevent","type":"match","hook":"Match each move to what it really protects.","pairs":[{"left":"Using a condom right","right":"Pregnancy and STIs"},{"left":"Choosing to wait","right":"Pregnancy and STIs, fully"},{"left":"The pill","right":"Mainly pregnancy"},{"left":"An implant","right":"Mainly pregnancy, longer term"},{"left":"Hoping for luck","right":"Nothing at all"}],"relearn":"Condoms and waiting cover STIs too; most methods cover pregnancy; luck covers nothing.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-1368","cat":"ways-to-prevent","type":"match","hook":"Match the myth to the calm correction.","pairs":[{"left":"'Pulling out is safe'","right":"It's unreliable on its own"},{"left":"'It's only her job'","right":"It's a shared responsibility"},{"left":"'Washing after works'","right":"It doesn't prevent pregnancy"},{"left":"'Luck will do it'","right":"Luck isn't a method"},{"left":"'One method, that's all'","right":"Several real methods exist"}],"relearn":"Pulling out, washing and luck don't work; prevention is shared and several real methods exist.","persona":"any","source":"prevention overview"},
  {"id":"pl-1369","cat":"ways-to-prevent","type":"match","hook":"Match who does what in shared prevention.","pairs":[{"left":"Both partners","right":"Agree on the plan together"},{"left":"Either partner","right":"Can carry a condom"},{"left":"Both","right":"Can ask a doctor questions"},{"left":"Neither","right":"Should leave it to luck"},{"left":"You","right":"Decide your own readiness"}],"relearn":"Prevention is a shared plan both carry; nobody leaves it to luck, and readiness stays yours.","persona":"any","source":"shared responsibility"},
  {"id":"pl-1370","cat":"ways-to-prevent","type":"match","hook":"Match each thing to where it belongs in this game.","pairs":[{"left":"'Methods exist'","right":"Overview we teach"},{"left":"'A doctor explains them'","right":"The overview's heart"},{"left":"Step-by-step how-to","right":"Goes to a real doctor"},{"left":"Graphic detail","right":"Not here"},{"left":"Pressure to use one now","right":"Never our message"}],"relearn":"We keep prevention at overview level; the how-to is a doctor's, and pressure is never the message.","persona":"any","source":"prevention overview"},
  {"id":"pl-1371","cat":"ways-to-prevent","type":"match","hook":"Veer, match the brag to the real fact.","pairs":[{"left":"'Real men skip protection'","right":"Being informed is the strong move"},{"left":"'Prevention is her problem'","right":"It's both partners' job"},{"left":"'Pulling out never fails'","right":"It's unreliable on its own"},{"left":"'Everyone's already doing it'","right":"Most teens aren't"},{"left":"'Asking a doctor is weak'","right":"Asking is the smart move"}],"relearn":"The 'man' brags are myths; informed, shared, doctor-asking choices are the strong, smart ones.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-1372","cat":"ways-to-prevent","type":"match","hook":"Riya, match each worry to the calm true answer.","pairs":[{"left":"'Is there really only luck?'","right":"No, real methods exist"},{"left":"'Is waiting weird?'","right":"No, it's fully respected"},{"left":"'Who do I even ask?'","right":"A doctor or trusted adult"},{"left":"'Does a condom do two jobs?'","right":"Yes, pregnancy and STIs"},{"left":"'Is it all on me?'","right":"No, it's shared"}],"relearn":"Real methods exist, waiting is respected, a doctor can help, condoms do two jobs, and it's shared.","persona":"Riya","source":"facts over rumours"},
  {"id":"pl-1373","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"Pulling out in time is a safe way to prevent pregnancy.\"","myth":{"un":"Pulling out in time prevents pregnancy.","re":"Pulling out is unreliable; fluid before climax can carry sperm.","why":"It leaves a real chance every time, so it isn't a method to count on."},"relearn":"Withdrawal is unreliable on its own; it isn't a method to count on.","persona":"any","source":"prevention facts"},
  {"id":"pl-1374","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"Washing or douching afterwards stops pregnancy.\"","myth":{"un":"Washing afterwards stops pregnancy.","re":"Washing or douching does not prevent pregnancy; sperm may already be on the way.","why":"Once sperm meets egg, washing can't undo it, so it isn't prevention."},"relearn":"Washing afterwards doesn't prevent pregnancy; it isn't a method.","persona":"any","source":"de-stigmatise"},
  {"id":"pl-1375","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"There's basically only one way to prevent pregnancy.\"","myth":{"un":"There's only one way to prevent pregnancy.","re":"Several real methods exist, and a doctor can explain which fits.","why":"More options means more chance to find one that suits a person."},"relearn":"Several real prevention methods exist; a doctor explains the options.","persona":"any","source":"prevention overview"},
  {"id":"pl-1376","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"A condom only does one job.\"","myth":{"un":"A condom only prevents pregnancy.","re":"A condom used correctly prevents pregnancy and reduces STIs.","why":"It's the rare method that covers both, which is why it stands out."},"relearn":"A condom used correctly does two jobs: pregnancy and STIs.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-1377","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"The pill protects you from STIs too.\"","myth":{"un":"The pill protects against STIs.","re":"The pill mainly prevents pregnancy; condoms are what also cut STIs.","why":"Knowing which method does what helps a person choose wisely later."},"relearn":"The pill mainly prevents pregnancy; condoms also cut STIs.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-1378","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"Asking a doctor about methods means you're definitely going to.\"","myth":{"un":"Asking a doctor about methods means you're definitely going to have sex.","re":"Asking is just getting facts; it doesn't decide anything for you.","why":"Information is a tool you can hold without using, anytime."},"relearn":"Asking a doctor for facts decides nothing; it just gives you the truth.","persona":"Counsellor","source":"agency"},
  {"id":"pl-1379","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"Waiting isn't really a 'method', so it doesn't count.\"","myth":{"un":"Waiting isn't a real way to prevent pregnancy.","re":"Not having sex is the one fully reliable choice, and it's respected.","why":"It's the only option with no chance at all, which makes it the strongest."},"relearn":"Not having sex is fully reliable prevention and a respected choice.","persona":"any","source":"abstinence-respected"},
  {"id":"pl-1380","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"An app's 'safe days' are as good as any method.\"","myth":{"un":"An app's 'safe days' are as reliable as any method.","re":"Cycles vary and sperm live for days, so calendar-only timing is unreliable.","why":"If the dates can shift, a method built only on dates can't be trusted."},"relearn":"Calendar / 'safe days' timing alone is unreliable; cycles and sperm don't keep schedule.","persona":"any","source":"prevention facts"},
  {"id":"pl-1381","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"Carrying a condom means you're looking for trouble.\"","myth":{"un":"Carrying a condom means you're looking for trouble.","re":"Being prepared is responsible, whatever a person chooses to do or not do.","why":"Preparation isn't a plan; it's just not being caught unready."},"relearn":"Being prepared and informed is responsible, not reckless.","persona":"Veer","source":"de-stigmatise"},
  {"id":"pl-1382","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"Preventing pregnancy is the girl's job to sort out.\"","myth":{"un":"Preventing pregnancy is the girl's job.","re":"It's a shared responsibility; both partners look after it together.","why":"Both people are involved, so both share the care, fairly."},"relearn":"Preventing pregnancy is shared; both partners look after it.","persona":"any","source":"shared responsibility / equality"},
  {"id":"pl-1383","cat":"ways-to-prevent","type":"strike-rewrite","hook":"\"If a method ever fails, you're completely out of options.\"","myth":{"un":"If a method fails, there's nothing anyone can do.","re":"A doctor or health worker can advise on next steps and options.","why":"There's always someone to ask, so a slip-up isn't a dead end."},"relearn":"If something goes wrong, a doctor or health worker can help with next steps.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-1384","cat":"ways-to-prevent","type":"build","hook":"Build the calm, true 'options' summary.","prompt":"Assemble the four-part overview.","pieces":["not having sex is fully reliable","condoms also cut STIs","other real methods exist","a doctor explains them"],"mode":"assemble","key":["not having sex is fully reliable","condoms also cut STIs","other real methods exist","a doctor explains them"],"relearn":"Waiting leads, condoms cover STIs too, more methods exist, and a doctor fills in the details.","persona":"any","source":"prevention overview"},
  {"id":"pl-1385","cat":"ways-to-prevent","type":"build","hook":"Build the two jobs of a condom.","prompt":"Assemble what a condom does, used right.","pieces":["helps prevent pregnancy","helps reduce STIs","needs correct use every time","is easy to get"],"mode":"assemble","key":["helps prevent pregnancy","helps reduce STIs","needs correct use every time","is easy to get"],"relearn":"A condom, used correctly every time, prevents pregnancy and reduces STIs.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-1386","cat":"ways-to-prevent","type":"build","hook":"Order the steps to choose a method wisely.","prompt":"Put the smart-planning steps in order.","pieces":["get real facts, not rumours","ask a doctor or trusted adult","talk it over with your partner","decide together, no pressure"],"mode":"sequence","key":["get real facts, not rumours","ask a doctor or trusted adult","talk it over with your partner","decide together, no pressure"],"relearn":"Facts first, then a doctor, then your partner, then a shared, pressure-free choice.","persona":"any","source":"help-seeking + shared responsibility"},
  {"id":"pl-1387","cat":"ways-to-prevent","type":"build","hook":"Build the 'shared job' picture.","prompt":"Assemble who does what.","pieces":["both partners agree on it","either can carry protection","both can ask a doctor","neither leaves it to luck"],"mode":"assemble","key":["both partners agree on it","either can carry protection","both can ask a doctor","neither leaves it to luck"],"relearn":"Prevention is a shared plan: agreed together, carried by either, asked about by both, never left to luck.","persona":"any","source":"shared responsibility"},
  {"id":"pl-1388","cat":"ways-to-prevent","type":"build","hook":"Build the 'sort fact from rumour' habit.","prompt":"Assemble the verify-it routine.","pieces":["pause on the bold claim","ask: where's the proof?","check with a doctor or adult","trust the verified fact"],"mode":"sequence","key":["pause on the bold claim","ask: where's the proof?","check with a doctor or adult","trust the verified fact"],"relearn":"Pause, ask for proof, check with a doctor or adult, then trust the verified fact, not the rumour.","persona":"any","source":"facts over rumours"},
  {"id":"pl-1389","cat":"ways-to-prevent","type":"build","hook":"Build what stays 'overview' here (no how-to).","prompt":"Assemble the four things this game does say.","pieces":["methods exist","some also cut STIs","a doctor explains them","waiting is fully respected"],"mode":"assemble","key":["methods exist","some also cut STIs","a doctor explains them","waiting is fully respected"],"relearn":"We stay at overview: methods exist, some cut STIs, a doctor explains, and waiting is respected.","persona":"any","source":"prevention overview"},
  {"id":"pl-1390","cat":"ways-to-prevent","type":"build","hook":"Riya, build your 'I've got real facts' kit.","prompt":"Assemble the four facts to hold onto.","pieces":["waiting is fully reliable","condoms do two jobs","real methods exist","a doctor can explain them"],"mode":"assemble","key":["waiting is fully reliable","condoms do two jobs","real methods exist","a doctor can explain them"],"relearn":"Hold the real facts: waiting works, condoms do two jobs, methods exist, and a doctor can explain.","persona":"Riya","source":"facts over rumours"},
  {"id":"pl-1391","cat":"ways-to-prevent","type":"build","hook":"Order how prevention links to STI care.","prompt":"Put the protect-on-both-fronts steps in order.","pieces":["pick a method for pregnancy","keep a condom for STIs too","ask a doctor what else helps","check in over time"],"mode":"sequence","key":["pick a method for pregnancy","keep a condom for STIs too","ask a doctor what else helps","check in over time"],"relearn":"Cover pregnancy, keep a condom for STIs, ask a doctor what else helps, and check in over time.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-1392","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: knowing the methods doesn't mean you have to use any now. Steady?","prompt":"What do you think?","options":["Yes","Knowledge isn't pressure","Good to know"],"affirm":"Knowing your options is freedom; using them is a separate, future choice that's only yours.","relearn":"Knowing your options is separate from choosing to use them.","persona":"any","source":"agency"},
  {"id":"pl-1393","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: at your age the most reliable method is also the simplest, waiting. Fair?","prompt":"What do you think?","options":["Yes","Waiting is solid","Makes sense"],"affirm":"Waiting is the one fully reliable choice, and it's completely respected, never second-best.","relearn":"Not having sex is the most reliable choice and is fully valid.","persona":"any","source":"abstinence-respected"},
  {"id":"pl-1394","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: deciding on protection together, out loud, beats one person quietly assuming. Agree?","prompt":"What do you think?","options":["Yes","Talk it through","Decide together"],"affirm":"Talking openly about protection before sex keeps you both on the same page.","relearn":"Partners should discuss and agree on protection together, before sex.","persona":"any","source":"communication / planning ahead"},
  {"id":"pl-1395","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: getting facts from a doctor is private and totally normal. Reassuring?","prompt":"What do you think?","options":["Yes","Good to know","I'd ask"],"affirm":"A doctor's info is private, accurate and there to help; asking is smart, never shameful.","relearn":"A doctor's facts are private and helpful; asking is smart.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-1396","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: a condom doing two jobs at once is kind of neat. Worth remembering?","prompt":"What do you think?","options":["Yes","Two jobs, noted","Useful"],"affirm":"A condom used correctly covers both pregnancy and STIs, which is genuinely worth remembering.","relearn":"A condom used correctly covers both pregnancy and STIs.","persona":"any","source":"prevention / STIs (links g20)"},
  {"id":"pl-1397","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: 'pulling out' and 'hoping' aren't really plans. Land for you?","prompt":"What do you think?","options":["Yes","They're not methods","Makes sense"],"affirm":"A real plan beats a guess; pulling out and hoping leave a chance you don't have to take.","relearn":"Withdrawal and hoping aren't reliable plans.","persona":"any","source":"agency"},
  {"id":"pl-1398","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: learning this stuff is protection, not a push. Sit okay with you?","prompt":"What do you think?","options":["Yes","Facts protect","Good framing"],"affirm":"Knowing the facts helps people wait and stay safer; it's never a push toward anything.","relearn":"Knowing the facts is protection, not pressure.","persona":"any","source":"facts-as-protection"},
  {"id":"pl-1399","cat":"ways-to-prevent","type":"reflect","hook":"Veer: being the informed one is actually the strong move. Buy it?","prompt":"What do you think?","options":["Yes","Informed is strong","Fair point"],"affirm":"Being informed and prepared is the steady, strong move, whatever you choose to do or not do.","relearn":"Being informed is the strong, responsible move.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-1400","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: you can keep options in your back pocket for future-you. Calming?","prompt":"What do you think?","options":["Yes","Future-me, sorted","Good idea"],"affirm":"Carrying the facts now means future-you gets to choose calmly, on your own timeline.","relearn":"Knowing your options now keeps future-you in control.","persona":"any","source":"agency"},
  {"id":"pl-1401","cat":"ways-to-prevent","type":"reflect","hook":"Riya: 'I'll check with a doctor before I decide' is a strong line. Agree?","prompt":"What do you think?","options":["Yes","I'd say that","Solid line"],"affirm":"Choosing to verify before you decide is calm and self-respecting; the facts are yours to gather.","relearn":"Verifying with a doctor before deciding is a strong, self-led move.","persona":"Riya","source":"facts over rumours"},
  {"id":"pl-1402","cat":"ways-to-prevent","type":"reflect","hook":"Lensy: prevention is a tool that protects YOUR plans, not a rule on you. Resonate?","prompt":"What do you think?","options":["Yes","It's my tool","Like that"],"affirm":"Prevention and waiting are tools that guard the future you want; you're the one charting the path.","relearn":"Prevention is a tool that protects your own goals.","persona":"any","source":"agency / plan-future"},
  {"id":"pl-1403","cat":"ways-to-prevent","type":"role-play","hook":"A friend says \"pulling out always works, relax\".","setup":"Set the record straight, kindly. Say:","yourLine":[{"text":"\"It's actually unreliable, ask a doctor for real facts.\"","best":true},{"text":"\"Yeah, I guess you'd know.\""}],"relearn":"Pulling out is unreliable; real facts come from a doctor, not a confident friend.","persona":"Veer","source":"facts over rumours"},
  {"id":"pl-1404","cat":"ways-to-prevent","type":"role-play","hook":"Someone says \"prevention is the girl's problem, not mine\".","setup":"Name it as shared. Say:","yourLine":[{"text":"\"It's both our jobs, that's just how it works.\"","best":true},{"text":"\"...fine, whatever you say.\""}],"relearn":"Prevention is a shared job; saying so out loud is fair and normal.","persona":"any","source":"shared responsibility"},
  {"id":"pl-1405","cat":"ways-to-prevent","type":"role-play","hook":"A classmate laughs, \"only losers carry protection\".","setup":"Hold steady. Say:","yourLine":[{"text":"\"Being prepared isn't weak, it's just smart.\"","best":true},{"text":"\"Ha, yeah, that's lame, I guess.\""}],"relearn":"Being prepared and informed is smart, not weak; you can say so calmly.","persona":"Veer","source":"de-stigmatise"},
  {"id":"pl-1406","cat":"ways-to-prevent","type":"role-play","hook":"You want to know your options but feel awkward asking.","setup":"Ask anyway. Say:","yourLine":[{"text":"\"Can I ask you something private about staying safe?\"","best":true},{"text":"\"Never mind, it's probably a dumb question.\""}],"relearn":"No question is too embarrassing; a doctor or trusted adult is there for exactly this.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-1407","cat":"ways-to-prevent","type":"role-play","hook":"A partner says \"a condom kills the mood, skip it\".","setup":"Keep your line. Say:","yourLine":[{"text":"\"If we're doing this, we do it safely or not at all.\"","best":true},{"text":"\"Okay, I don't want to make it weird.\""}],"relearn":"Safety isn't negotiable to 'keep a mood'; 'safely or not at all' is a full answer.","persona":"Riya","source":"prevention / boundaries"},
  {"id":"pl-1408","cat":"ways-to-prevent","type":"role-play","hook":"A friend insists \"my cousin's trick stops pregnancy, trust me\".","setup":"Choose facts over the rumour. Say:","yourLine":[{"text":"\"I'd rather check that with a doctor than just trust it.\"","best":true},{"text":"\"Cool, sounds legit, I'll try it.\""}],"relearn":"A confident rumour isn't proof; verifying with a doctor beats trusting a 'trick'.","persona":"any","source":"facts over rumours"},
  {"id":"pl-1409","cat":"ways-to-prevent","type":"role-play","hook":"Someone says \"you don't need to know any of this yet\".","setup":"Claim the facts anyway. Say:","yourLine":[{"text":"\"Knowing the facts early just helps me stay safe.\"","best":true},{"text":"\"You're right, I'll just not think about it.\""}],"relearn":"Accurate facts are protection at any age; knowing early helps people stay safer.","persona":"any","source":"facts-as-protection"},
  {"id":"pl-1410","cat":"ways-to-prevent","type":"role-play","hook":"Riya wonders aloud, \"should we even talk about this together?\"","setup":"Open the shared conversation. Say:","yourLine":[{"text":"\"Yes, this is something we decide together, calmly.\"","best":true},{"text":"\"Maybe forget I said anything.\""}],"relearn":"Prevention is a shared decision; talking it over together is the grown-up move.","persona":"Riya","source":"shared responsibility"},
  {"id":"pl-1411","cat":"ways-to-prevent","type":"branch","hook":"You've got a real question about methods but don't know who to ask.","options":[{"text":"Ask a doctor or trusted adult","consequence":"You get private, accurate facts you can use.","outcome":"facts","best":true},{"text":"Just ask the group chat","consequence":"That's rumours, not facts; a doctor is the reliable route."}],"debrief":"Real questions about methods route to a doctor or trusted adult.","relearn":"Real questions about methods route to a doctor or trusted adult.","persona":"any","source":"help-seeking"},
  {"id":"pl-1412","cat":"ways-to-prevent","type":"branch","hook":"A partner pushes to skip the condom \"just this once\".","options":[{"text":"Hold your line: condom, or not at all","consequence":"You both stay protected and your boundary holds.","outcome":"safe","best":true},{"text":"Give in to avoid the awkwardness","consequence":"'Just once' still carries a real chance; your safety comes first."}],"debrief":"'Condom or not at all' is a complete, fair answer.","relearn":"'Condom or not at all' is a complete, fair answer.","persona":"Riya","source":"prevention / boundaries"},
  {"id":"pl-1413","cat":"ways-to-prevent","type":"branch","hook":"You hear a bold 'fact' about prevention and aren't sure it's true.","options":[{"text":"Check it with a doctor first","consequence":"You sort fact from rumour and act on the truth.","outcome":"verified","best":true},{"text":"Repeat it as true","consequence":"Passing on an unchecked claim just grows the rumour; verify first."}],"debrief":"Verify a bold claim against a reliable source before believing it.","relearn":"Verify a bold claim against a reliable source before believing it.","persona":"any","source":"facts over rumours"},
  {"id":"pl-1414","cat":"ways-to-prevent","type":"branch","hook":"You and a partner are deciding who handles prevention.","options":[{"text":"Make it a shared plan, both in","consequence":"You both own it, so nothing slips through.","outcome":"shared","best":true},{"text":"Leave it all to one person","consequence":"One-sided prevention drops things; it's meant to be shared."}],"debrief":"Prevention is a shared plan both partners own.","relearn":"Prevention is a shared plan both partners own.","persona":"any","source":"shared responsibility"},
  {"id":"pl-1415","cat":"ways-to-prevent","type":"branch","hook":"Plan It: your goal is to finish school and train for the team.","options":[{"text":"Let waiting and prevention protect the plan","consequence":"Your choices line up behind the future you want.","outcome":"on-track","best":true},{"text":"Ignore it and hope nothing happens","consequence":"Hoping isn't planning; an unplanned turn could change a lot."}],"debrief":"Today's choices ripple forward; prevention protects your own goals.","relearn":"Today's choices ripple forward; prevention protects your own goals.","persona":"any","source":"plan-future"},
  {"id":"pl-1416","cat":"ways-to-prevent","type":"branch","hook":"Veer's friends dare him to brag he 'never bothers with protection'.","options":[{"text":"Skip the brag, keep his own facts","consequence":"He stays informed, unbothered by a dare that proves nothing.","outcome":"self-led","best":true},{"text":"Brag along to fit in","consequence":"A brag isn't a fact; copying it just spreads a risky myth."}],"debrief":"'Real men skip protection' is a myth; being informed is the strong choice.","relearn":"'Real men skip protection' is a myth; being informed is the strong choice.","persona":"Veer","source":"norm-busting"},
  {"id":"pl-1417","cat":"ways-to-prevent","type":"branch","hook":"A method question feels too embarrassing to ask out loud.","options":[{"text":"Ask a doctor privately anyway","consequence":"You get a private, judgment-free, accurate answer.","outcome":"asked","best":true},{"text":"Stay silent and stay unsure","consequence":"Silence keeps you guessing; no question is too embarrassing."}],"debrief":"No question is too embarrassing; a doctor's answer is private and helpful.","relearn":"No question is too embarrassing; a doctor's answer is private and helpful.","persona":"Counsellor","source":"help-seeking"},
  {"id":"pl-1418","cat":"ways-to-prevent","type":"branch","hook":"You're tempted to rely on a 'safe days' app alone.","options":[{"text":"Treat it as a guess, not a guarantee","consequence":"You don't bet on dates alone; you keep a reliable method.","outcome":"careful","best":true},{"text":"Trust the app completely","consequence":"Cycles vary and sperm live for days; dates-only is unreliable."}],"debrief":"'Safe days' alone is unreliable; don't bet on dates.","relearn":"'Safe days' alone is unreliable; don't bet on dates.","persona":"any","source":"prevention facts"},
];

